val ScallopedShape = GenericShape { size, _ ->
    val width = size.width
    val height = size.height
    val centerX = width / 2f
    val centerY = height / 2f
    val outerRadius = minOf(width, height) / 2f
    val innerRadius = outerRadius * 0.85f
    val numPoints = 16 // 8 petals, so 16 points
    
    for (i in 0..numPoints) {
        val angle = (i.toDouble() / numPoints) * 2 * Math.PI
        val r = if (i % 2 == 0) outerRadius else innerRadius
        val x = centerX + r * Math.cos(angle).toFloat()
        val y = centerY + r * Math.sin(angle).toFloat()
        
        if (i == 0) moveTo(x, y)
        else lineTo(x, y)
    }
    close()
}

@Composable
fun AnimatedTabIcon(
    index: Int,
    isSelected: Boolean,
    tint: androidx.compose.ui.graphics.Color,
    modifier: Modifier = Modifier,
    coachProgressValue: Float = 0f,
    animationTrigger: Int = 0
) {
    val animProgress = remember { androidx.compose.animation.core.Animatable(0f) }

    LaunchedEffect(isSelected, animationTrigger) {
        if (index != 2) {
            if (isSelected) {
                animProgress.snapTo(0f)
                animProgress.animateTo(
                    targetValue = 1f,
                    animationSpec = androidx.compose.animation.core.tween(
                        durationMillis = 1800,
                        easing = androidx.compose.animation.core.LinearEasing
                    )
                )
            } else {
                animProgress.snapTo(0f)
            }
        }
    }

    val progress = animProgress.value

    Box(
        modifier = modifier.size(24.dp),
        contentAlignment = Alignment.Center
    ) {
        when (index) {
            0 -> {
                // Track: Water Drop Splash
                val dropScale = if (progress > 0f) {
                    if (progress < 0.2f) {
                        1f - (progress / 0.2f) * 0.15f
                    } else if (progress < 0.5f) {
                        0.85f + ((progress - 0.2f) / 0.3f) * 0.3f
                    } else {
                        1.15f - ((progress - 0.5f) / 0.5f) * 0.15f
                    }
                } else 1f

                val rippleAlpha = if (progress > 0.2f && progress < 0.8f) {
                    1f - ((progress - 0.2f) / 0.6f)
                } else 0f

                val rippleScale = if (progress > 0.2f) {
                    1f + ((progress - 0.2f) / 0.8f) * 1.5f
                } else 1f

                Box(contentAlignment = Alignment.Center) {
                    if (rippleAlpha > 0f) {
                        androidx.compose.foundation.Canvas(modifier = Modifier.size(24.dp)) {
                            drawCircle(
                                color = tint,
                                radius = (size.minDimension / 2f) * rippleScale,
                                alpha = rippleAlpha * 0.4f,
                                style = androidx.compose.ui.graphics.drawscope.Stroke(width = 1.5.dp.toPx())
                            )
                        }
                    }

                    Icon(
                        imageVector = androidx.compose.material.icons.Icons.Rounded.WaterDrop,
                        contentDescription = null,
                        tint = tint,
                        modifier = Modifier
                            .size(22.dp)
                            .graphicsLayer {
                                scaleX = dropScale
                                scaleY = dropScale
                            }
                    )
                }
            }
            1 -> {
                // Stats: Rising/growing bar chart columns
                androidx.compose.foundation.Canvas(modifier = Modifier.fillMaxSize()) {
                    val w = size.width
                    val h = size.height
                    
                    val barWidth = 4.dp.toPx()
                    val spacing = 3.dp.toPx()
                    val startX = (w - (3 * barWidth + 2 * spacing)) / 2f

                    val heightMultiplier1 = if (progress == 0f) 0.5f else {
                        if (progress < 0.3f) {
                            0.5f + (progress / 0.3f) * 0.4f
                        } else if (progress < 0.6f) {
                            0.9f - ((progress - 0.3f) / 0.3f) * 0.5f
                        } else {
                            0.4f + ((progress - 0.6f) / 0.4f) * 0.2f
                        }
                    }

                    val heightMultiplier2 = if (progress == 0f) 0.8f else {
                        if (progress < 0.15f) {
                            0.8f
                        } else if (progress < 0.45f) {
                            0.8f - ((progress - 0.15f) / 0.3f) * 0.5f
                        } else if (progress < 0.75f) {
                            0.3f + ((progress - 0.45f) / 0.3f) * 0.7f
                        } else {
                            1f - ((progress - 0.75f) / 0.25f) * 0.2f
                        }
                    }

                    val heightMultiplier3 = if (progress == 0f) 0.4f else {
                        if (progress < 0.3f) {
                            0.4f
                        } else if (progress < 0.6f) {
                            0.4f + ((progress - 0.3f) / 0.3f) * 0.5f
                        } else if (progress < 0.9f) {
                            0.9f - ((progress - 0.6f) / 0.3f) * 0.4f
                        } else {
                            0.5f + ((progress - 0.9f) / 0.1f) * 0.1f
                        }
                    }

                    val bar1H = h * 0.55f * heightMultiplier1
                    drawRoundRect(
                        color = tint,
                        topLeft = androidx.compose.ui.geometry.Offset(startX, h - bar1H),
                        size = androidx.compose.ui.geometry.Size(barWidth, bar1H),
                        cornerRadius = androidx.compose.ui.geometry.CornerRadius(1.5.dp.toPx(), 1.5.dp.toPx())
                    )

                    val bar2H = h * 0.85f * heightMultiplier2
                    drawRoundRect(
                        color = tint,
                        topLeft = androidx.compose.ui.geometry.Offset(startX + barWidth + spacing, h - bar2H),
                        size = androidx.compose.ui.geometry.Size(barWidth, bar2H),
                        cornerRadius = androidx.compose.ui.geometry.CornerRadius(1.5.dp.toPx(), 1.5.dp.toPx())
                    )

                    val bar3H = h * 0.45f * heightMultiplier3
                    drawRoundRect(
                        color = tint,
                        topLeft = androidx.compose.ui.geometry.Offset(startX + 2 * (barWidth + spacing), h - bar3H),
                        size = androidx.compose.ui.geometry.Size(barWidth, bar3H),
                        cornerRadius = androidx.compose.ui.geometry.CornerRadius(1.5.dp.toPx(), 1.5.dp.toPx())
                    )
                }
            }
            2 -> {
                // AI Coach: Google Bubbles Icon (Pixel/Gemini waving color bubbles)
                val colors = listOf(
                    androidx.compose.ui.graphics.Color(0xFF4285F4), // Blue
                    androidx.compose.ui.graphics.Color(0xFFEA4335), // Red
                    androidx.compose.ui.graphics.Color(0xFFFBBC05), // Yellow
                    androidx.compose.ui.graphics.Color(0xFF34A853)  // Green
                )

                androidx.compose.foundation.Canvas(modifier = Modifier.fillMaxSize()) {
                    val w = size.width
                    val h = size.height
                    
                    val cx = w / 2f
                    val cy = h / 2f
                    val dotRadius = 2.dp.toPx()
                    val gap = 2.5.dp.toPx()
                    val circleR = 4.5.dp.toPx()
                    val totalW = 4 * (2 * dotRadius) + 3 * gap
                    val lineStartX = cx - totalW / 2f + dotRadius
                    
                    val lineProgress = coachProgressValue

                    for (i in 0..3) {
                        val baseColor = colors[i]
                        val drawColor = if (isSelected) baseColor else tint

                        // Circle position
                        val angle = (i * Math.PI / 2) + (Math.PI / 4)
                        val targetCircleX = cx + circleR * kotlin.math.cos(angle).toFloat()
                        val targetCircleY = cy + circleR * kotlin.math.sin(angle).toFloat()

                        // Line position
                        val lineX = lineStartX + i * (2 * dotRadius + gap)
                        val lineY = cy

                        val currentX = targetCircleX + (lineX - targetCircleX) * lineProgress
                        val currentY = targetCircleY + (lineY - targetCircleY) * lineProgress

                        drawCircle(
                            color = drawColor,
                            radius = dotRadius,
                            center = androidx.compose.ui.geometry.Offset(currentX, currentY)
                        )
                    }
                }
            }
            3 -> {
                // Reminders: Dinging Bell
                val rotation = if (progress > 0f) {
                    val swing = kotlin.math.sin(progress * Math.PI * 4)
                    val decay = (1f - progress).coerceAtLeast(0f)
                    (swing * 22f * decay).toFloat()
                } else 0f

                val beatTimes = floatArrayOf(0.1f, 0.32f, 0.54f, 0.76f)
                val ripples = FloatArray(4) { i ->
                    val tPeak = beatTimes[i]
                    if (progress >= tPeak && progress < 0.95f) {
                        val age = progress - tPeak
                        val duration = 0.20f
                        if (age < duration) {
                            1f - (age / duration)
                        } else 0f
                    } else 0f
                }

                Box(contentAlignment = Alignment.Center) {
                    val hasActiveRipple = ripples.any { it > 0f }
                    if (hasActiveRipple) {
                        androidx.compose.foundation.Canvas(modifier = Modifier.size(24.dp)) {
                            for (i in 0..3) {
                                val rippleVal = ripples[i]
                                if (rippleVal > 0f) {
                                    val fraction = 1f - rippleVal
                                    val scale = 1.0f + fraction * 0.45f
                                    drawArc(
                                        color = tint,
                                        startAngle = -150f,
                                        sweepAngle = 120f,
                                        useCenter = false,
                                        alpha = rippleVal * 0.45f,
                                        style = androidx.compose.ui.graphics.drawscope.Stroke(width = 1.dp.toPx()),
                                        size = size * scale,
                                        topLeft = androidx.compose.ui.geometry.Offset((size.width - size.width * scale) / 2f, (size.height - size.height * scale) / 2f)
                                    )
                                }
                            }
                        }
                    }

                    Icon(
                        imageVector = androidx.compose.material.icons.Icons.Rounded.Notifications,
                        contentDescription = null,
                        tint = tint,
                        modifier = Modifier
                            .size(22.dp)
                            .graphicsLayer {
                                rotationZ = rotation
                                transformOrigin = androidx.compose.ui.graphics.TransformOrigin(0.5f, 0.1f)
                            }
                    )
                }
            }
            4 -> {
                // Settings: Rotating Gear
                val angle = if (progress > 0f) {
                    val t = progress
                    val easeOut = 1f - (1f - t) * (1f - t) * (1f - t)
                    val overshoot = if (t > 0.8f) {
                        val ot = (t - 0.8f) / 0.2f
                        kotlin.math.sin(ot * Math.PI).toFloat() * 6f * (1f - ot)
                    } else 0f
                    easeOut * 180f + overshoot
                } else 0f
                
                val view = androidx.compose.ui.platform.LocalView.current
                var lastHapticAngle by remember { mutableStateOf(0f) }
                LaunchedEffect(angle) {
                    if (progress == 0f) {
                        lastHapticAngle = 0f
                    } else {
                        // 180 degrees over 6 intervals = every 30 degrees
                        val currentStep = (angle / 30f).toInt() * 30f
                        if (currentStep > lastHapticAngle && currentStep <= 180f) {
                            lastHapticAngle = currentStep
                            // Strong tactile clicky haptic for each gear tooth
                            view.performHapticFeedback(android.view.HapticFeedbackConstants.KEYBOARD_TAP)
                        }
                    }
                }

                Icon(
                    imageVector = androidx.compose.material.icons.Icons.Rounded.Settings,
                    contentDescription = null,
                    tint = tint,
                    modifier = Modifier
                        .size(22.dp)
                        .graphicsLayer {
                            rotationZ = angle
                        }
                )
            }
        }
    }
}

fun LazyListScope.renderHapticsSettingsSection(
    viewModel: WaterViewModel,
    isEmailDeveloper: Boolean,
    hapticsSlidersEnabled: Boolean,
    hapticsButtonsEnabled: Boolean,
    hapticsGoalEnabled: Boolean,
    fireworksFeedbackEnabled: Boolean,
    customFireworkHapticsEnabled: Boolean,
    fireworkDurationMs: Int,
    fireworkGapMs: Int,
    fireworkStrength: Int,
    fireworkPatternPreset: VibrationPatternPreset,
    isFireworkHapticTestActive: Boolean,
    vibrationDurationMs: Int,
    vibrationGapMs: Int,
    vibrationStrength: Int,
    animationHapticStrength: Int,
    vibrationPatternPreset: VibrationPatternPreset,
    isHapticTestActive: Boolean,
    appLanguage: String,
    hapticMode: HapticMode
) {
    item {
        ChunkyHapticEngineRow(
            viewModel = viewModel,
            appLanguage = appLanguage
        )
    }

    item {
        val hapticMode by viewModel.hapticMode.collectAsStateWithLifecycle()
        if (hapticMode == HapticMode.ENHANCED) {
            EnhancedHapticStrengthRow(
                viewModel = viewModel,
                appLanguage = appLanguage
            )
        }
    }
    item {
        val titleVal = if (viewModel.appLanguage.value == "el") "Δονήσεις για Κουμπιά" else "Haptics for Buttons"
        val subtitleVal = if (viewModel.appLanguage.value == "el") "Παρέχει έναν καθαρό παλμό κατά το πάτημα των εικονιδίων και των κουμπιών." else "Provides a crisp pulse when tapping tab icons and interactive buttons."
        ChunkyIconSwitchRow(
            icon = Icons.Rounded.Notifications,
            title = titleVal,
            subtitle = subtitleVal,
            checked = hapticsButtonsEnabled,
            onCheckedChange = { viewModel.updateHapticsButtonsEnabled(it) }
        )
    }

    item {
        val hapticsTogglesEnabled = viewModel.hapticsTogglesEnabled.collectAsState().value
        val titleVal = if (viewModel.appLanguage.value == "el") "Δονήσεις για Διακόπτες" else "Haptics for Toggles"
        val subtitleVal = if (viewModel.appLanguage.value == "el") "Παρέχει ένα μηχανικό μοτίβο κατά την ενεργοποίηση ή απενεργοποίηση επιλογών." else "Provides a tactile pattern when switching toggles or simple switches."
        ChunkyIconSwitchRow(
            icon = Icons.Rounded.ToggleOff,
            title = titleVal,
            subtitle = subtitleVal,
            checked = hapticsTogglesEnabled,
            onCheckedChange = { viewModel.updateHapticsTogglesEnabled(it) }
        )
    }

    item {
        val titleVal = if (viewModel.appLanguage.value == "el") "Δονήσεις για Ολισθητές" else "Haptics for Sliders"
        val subtitleVal = if (viewModel.appLanguage.value == "el") "Ενεργοποιεί γρήγορα μηχανικά κλικ κατά τη ρύθμιση τιμών." else "Triggers rapid mechanical ticks while sliding values to fine-tune inputs."
        ChunkyIconSwitchRow(
            icon = Icons.Rounded.Settings,
            title = titleVal,
            subtitle = subtitleVal,
            checked = hapticsSlidersEnabled,
            onCheckedChange = { viewModel.updateHapticsSlidersEnabled(it) }
        )
    }

    item {
        val scrollHapticsEnabled by viewModel.scrollHapticsEnabled.collectAsStateWithLifecycle()
        val scrollHapticsPixels by viewModel.scrollHapticsPixels.collectAsStateWithLifecycle()
        val titleVal = if (viewModel.appLanguage.value == "el") "Δονήσεις για Κύλιση" else "Scroll Haptics"
        val subtitleVal = if (viewModel.appLanguage.value == "el") "Παρέχει απαλή απτική ανάδραση κατά την κύλιση ολισθητών ή λιστών." else "Provides light tactile feedback during scrolling/sliding of lists and sliders."
        Column {
            ChunkyIconSwitchRow(
                icon = Icons.Rounded.TouchApp,
                title = titleVal,
                subtitle = subtitleVal,
                checked = scrollHapticsEnabled,
                onCheckedChange = { viewModel.updateScrollHapticsEnabled(it) }
            )
            androidx.compose.animation.AnimatedVisibility(visible = scrollHapticsEnabled) {
                Column(modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp)) {
                    val isDark = MaterialTheme.colorScheme.background.luminance() < 0.5f
                    val textColor = if (isDark) androidx.compose.ui.graphics.Color.White else MaterialTheme.colorScheme.onSurface
                    Text(if (appLanguage == "el") "Απόσταση δόνησης (pixels): ${scrollHapticsPixels.toInt()}" else "Haptic distance (pixels): ${scrollHapticsPixels.toInt()}", style = MaterialTheme.typography.bodyMedium, fontWeight = FontWeight.Bold, color = textColor)
                    Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
                        CapsulePatternSlider(
                            value = scrollHapticsPixels,
                            onValueChange = { viewModel.updateScrollHapticsPixels(it) },
                            valueRange = 1f..500f,
                            triggerHaptic = { viewModel.triggerSliderHaptic() },
                            modifier = Modifier.weight(1f)
                        )
                        androidx.compose.animation.AnimatedVisibility(
                            visible = kotlin.math.abs(scrollHapticsPixels - 200f) > 0.1f,
                            enter = androidx.compose.animation.fadeIn() + androidx.compose.animation.expandHorizontally(),
                            exit = androidx.compose.animation.fadeOut() + androidx.compose.animation.shrinkHorizontally()
                        ) {
                            IconButton(
                                onClick = { 
                                    viewModel.updateScrollHapticsPixels(200f)
                                    viewModel.triggerButtonHaptic()
                                },
                                modifier = Modifier.padding(start = 8.dp).size(36.dp)
                            ) {
                                Icon(
                                    imageVector = Icons.Rounded.Restore, 
                                    contentDescription = "Reset",
                                    tint = MaterialTheme.colorScheme.primary
                                )
                            }
                        }
                    }
                    
                    val hapticMode by viewModel.hapticMode.collectAsStateWithLifecycle()
                    if (hapticMode == HapticMode.ENHANCED) {
                        Spacer(modifier = Modifier.height(16.dp))
                        val scrollHapticStrength by viewModel.enhancedScrollHapticStrength.collectAsStateWithLifecycle()
                        val formattedStrength = (scrollHapticStrength * 10).toInt() / 10f
                        val strengthLabel = if (appLanguage == "el") "Ένταση Δόνησης Κύλισης: $formattedStrength" else "Scrolling Haptics Strength: $formattedStrength"
                        Text(strengthLabel, style = MaterialTheme.typography.bodyMedium, fontWeight = FontWeight.Bold, color = textColor)
                        CapsulePatternSlider(
                            value = scrollHapticStrength,
                            onValueChange = { viewModel.updateEnhancedScrollHapticStrength(it) },
                            valueRange = 0.1f..2.0f,
                            triggerHaptic = { viewModel.triggerSliderHaptic() }
                        )
                    }
                }
            }
        }
    }

    item {
        val titleVal = if (viewModel.appLanguage.value == "el") "Δονήσεις για Επίτευξη Στόχου" else "Haptics for Goal Achieved"
        val subtitleVal = if (viewModel.appLanguage.value == "el") "Ενεργοποιεί έναν εορταστικό διπλό παλμό μόλις φτάσετε στο 100% του στόχου σας." else "Triggers an immersive celebratory double pulse exactly when you reach 100% of your daily intake."
        ChunkyIconSwitchRow(
            icon = Icons.Rounded.Star,
            title = titleVal,
            subtitle = subtitleVal,
            checked = hapticsGoalEnabled,
            onCheckedChange = { viewModel.updateHapticsGoalEnabled(it) }
        )
    }

    item {
        val overrideSwipeHapticsEnabled by viewModel.overrideSwipeHapticsEnabled.collectAsStateWithLifecycle()
        val titleVal = if (viewModel.appLanguage.value == "el") "Παράκαμψη Απτικών Σάρωσης" else "Override Swipe Haptics"
        val subtitleVal = if (viewModel.appLanguage.value == "el") "Εάν ενεργοποιηθεί, η σάρωση θα αναπαράγει τις μοναδικές απτικές δονήσεις κάθε καρτέλας." else "If active, swiping will play the unique tab-switching animations & chimes instead of generic snap feedback."
        ChunkyIconSwitchRow(
            icon = Icons.Rounded.Autorenew,
            title = titleVal,
            subtitle = subtitleVal,
            checked = overrideSwipeHapticsEnabled,
            onCheckedChange = { viewModel.updateOverrideSwipeHapticsEnabled(it) }
        )
    }

    item {
        val titleVal = if (viewModel.appLanguage.value == "el") "Συναισθηματική Απόκριση Πυροτεχνημάτων" else "Firework Release Feedback"
