@Composable
private fun WearDialogContainer(
    onDismissRequest: () -> Unit,
    content: @Composable ColumnScope.() -> Unit
) {
    val isFrostedGlassEnabled = LocalFrostedGlassEnabled.current
    val isBlurEffect = LocalBlurEffectEnabled.current
    val frostedTransparency = LocalFrostedGlassTransparency.current
    val generalCornerRadius = LocalGeneralCornerRadius.current
    
    val dialogBgColor = if (isFrostedGlassEnabled) {
        Color.Transparent
    } else {
        MaterialTheme.colorScheme.surface
    }
    
    val cornerRadius = maxOf(28, generalCornerRadius).dp
    val isDark = MaterialTheme.colorScheme.background.luminance() < 0.5f
    
    androidx.compose.ui.window.Dialog(
        onDismissRequest = onDismissRequest,
        properties = androidx.compose.ui.window.DialogProperties(usePlatformDefaultWidth = true)
    ) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 8.dp)
                .then(
                    if (isBlurEffect && !isFrostedGlassEnabled) Modifier.shadow(
                        elevation = 16.dp,
                        shape = RoundedCornerShape(cornerRadius),
                        ambientColor = Color.Black.copy(alpha = 0.2f),
                        spotColor = Color.Black.copy(alpha = 0.35f)
                    ) else Modifier
                )
                .clip(RoundedCornerShape(cornerRadius))
        ) {
            // Blurred background layer
            Box(
                modifier = Modifier
                    .matchParentSize()
                    .then(
                        if (isBlurEffect && !isFrostedGlassEnabled) Modifier.blur(
                            radius = 24.dp,
                            edgeTreatment = androidx.compose.ui.draw.BlurredEdgeTreatment(RoundedCornerShape(cornerRadius))
                        ) else Modifier
                    )
                    .background(
                        color = dialogBgColor,
                        shape = RoundedCornerShape(cornerRadius)
                    )
                    .then(
                        if (isFrostedGlassEnabled) Modifier.border(
                            width = 1.dp,
                            brush = GlassTheme.getCardBorderBrush(isDark),
                            shape = RoundedCornerShape(cornerRadius)
                        ) else Modifier
                    )
            )
            
            if (isFrostedGlassEnabled) {
                Box(
                    modifier = Modifier
                        .matchParentSize()
                        .background(
                            brush = GlassTheme.getCardBackgroundBrush(isDark, frostedTransparency),
                            shape = RoundedCornerShape(cornerRadius)
                        )
                )
            }
            
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(24.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(20.dp),
                content = content
            )
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun WaterTrackerScreen(viewModel: WaterViewModel, modifier: Modifier = Modifier) {
    val context = LocalContext.current
    
    val currentDate by viewModel.currentDate.collectAsStateWithLifecycle()
    val todayLogsRaw by viewModel.todayLogs.collectAsStateWithLifecycle()
    val todayLogs = remember(todayLogsRaw) { todayLogsRaw.filter { it.amountMl > 0 } }
    val totalIntakeToday by viewModel.totalIntakeToday.collectAsStateWithLifecycle()
