    val targetColorBottom = if (isOledActive) Color.Black else if (!isDark && keepLightBackgroundWhite) Color.White else {
        if (isDark) {
            Color(
                red = (themeBgColor.red * 0.94f + themePrimaryColor.red * 0.06f).coerceIn(0f, 1f),
                green = (themeBgColor.green * 0.94f + themePrimaryColor.green * 0.06f).coerceIn(0f, 1f),
                blue = (themeBgColor.blue * 0.94f + themePrimaryColor.blue * 0.06f).coerceIn(0f, 1f)
            )
        } else {
