        } else if (!isDark) {
            if (vividLightBoxesEnabled) {
                when (boxBgSource) {
                    "PALETTE" -> {
                        when (boxBgPaletteChoice) {
                            0 -> MaterialTheme.colorScheme.primaryContainer
                            1 -> MaterialTheme.colorScheme.secondaryContainer
                            2 -> MaterialTheme.colorScheme.tertiaryContainer
                            else -> MaterialTheme.colorScheme.primaryContainer
                        }
                    }
                    else -> MaterialTheme.colorScheme.primaryContainer
                }
            } else {
                MaterialTheme.colorScheme.surfaceVariant
            }
        } else {
            when (boxBgSource) {
                "PALETTE" -> {
                    when (boxBgPaletteChoice) {
                        0 -> MaterialTheme.colorScheme.primaryContainer
                        1 -> MaterialTheme.colorScheme.secondaryContainer
                        2 -> MaterialTheme.colorScheme.tertiaryContainer
                        else -> MaterialTheme.colorScheme.primaryContainer
                    }
                }
                else -> null
            }
        }

        CompositionLocalProvider(
            LocalGeneralCornerRadius provides generalCornerRadius,
            LocalBaseCardColor provides computedCustomBoxColor,
            LocalFrostedGlassEnabled provides isFrostedGlassEnabled,
