            LocalExperimentalHueShiftDuration provides viewModel.experimentalHueShiftDuration.collectAsStateWithLifecycle().value,
            LocalAppTheme provides appTheme,
            LocalSettingsDividerStyle provides viewModel.settingsDividerStyle.collectAsStateWithLifecycle().value,
            LocalSettingsDividerContrast provides "HIGH",
            LocalSettingsGapScale provides viewModel.settingsGapScale.collectAsStateWithLifecycle().value,
            LocalSettingsAdaptiveGrouping provides viewModel.settingsAdaptiveGrouping.collectAsStateWithLifecycle().value,
            LocalSettingsAdaptiveCornerRadius provides viewModel.settingsAdaptiveCornerRadius.collectAsStateWithLifecycle().value,
            LocalButtonHapticTrigger provides { viewModel.triggerButtonHaptic(currentLocalView) },
            LocalToggleHapticTrigger provides { reversed -> viewModel.triggerToggleHaptic(currentLocalView, reversed) },
            LocalDevFontWeight provides devFontWeight
        ) {
            val swipeScope = rememberCoroutineScope()
            val dragOffsetAnimatable = remember { androidx.compose.animation.core.Animatable(0f) }
            var isDragging by remember { mutableStateOf(false) }
            var dragOffsetValue by remember { mutableFloatStateOf(0f) }
            var hasSnappedHaptic by remember { mutableStateOf(false) }

            val swipeThreshold = 450f
            val isUnlatched = isDragging && kotlin.math.abs(dragOffsetValue) > swipeThreshold
            val visibleTabs = remember(remindersInSettings) {
                if (remindersInSettings) listOf(0, 1, 2, 4) else listOf(0, 1, 2, 3, 4)
            }
            val targetSwipeIndex = if (dragOffsetValue > 0f) {
                val currIdx = visibleTabs.indexOf(currentTab)
                if (currIdx != -1) {
                    val prevIdx = if (currIdx == 0) visibleTabs.size - 1 else currIdx - 1
                    visibleTabs[prevIdx]
                } else null
            } else if (dragOffsetValue < 0f) {
                val currIdx = visibleTabs.indexOf(currentTab)
                if (currIdx != -1) {
                    val nextIdx = if (currIdx == visibleTabs.size - 1) 0 else currIdx + 1
                    visibleTabs[nextIdx]
                } else null
            } else {
                null
            }

            val navBarStyle by viewModel.navBarStyle.collectAsStateWithLifecycle()
            var isNavBarVisible by remember { mutableStateOf(true) }

            LaunchedEffect(currentTab) {
                isNavBarVisible = true
            }

            val navBarNestedScrollConnection = remember {
                object : NestedScrollConnection {
                    override fun onPreScroll(
                        available: androidx.compose.ui.geometry.Offset,
                        source: NestedScrollSource
                    ): androidx.compose.ui.geometry.Offset {
                        val delta = available.y
                        if (delta < -8f) {
                            if (isNavBarVisible) {
                                isNavBarVisible = false
                            }
                        } else if (delta > 8f) {
                            if (!isNavBarVisible) {
                                isNavBarVisible = true
                            }
                        }
                        return androidx.compose.ui.geometry.Offset.Zero
                    }

                    override fun onPostScroll(
                        consumed: androidx.compose.ui.geometry.Offset,
                        available: androidx.compose.ui.geometry.Offset,
                        source: NestedScrollSource
                    ): androidx.compose.ui.geometry.Offset {
                        val delta = available.y
                        if (delta < -8f) {
                            if (isNavBarVisible) {
                                isNavBarVisible = false
                            }
                        } else if (delta > 8f) {
                            if (!isNavBarVisible) {
                                isNavBarVisible = true
                            }
                        }
                        return androidx.compose.ui.geometry.Offset.Zero
                    }
                }
            }

            Scaffold(
                contentWindowInsets = WindowInsets.statusBars,
                bottomBar = {
             // Floating Pill Navigation Bar from reference photos with gradual blur backdrop scrim
             val separateSettingsTabEnabled by viewModel.separateSettingsTabEnabled.collectAsStateWithLifecycle()
             val density = androidx.compose.ui.platform.LocalDensity.current
             val isDarkTheme = MaterialTheme.colorScheme.background.luminance() < 0.5f
             val scrimColor = if (isDarkTheme) {
                 if (isOledActive) Color.Black else MaterialTheme.colorScheme.background
             } else {
                 MaterialTheme.colorScheme.background
             }

             val imeBottomInsets = WindowInsets.ime.asPaddingValues().calculateBottomPadding()
             val isKeyboardActive = imeBottomInsets > 20.dp
             val showNavBar = isNavBarVisible && !isKeyboardActive

             val navBarTranslationY by androidx.compose.animation.core.animateFloatAsState(
                 targetValue = if (showNavBar) 0f else with(density) { 140.dp.toPx() },
                 animationSpec = androidx.compose.animation.core.spring(
                     dampingRatio = androidx.compose.animation.core.Spring.DampingRatioNoBouncy,
                     stiffness = androidx.compose.animation.core.Spring.StiffnessMediumLow
                 ),
                 label = "nav_bar_slide"
             )

             Box(
                 modifier = Modifier
                     .fillMaxWidth()
                     .graphicsLayer {
                         translationY = navBarTranslationY
                     },
                 contentAlignment = Alignment.BottomCenter
             ) {
                 // Soft feather gradient behind floating bottom bar without blackening or whitening
                 Box(
                     modifier = Modifier
                         .fillMaxWidth()
                         .height(80.dp)
                         .background(
                             brush = androidx.compose.ui.graphics.Brush.verticalGradient(
                                 colors = listOf(
                                     Color.Transparent,
                                     MaterialTheme.colorScheme.background.copy(alpha = 0.20f)
                                 )
                             )
                         )
                 )
                 val isThickMode = navBarStyle == "THICK" || navBarStyle == "FULL"
                 Row(
                     modifier = Modifier
                         .fillMaxWidth()
                         .padding(
                             horizontal = 16.dp,
                             vertical = 8.dp
                         )
                         .navigationBarsPadding(),
                     horizontalArrangement = Arrangement.spacedBy(if (isThickMode) 14.dp else 12.dp, Alignment.CenterHorizontally),
                     verticalAlignment = Alignment.CenterVertically
                 ) {
                  val isDark = MaterialTheme.colorScheme.background.luminance() < 0.5f
                  val isFrostedGlass = isFrostedGlassEnabled
                  val navBarAlpha = if (isFrostedGlass) 0f else 1.0f
                  val navBarShape = RoundedCornerShape(maxOf(0, navbarCornerRadius).dp)
                  val navBarBorderColor = if (!isDark) {
                      MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.6f)
                  } else {
                      MaterialTheme.colorScheme.outline.copy(alpha = 0.3f)
                  }
                  val navBarBorderBrush = if (isFrostedGlass) {
                      Brush.linearGradient(
                          colors = listOf(
                              Color.White.copy(alpha = if (isDark) 0.55f else 0.75f),
                              Color.White.copy(alpha = if (isDark) 0.20f else 0.35f),
                              Color.Transparent
                          )
                      )
                  } else null
                  val navBarBgBrush = if (isFrostedGlass) {
                      Brush.verticalGradient(
                          colors = listOf(
                              Color.White.copy(alpha = if (isDark) (frostedGlassTransparency * 0.22f).coerceIn(0.08f, 0.40f) else (frostedGlassTransparency * 0.35f).coerceIn(0.15f, 0.55f)),
                              Color.White.copy(alpha = if (isDark) (frostedGlassTransparency * 0.10f).coerceIn(0.04f, 0.25f) else (frostedGlassTransparency * 0.18f).coerceIn(0.06f, 0.32f))
                          )
                      )
                  } else null
                  Row(
                      modifier = Modifier
                          .drawPillDropShadow(
                              shape = navBarShape,
                              isDark = isDark,
                              elevationDp = 16.dp,
                              offsetYDp = 6.dp
                          )
                          .then(
                              if (navBarBgBrush != null) {
                                  Modifier.background(brush = navBarBgBrush, shape = navBarShape)
                              } else {
                                  Modifier.background(
                                      color = MaterialTheme.colorScheme.surface.copy(alpha = navBarAlpha),
                                      shape = navBarShape
                                  )
                              }
                          )
                          .then(
                              if (!isDark) {
                                  if (navBarBorderBrush != null) {
                                      Modifier.border(
                                          width = 1.dp,
                                          brush = navBarBorderBrush,
                                          shape = navBarShape
                                      )
                                  } else {
                                      Modifier.border(
                                          width = 1.dp,
                                          color = navBarBorderColor,
                                          shape = navBarShape
                                      )
                                  }
                              } else {
                                  Modifier
                              }
                          )
                          .padding(
                              horizontal = if (isThickMode) 12.dp else 8.dp,
                              vertical = if (isThickMode) 8.dp else 6.dp
                          ),
                      verticalAlignment = Alignment.CenterVertically,
                      horizontalArrangement = Arrangement.spacedBy(if (isThickMode) 6.dp else 4.dp)
                  ) {
                     val tabs = remember(separateSettingsTabEnabled, remindersInSettings, appLanguage) {
                         val list = mutableListOf<Triple<Int, String, androidx.compose.ui.graphics.vector.ImageVector>>()
                         list.add(Triple(0, if (appLanguage == "el") "Καταγραφή" else "Track", Icons.Rounded.WaterDrop))
                         list.add(Triple(1, if (appLanguage == "el") "Στατιστικά" else "Stats", Icons.Rounded.BarChart))
                         list.add(Triple(2, if (appLanguage == "el") "Σύμβουλος AI" else "AI Coach", Icons.Rounded.SmartToy))
                         if (!remindersInSettings) {
                             list.add(Triple(3, if (appLanguage == "el") "Ειδοποιήσεις" else "Reminders", Icons.Rounded.Notifications))
                         }
                         if (!separateSettingsTabEnabled) {
                             list.add(Triple(4, if (appLanguage == "el") "Ρυθμίσεις" else "Settings", Icons.Rounded.Settings))
                         }
                         list
                     }

                     val density = androidx.compose.ui.platform.LocalDensity.current
                     tabs.forEach { (index, label, icon) ->
                         val isSelected = currentTab == index
                         
                         val coachAnimState = if (index == 2) {
                             remember { androidx.compose.animation.core.Animatable(0f) }
                         } else null

                         if (coachAnimState != null) {
                             val triggerKey = tabClicksList[2]
                             LaunchedEffect(isSelected, triggerKey) {
                                 if (isSelected) {
                                     coachAnimState.snapTo(0f)
                                     coachAnimState.animateTo(
                                         targetValue = 1f,
                                         animationSpec = androidx.compose.animation.core.tween(
                                             durationMillis = 600,
                                             easing = androidx.compose.animation.core.FastOutSlowInEasing
                                         )
                                     )
                                 } else {
                                     coachAnimState.animateTo(
                                         targetValue = 0f,
                                         animationSpec = androidx.compose.animation.core.tween(
                                             durationMillis = 600,
                                             easing = androidx.compose.animation.core.FastOutSlowInEasing
                                         )
                                     )
                                 }
                             }
                         }

                         val isUnlatchedTarget = isUnlatched && index == targetSwipeIndex
                         val tabScale by androidx.compose.animation.core.animateFloatAsState(
                             targetValue = when {
                                 isUnlatchedTarget -> 1.20f
                                 isUnlatched && isSelected -> 0.85f
                                 else -> 1.0f
                             },
                             animationSpec = androidx.compose.animation.core.spring(
                                 dampingRatio = bounceDamping,
                                 stiffness = bounceStiffness
                             ),
                             label = "tab_scale_"
                         )

                         val tabTranslationY by androidx.compose.animation.core.animateFloatAsState(
                             targetValue = when {
                                 isUnlatchedTarget -> with(density) { -10.dp.toPx() }
                                 isUnlatched && isSelected -> with(density) { 2.dp.toPx() }
                                 isSelected -> 0f
                                 else -> 0f
                             },
                             animationSpec = androidx.compose.animation.core.spring(
                                 dampingRatio = bounceDamping,
                                 stiffness = bounceStiffness
                             ),
                             label = "tab_trans_y_"
                         )

                         val inactiveBgColor by androidx.compose.animation.animateColorAsState(
                             targetValue = Color.Transparent,
                             animationSpec = androidx.compose.animation.core.spring(
                                 stiffness = androidx.compose.animation.core.Spring.StiffnessLow
                             ),
                             label = "tab_inactive_bg_"
                         )

                         Box(
                             modifier = Modifier.graphicsLayer {
                                 scaleX = tabScale
                                 scaleY = tabScale
                                 translationY = tabTranslationY
                             },
                             contentAlignment = Alignment.Center
                         ) {
                             androidx.compose.animation.AnimatedContent(
                                 targetState = isSelected,
                                 label = "nav_tab_anim_",
                                 transitionSpec = {
                                     when (tabTransitionMode) {
                                         0 -> { // Sliding (Horizontal expansion)
                                             val slideSpec = spring<androidx.compose.ui.unit.IntOffset>(
                                                 stiffness = slideStiffness,
                                                 dampingRatio = slideDamping
                                             )
                                             val fadeSpec = spring<Float>(
                                                 stiffness = slideStiffness,
                                                 dampingRatio = slideDamping
                                             )
                                             (androidx.compose.animation.slideInHorizontally(slideSpec) { if (targetState) it / 2 else -it / 2 } + androidx.compose.animation.fadeIn(fadeSpec)).togetherWith(
                                                 androidx.compose.animation.slideOutHorizontally(slideSpec) { if (targetState) -it / 2 else it / 2 } + androidx.compose.animation.fadeOut(fadeSpec)
                                             ).using(androidx.compose.animation.SizeTransform(clip = false))
                                         }
                                         1 -> { // Bouncing (Spring expansion)
                                             val bounceSpec = spring<Float>(
                                                 stiffness = bounceStiffness,
                                                 dampingRatio = bounceDamping
                                             )
                                             (androidx.compose.animation.scaleIn(bounceSpec) + androidx.compose.animation.fadeIn(bounceSpec)).togetherWith(
                                                 androidx.compose.animation.scaleOut(bounceSpec) + androidx.compose.animation.fadeOut(bounceSpec)
                                             ).using(androidx.compose.animation.SizeTransform(clip = false))
                                         }
                                         else -> { // Fading
                                             val fadeSpec = spring<Float>(
                                                 stiffness = fadeStiffness,
                                                 dampingRatio = fadeDamping
                                             )
                                             (androidx.compose.animation.fadeIn(fadeSpec)).togetherWith(
                                                 androidx.compose.animation.fadeOut(fadeSpec)
                                             ).using(androidx.compose.animation.SizeTransform(clip = false))
                                         }
                                     }
                                 }
                             ) { selected ->
                                 if (selected) {
                                     // Active capsule element with name & icon side-by-side
                                     val activeContentColor = if (isDark) Color.Black else MaterialTheme.colorScheme.onPrimary
                                     Row(
                                         modifier = Modifier
                                             .background(
                                                 color = MaterialTheme.colorScheme.primary,
                                                 shape = RoundedCornerShape(100)
                                             )
                                             .clickable(
                                                 interactionSource = remember { androidx.compose.foundation.interaction.MutableInteractionSource() },
                                                 indication = androidx.compose.material3.ripple()
                                             ) {
                                                 tabClicksList = tabClicksList.mapIndexed { idx, count ->
                                                     if (idx == index) count + 1 else count
                                                 }
                                                 currentTab = index
                                                 settingsSubPage = null // reset sub-pages on tab change
                                                 if (index == 0) {
                                                     viewModel.setDate(viewModel.getCurrentDateString())
                                                 }
                                                 viewModel.triggerTabClickHaptic(index)
                                             }
                                             .padding(
                                                 horizontal = if (isThickMode) 16.dp else 13.dp,
                                                 vertical = if (isThickMode) 10.dp else 8.dp
                                             ),
                                         verticalAlignment = Alignment.CenterVertically,
                                         horizontalArrangement = Arrangement.spacedBy(if (isThickMode) 10.dp else 8.dp)
                                     ) {
                                         AnimatedTabIcon(
                                             index = index,
                                             isSelected = true,
                                             tint = activeContentColor,
                                             modifier = Modifier.size(if (isThickMode) 26.dp else 24.dp),
                                             coachProgressValue = coachAnimState?.value ?: 0f,
                                             animationTrigger = tabClicksList[index]
                                         )
                                         Text(
                                             text = label,
                                             color = activeContentColor,
                                             fontSize = if (isThickMode) 15.sp else 14.sp,
                                             fontWeight = FontWeight.Black
                                         )
                                     }
                                 } else {
                                     // Inactive simple transparent circle icon button
                                     Box(
                                         modifier = Modifier
                                             .requiredSize(if (isThickMode) 46.dp else 40.dp)
                                             .background(inactiveBgColor, shape = CircleShape)
                                             .clip(CircleShape)
                                             .clickable {
                                                 tabClicksList = tabClicksList.mapIndexed { idx, count ->
                                                     if (idx == index) count + 1 else count
                                                 }
                                                 currentTab = index
                                                 settingsSubPage = null // reset sub-pages on tab change
                                                 if (index == 0) {
                                                     viewModel.setDate(viewModel.getCurrentDateString())
                                                 }
                                                 viewModel.triggerTabClickHaptic(index)
                                             },
                                         contentAlignment = Alignment.Center
                                     ) {
                                         AnimatedTabIcon(
                                             index = index,
                                             isSelected = false,
                                             tint = if (isDark) Color.White else MaterialTheme.colorScheme.onSurfaceVariant,
                                             modifier = Modifier.size(if (isThickMode) 26.dp else 24.dp),
                                             coachProgressValue = coachAnimState?.value ?: 0f,
                                             animationTrigger = tabClicksList[index]
                                         )
                                     }
                                 }
                             }
                         }
                     }
                  }

                  if (separateSettingsTabEnabled) {
                     val index = 4
                     val isSelected = currentTab == index
                     val isUnlatchedTarget = isUnlatched && index == targetSwipeIndex
                     val tabScale by androidx.compose.animation.core.animateFloatAsState(
                         targetValue = when {
                             isUnlatchedTarget -> 1.20f
                             isUnlatched && isSelected -> 0.85f
                             else -> 1.0f
                         },
                         animationSpec = androidx.compose.animation.core.spring(
                             dampingRatio = bounceDamping,
                             stiffness = bounceStiffness
                         ),
                         label = "tab_scale_"
                     )

                     val tabTranslationY by androidx.compose.animation.core.animateFloatAsState(
                         targetValue = when {
                             isUnlatchedTarget -> with(density) { -10.dp.toPx() }
                             isUnlatched && isSelected -> with(density) { 2.dp.toPx() }
                             isSelected -> 0f
                             else -> 0f
                         },
                         animationSpec = androidx.compose.animation.core.spring(
                             dampingRatio = bounceDamping,
                             stiffness = bounceStiffness
                         ),
                         label = "tab_trans_y_"
                     )

                     val inactiveBgColor by androidx.compose.animation.animateColorAsState(
                         targetValue = Color.Transparent,
                         animationSpec = androidx.compose.animation.core.spring(
                             stiffness = androidx.compose.animation.core.Spring.StiffnessLow
                         ),
                         label = "tab_inactive_bg_"
                     )

                     val animatedBgColor by androidx.compose.animation.animateColorAsState(
                         targetValue = if (isSelected) MaterialTheme.colorScheme.primary else inactiveBgColor,
                         animationSpec = androidx.compose.animation.core.spring(
                             stiffness = androidx.compose.animation.core.Spring.StiffnessMedium
                         ),
                         label = "settings_bg_color"
                     )

                     val animatedIconColor by androidx.compose.animation.animateColorAsState(
                         targetValue = if (isSelected) {
                             if (isDark) Color.Black else MaterialTheme.colorScheme.onPrimary
                         } else {
                             if (isDark) Color.White else MaterialTheme.colorScheme.onSurfaceVariant
                         },
                         animationSpec = androidx.compose.animation.core.spring(
                             stiffness = androidx.compose.animation.core.Spring.StiffnessMedium
                         ),
                         label = "settings_icon_color"
                     )

                     Box(
                         modifier = Modifier
                             .requiredSize(if (isThickMode) 64.dp else 52.dp)
                             .graphicsLayer {
                                 scaleX = tabScale
                                 scaleY = tabScale
                                 translationY = tabTranslationY
                             }
                             .drawPillDropShadow(
                                 shape = CircleShape,
                                 isDark = isDark,
                                 elevationDp = 16.dp,
                                 offsetYDp = 6.dp
                             )
                             .then(
                                 if (navBarBgBrush != null) {
                                     Modifier.background(brush = navBarBgBrush, shape = CircleShape)
                                 } else {
                                     Modifier.background(
                                         color = MaterialTheme.colorScheme.surface.copy(alpha = navBarAlpha),
                                         shape = CircleShape
                                     )
                                 }
                             )
                             .then(
                                 if (!isDark) {
                                     if (navBarBorderBrush != null) {
                                         Modifier.border(
                                             width = 1.dp,
                                             brush = navBarBorderBrush,
                                             shape = CircleShape
                                         )
                                     } else {
                                         Modifier.border(
                                             width = 1.dp,
                                             color = navBarBorderColor,
                                             shape = CircleShape
                                         )
                                     }
                                 } else {
                                     Modifier
                                 }
                             )
                             .padding(if (isThickMode) 9.dp else 6.dp),
                         contentAlignment = Alignment.Center
                     ) {
                         Box(
                             modifier = Modifier
                                 .requiredSize(if (isThickMode) 46.dp else 40.dp)
                                 .background(animatedBgColor, shape = CircleShape)
                                 .clip(CircleShape)
                                 .clickable(
                                     interactionSource = remember { androidx.compose.foundation.interaction.MutableInteractionSource() },
                                     indication = androidx.compose.material3.ripple()
                                 ) {
                                     tabClicksList = tabClicksList.mapIndexed { idx, count ->
                                         if (idx == index) count + 1 else count
                                     }
                                     currentTab = index
                                     settingsSubPage = null
                                     viewModel.triggerTabClickHaptic(index)
                                 },
                             contentAlignment = Alignment.Center
                         ) {
                             AnimatedTabIcon(
                                 index = index,
                                 isSelected = isSelected,
                                 tint = animatedIconColor,
                                 modifier = Modifier.requiredSize(if (isThickMode) 26.dp else 24.dp),
                                 coachProgressValue = 0f,
                                 animationTrigger = tabClicksList[index]
                             )
                         }
                     }
                  }
              }
             }
          },
        floatingActionButton = {
        },
        containerColor = Color.Transparent,
        modifier = modifier.fillMaxSize().nestedScroll(navBarNestedScrollConnection).then(
            if (scaffoldBlur > 0.dp) Modifier.blur(
                radius = scaffoldBlur,
                edgeTreatment = androidx.compose.ui.draw.BlurredEdgeTreatment.Unbounded
            ) else Modifier
        )
    ) { padding ->
        val dragVal = if (isDragging) dragOffsetValue else dragOffsetAnimatable.value
        val tensionOffset = if (dragVal == 0f) 0f else {
            val sign = if (dragVal > 0f) 1f else -1f
            val absDrag = kotlin.math.abs(dragVal)
            val threshold = swipeThreshold
            if (absDrag > threshold) {
                // Release past the stuck latch: feel organic and smooth (tension gives way)
                val overage = absDrag - threshold
                sign * (220f * (1f - kotlin.math.exp(-threshold / 320f)) + overage * 0.70f)
            } else {
                // High tactile friction tension curve to make the page feel realistically heavy and stuck initially
                sign * (220f * (1f - kotlin.math.exp(-absDrag / 320f)))
            }
        }

        androidx.compose.animation.AnimatedContent(
            targetState = currentTab,
            label = "tab_transition",
            modifier = Modifier
                .fillMaxSize()
                .graphicsLayer {
                    translationX = tensionOffset
                }
                .then(
                    if (isSwipeTabNavEnabled) {
                        Modifier.pointerInput(Unit) {
                            detectHorizontalDragGestures(
                                onDragStart = { 
                                    isDragging = true
                                    dragOffsetValue = 0f
                                    swipeScope.launch {
                                        dragOffsetAnimatable.snapTo(0f)
                                    }
                                    hasSnappedHaptic = false
                                },
                                onDragEnd = {
                                    val finalVal = dragOffsetValue
                                    if (kotlin.math.abs(finalVal) > swipeThreshold) {
                                        val currIdx = visibleTabs.indexOf(currentTab)
                                        val nextTab = if (currIdx != -1) {
                                            if (finalVal > 0f) {
                                                val prevIdx = if (currIdx == 0) visibleTabs.size - 1 else currIdx - 1
                                                visibleTabs[prevIdx]
                                            } else {
                                                val nextIdx = if (currIdx == visibleTabs.size - 1) 0 else currIdx + 1
                                                visibleTabs[nextIdx]
                                            }
                                        } else {
                                            0
                                        }
                                        if (overrideSwipeHapticsEnabled) {
                                            viewModel.triggerTabClickHaptic(nextTab)
                                        } else {
                                            viewModel.triggerToggleSnapHaptic()
                                        }
                                        currentTab = nextTab
                                        settingsSubPage = null
                                    }
                                    isDragging = false
                                    // Smoothly spring-back to center after swipe release/abort
                                    swipeScope.launch {
                                        dragOffsetAnimatable.snapTo(finalVal)
                                        dragOffsetAnimatable.animateTo(
                                            targetValue = 0f,
                                            animationSpec = androidx.compose.animation.core.spring(
                                                dampingRatio = androidx.compose.animation.core.Spring.DampingRatioNoBouncy,
                                                stiffness = androidx.compose.animation.core.Spring.StiffnessMedium
                                            )
                                        )
                                        hasSnappedHaptic = false
                                    }
                                },
                                onDragCancel = {
                                    val finalVal = dragOffsetValue
                                    isDragging = false
                                    swipeScope.launch {
                                        dragOffsetAnimatable.snapTo(finalVal)
                                        dragOffsetAnimatable.animateTo(
                                            targetValue = 0f,
                                            animationSpec = androidx.compose.animation.core.spring(
                                                dampingRatio = androidx.compose.animation.core.Spring.DampingRatioNoBouncy,
                                                stiffness = androidx.compose.animation.core.Spring.StiffnessMedium
                                            )
                                        )
                                        hasSnappedHaptic = false
                                    }
                                },
                                onHorizontalDrag = { change, dragAmount ->
                                    val prevVal = dragOffsetValue
                                    dragOffsetValue += dragAmount
                                    
                                    val absDrag = kotlin.math.abs(dragOffsetValue)
                                    if (absDrag < swipeThreshold) {
                                        // Light continuous gear feedback vibe (every 12px steps) before snap
                                        val stepSize = 12f
                                        val lastStep = (kotlin.math.abs(prevVal) / stepSize).toInt()
                                        val currentStep = (absDrag / stepSize).toInt()
                                        if (currentStep != lastStep) {
                                            viewModel.triggerToggleLightHaptic()
                                        }
                                    }
                                    
                                    // Organic breakthrough trigger haptics when transcending the stuck barrier
                                    if (absDrag > swipeThreshold) {
                                        if (!hasSnappedHaptic) {
                                            viewModel.triggerToggleSnapHaptic() // Satisfying strong snap click
                                            hasSnappedHaptic = true
                                        }
                                    } else {
                                        if (hasSnappedHaptic) {
                                            hasSnappedHaptic = false
                                        }
                                    }
                                    change.consume()
                                }
                            )
                        }
                    } else Modifier
                ),
            transitionSpec = {
                val slideSpring = androidx.compose.animation.core.spring<androidx.compose.ui.unit.IntOffset>(
                    stiffness = slideStiffness,
                    dampingRatio = slideDamping
                )
                val slideFadeSpring = androidx.compose.animation.core.spring<Float>(
                    stiffness = slideStiffness,
                    dampingRatio = slideDamping
                )
                val bounceSlideSpring = androidx.compose.animation.core.spring<androidx.compose.ui.unit.IntOffset>(stiffness = bounceStiffness, dampingRatio = bounceDamping); val bounceSpring = androidx.compose.animation.core.spring<Float>(
                    stiffness = bounceStiffness,
                    dampingRatio = bounceDamping
                )
                val fadeSlideSpring = androidx.compose.animation.core.spring<androidx.compose.ui.unit.IntOffset>(stiffness = fadeStiffness, dampingRatio = fadeDamping); val fadeSpring = androidx.compose.animation.core.spring<Float>(
                    stiffness = fadeStiffness,
                    dampingRatio = fadeDamping
                )

                

                
                val isForward = targetState > initialState
                when (tabTransitionMode) {
                    0 -> { // Sliding (Horizontal spring transition)
                        val inOffsetX: (Int) -> Int = { if (isForward) it else -it }
                        (androidx.compose.animation.slideInHorizontally(
                            animationSpec = slideSpring,
                            initialOffsetX = inOffsetX
                        ) + androidx.compose.animation.fadeIn(animationSpec = slideFadeSpring)) togetherWith 
                     (androidx.compose.animation.slideOutHorizontally(
                         animationSpec = slideSpring,
                         targetOffsetX = { if (isForward) -it else it }
                     ) + androidx.compose.animation.fadeOut(animationSpec = slideFadeSpring)) using androidx.compose.animation.SizeTransform { _, _ ->
                         androidx.compose.animation.core.snap()
                      }
                    }
                    1 -> { // Bouncing (Bouncy Organic Horizontal Slide, no overlap)
                        val inOffsetX: (Int) -> Int = { if (isForward) it else -it }
                        val outOffsetX: (Int) -> Int = { if (isForward) -it else it }
                        (androidx.compose.animation.slideInHorizontally(
                            animationSpec = bounceSlideSpring,
                            initialOffsetX = inOffsetX
                        ) + androidx.compose.animation.scaleIn(bounceSpring, initialScale = 0.95f) + androidx.compose.animation.fadeIn(animationSpec = bounceSpring)) togetherWith 
                        (androidx.compose.animation.slideOutHorizontally(
                            animationSpec = bounceSlideSpring,
                            targetOffsetX = outOffsetX
                        ) + androidx.compose.animation.scaleOut(bounceSpring, targetScale = 0.95f) + androidx.compose.animation.fadeOut(animationSpec = bounceSpring)) using androidx.compose.animation.SizeTransform { _, _ ->
                            androidx.compose.animation.core.snap()
                        }
                    }
                    else -> { // Fading (Sequential alpha-only fade transition, no overlap, no sliding offsets)
                        androidx.compose.animation.fadeIn(
                            animationSpec = androidx.compose.animation.core.tween(
                                durationMillis = 200,
                                delayMillis = 200
                            )
                        ) togetherWith androidx.compose.animation.fadeOut(
                            animationSpec = androidx.compose.animation.core.tween(
                                durationMillis = 200
                            )
                        ) using androidx.compose.animation.SizeTransform { _, _ ->
                            androidx.compose.animation.core.snap()
                        }
                    }
                }
            }
        ) { targetTab ->
            if (targetTab == 2) {
                BoxWithConstraints(
