            val uriHandler = androidx.compose.ui.platform.LocalUriHandler.current

            androidx.compose.animation.AnimatedContent(
                targetState = settingsSubPage,
                label = "settings_subpage_transition",
                modifier = Modifier
                    .fillMaxSize()
                    .padding(top = padding.calculateTopPadding()),
                transitionSpec = {
                    val isForward = (when (targetState) {
                        null -> 0
                        "adjust_corner_radius" -> 2
                        else -> 1
                    }) > (when (initialState) {
                        null -> 0
                        "adjust_corner_radius" -> 2
                        else -> 1
                    })

                    val slideSpring = androidx.compose.animation.core.spring<androidx.compose.ui.unit.IntOffset>(
                        stiffness = slideStiffness,
                        dampingRatio = slideDamping
                    )
                    val slideFadeSpring = androidx.compose.animation.core.spring<Float>(
                        stiffness = slideStiffness,
                        dampingRatio = slideDamping
                    )
                    val bounceSlideSpring = androidx.compose.animation.core.spring<androidx.compose.ui.unit.IntOffset>(
                        stiffness = bounceStiffness,
                        dampingRatio = bounceDamping
                    )
                    val bounceSpring = androidx.compose.animation.core.spring<Float>(
                        stiffness = bounceStiffness,
                        dampingRatio = bounceDamping
                    )
                    val fadeSlideSpring = androidx.compose.animation.core.spring<androidx.compose.ui.unit.IntOffset>(
                        stiffness = fadeStiffness,
                        dampingRatio = fadeDamping
                    )
                    val fadeSpring = androidx.compose.animation.core.spring<Float>(
                        stiffness = fadeStiffness,
                        dampingRatio = fadeDamping
                    )

                    when (tabTransitionMode) {
                        0 -> { // Sliding
                            val inOffsetX: (Int) -> Int = { if (isForward) it else -it }
                            (androidx.compose.animation.slideInHorizontally(
                                animationSpec = slideSpring,
                                initialOffsetX = inOffsetX
                            ) + androidx.compose.animation.fadeIn(animationSpec = slideFadeSpring)) togetherWith 
