                                        val formatPattern = if (appLanguage == "el") "EEEE, d MMMM" else "EEEE, MMMM d"
                                        val outputFormat = SimpleDateFormat(formatPattern, locale)
                                        val date = inputFormat.parse(currentDate)
                                        date?.let { 
                                            val formatted = outputFormat.format(it)
                                            formatted.replaceFirstChar { char -> if (char.isLowerCase()) char.titlecase(locale) else char.toString() }
                                        } ?: (if (appLanguage == "el") "Σήμερα" else "Today")
                                    } catch (e: Exception) {
                                        if (appLanguage == "el") "Σήμερα" else "Today"
                                    }
                                }
                                Text(
                                    text = headerDateText,
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.Medium,
