                                    1 -> " (つ≧▽≦)つ"
                                    2 -> " ૮(˶ᵔ ᵕ ᵔ˶)っ"
                                    3 -> " (⊃＾▽＾)⊃"
                                    4 -> " <(◠‿◠)ﾉ"
                                    5 -> ""
                                    6 -> {
                                        val hour = java.util.Calendar.getInstance().get(java.util.Calendar.HOUR_OF_DAY)
                                        when {
                                            hour in 5..10 -> " (っ◕‿◕)っ"
                                            hour in 11..14 -> " (つ≧▽≦)つ"
                                            hour in 15..18 -> " ૮(˶ᵔ ᵕ ᵔ˶)っ"
                                            hour in 19..22 -> " (⊃＾▽＾)⊃"
                                            else -> " <(◠‿◠)ﾉ"
                                        }
                                    }
                                    else -> ""
                                }
                                
                                val faceAlpha = when (titleFaceVividness) {
                                    1 -> 0.2f
                                    2 -> 0.4f
                                    3 -> 0.6f
                                    4 -> 0.8f
                                    5 -> 1.0f
                                    else -> 1.0f
                                }

                                val titleFaceBaseColor = if (appTheme == "DYNAMIC") {
                                    when (titleFacePaletteRole) {
                                        "SECONDARY" -> MaterialTheme.colorScheme.secondary
                                        "TERTIARY" -> MaterialTheme.colorScheme.tertiary
                                        else -> MaterialTheme.colorScheme.primary
                                    }
                                } else {
                                    MaterialTheme.colorScheme.primary
                                }

                                val annotatedTitle = buildAnnotatedString {
                                    withStyle(
                                        SpanStyle(
                                            fontWeight = FontWeight.Medium,
                                            color = MaterialTheme.colorScheme.onBackground
                                        )
                                    ) {
                                        append("Pixel")
                                    }
                                    append(" ")
                                    withStyle(
                                        SpanStyle(
                                            fontWeight = FontWeight.Black,
                                            color = MaterialTheme.colorScheme.primary
                                        )
                                    ) {
                                        append("Water")
                                    }
                                    if (faceStr.isNotEmpty() && titleFacePosition == 0) {
                                        withStyle(
                                            SpanStyle(
                                                fontWeight = FontWeight.Normal,
                                                color = titleFaceBaseColor.copy(alpha = faceAlpha),
                                                fontSize = 20.sp
                                            )
                                        ) {
                                            append(faceStr)
                                        }
                                    }
                                }
                                
                                Text(
                                    text = annotatedTitle,
                                    fontSize = 28.sp,
                                    letterSpacing = (-0.5).sp,
                                    modifier = Modifier
                                        .testTag("pixel_water_title")
                                        .clip(RoundedCornerShape(8.dp))
                                        .clickable(
                                            interactionSource = remember { androidx.compose.foundation.interaction.MutableInteractionSource() },
                                            indication = null
