                                            if (targetTab == 0) {
                                                val now = System.currentTimeMillis()
                                                if (now - lastTitleTapTime > 1500L) {
                                                    titleTapCount = 1
                                                } else {
                                                    titleTapCount++
                                                }
                                                lastTitleTapTime = now

                                                if (titleTapCount == 5) {
                                                    val emailLower = googleAccountEmail.lowercase()
                                                    if (emailLower == "emmadrenou@gmail.com") {
                                                        viewModel.triggerWolfEasterEgg(context)
                                                    }
                                                    val userMessage = if (premiumEmails.containsKey(emailLower)) {
                                                        premiumEmails[emailLower]?.invoke(appLanguage) ?: ""
                                                    } else if (isDeveloper) {
                                                        if (appLanguage == "el") "Προγραμματιστής" else "Developer"
                                                    } else if (isGoogleLoggedIn) {
                                                        if (appLanguage == "el") "Premium Χρήστης 🌟" else "Premium User 🌟"
                                                    } else {
                                                        if (appLanguage == "el") "Pixel Water Premium 🌟" else "Pixel Water Premium 🌟"
                                                    }
                                                    if (userMessage.isNotEmpty()) {
                                                        android.widget.Toast.makeText(context, userMessage, android.widget.Toast.LENGTH_SHORT).show()
                                                    }
                                                } else if (titleTapCount >= 10) {
                                                    titleTapCount = 0
                                                    viewModel.updateDeveloperMode(true)
                                                    currentTab = 4
                                                    settingsSubPage = "developer_options"
                                                    val devMsg = if (appLanguage == "el") "Επιλογές Προγραμματιστή" else "Developer Options"
                                                    android.widget.Toast.makeText(context, devMsg, android.widget.Toast.LENGTH_SHORT).show()
                                                }
                                            }
                                        }
                                )
                            }
                        }

                        // Render the face on the top right corner if titleFacePosition == 1
                        if (targetTab != 2 && targetTab != 3 && targetTab != 4 && titleFacePosition == 1) {
                            val faceStr = when(titleFaceStyle) {
                                0 -> "(っ◕‿◕)っ"
                                1 -> "(つ≧▽≦)つ"
                                2 -> "૮(˶ᵔ ᵕ ᵔ˶)っ"
                                3 -> "(⊃＾▽＾)⊃"
                                4 -> "<(◠‿◠)ﾉ"
                                5 -> ""
                                6 -> {
                                    val hour = java.util.Calendar.getInstance().get(java.util.Calendar.HOUR_OF_DAY)
                                    when {
                                        hour in 5..10 -> "(っ◕‿◕)っ"
                                        hour in 11..14 -> "(つ≧▽≦)つ"
                                        hour in 15..18 -> "૮(˶ᵔ ᵕ ᵔ˶)っ"
                                        hour in 19..22 -> "(⊃＾▽＾)⊃"
                                        else -> "<(◠‿◠)ﾉ"
                                    }
                                }
                                else -> ""
                            }
                            val faceAlpha = when (titleFaceVividness) {
                                1 -> 0.2f
                                2 -> 0.4f
                                3 -> 0.6f
                                4 -> 0.8f
                                5 -> 1.0f
                                else -> 1.0f
                            }
                            if (faceStr.isNotEmpty()) {
                                val topCornerFaceColor = if (appTheme == "DYNAMIC") {
                                    when (titleFacePaletteRole) {
                                        "SECONDARY" -> MaterialTheme.colorScheme.secondary
                                        "TERTIARY" -> MaterialTheme.colorScheme.tertiary
                                        else -> MaterialTheme.colorScheme.primary
                                    }
                                } else {
                                    MaterialTheme.colorScheme.primary
                                }
                                Text(
                                    text = faceStr,
                                    fontSize = 22.sp,
                                    fontWeight = FontWeight.Normal,
                                    color = topCornerFaceColor.copy(alpha = faceAlpha),
                                    modifier = Modifier.padding(end = 4.dp, top = 16.dp)
                                )
                            }
                        }
                    }
                }
                }
            }

            when (targetTab) {
                0 -> {
                    // Navigation with Date Changer
                    item {
                        DateSelectorRow(
                            currentDate = currentDate,
