                            var isInsightExpanded by remember(aiSummary) { mutableStateOf(false) }
                            var lastTapTime by remember { mutableStateOf(0L) }
                            var tapCount by remember { mutableStateOf(0) }

                            val displayText = if (aiSummary.isBlank()) {
                                if (appLanguage == "el") "Δημιουργία έξυπνης σύνοψης..." else "Generating smart summary..."
