                "Extreme Caution" -> "Αυξημένη Προσοχή"
                "Caution" -> "Προσοχή"
                else -> "Καύσωνας"
            }
        } else {
            when (proposal.heatDangerLevel) {
                "Extreme Danger" -> "Extreme Danger"
                "Danger" -> "Danger"
                "Extreme Caution" -> "Extreme Caution"
                "Caution" -> "Caution"
                else -> "Extreme Heat"
            }
