                // Header Climate Info
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    Text(
                        text = (if (appLanguage == "el") "ΜΕΤΕΩΡΟΛΟΓΙΚΗ ΠΡΟΕΙΔΟΠΟΙΗΣΗ" else "CLIMATE ALERT").uppercase(),
