                    )
                    Text(
                        text = if (appLanguage == "el") "Ανίχνευση υψηλής θερμοκρασίας στο ${proposal.city}" else "High outdoor temperature detected in ${proposal.city}",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f),
                        textAlign = TextAlign.Center
                    )
                }

                // Grid layout with Thermal graphic
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
