    // Legal Disclaimer Agreement Startup Dialog
    if (!legalDisclaimerAccepted || forceShowDisclaimerDialog) {
        val isGreek = appLanguage == "el"
        var hasCheckedAgeAndTerms by remember { mutableStateOf(false) }
        val scrollState = rememberScrollState()

        // Dynamic screen expansion on scroll & interactive dragging!
        var targetFraction by remember { mutableStateOf(1.0f) }
        var isManuallyResized by remember { mutableStateOf(false) }

        androidx.compose.runtime.LaunchedEffect(scrollState.value) {
            if (!isManuallyResized && scrollState.value > 15) {
                targetFraction = 1.0f
            }
        }

        val fraction by androidx.compose.animation.core.animateFloatAsState(
            targetValue = targetFraction,
            animationSpec = androidx.compose.animation.core.spring(
                dampingRatio = androidx.compose.animation.core.Spring.DampingRatioNoBouncy,
                stiffness = androidx.compose.animation.core.Spring.StiffnessMedium
            ),
            label = "disclaimer_fraction"
        )
 
         androidx.compose.ui.window.Dialog(
             onDismissRequest = { 
                 if (forceShowDisclaimerDialog) {
                     viewModel.setForceShowDisclaimerDialog(false)
                 }
             },
             properties = androidx.compose.ui.window.DialogProperties(
                 usePlatformDefaultWidth = false,
                 dismissOnBackPress = forceShowDisclaimerDialog,
                 dismissOnClickOutside = forceShowDisclaimerDialog
             )
         ) {
             BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
                 val totalHeightPx = with(androidx.compose.ui.platform.LocalDensity.current) { maxHeight.toPx() }

                 Box(
                     modifier = Modifier.fillMaxSize(),
                     contentAlignment = Alignment.BottomCenter
                 ) {
                     Surface(
                         modifier = Modifier
                             .fillMaxWidth()
                             .fillMaxHeight(fraction),
                         shape = RoundedCornerShape(
                             topStart = 28.dp,
                             topEnd = 28.dp,
                             bottomStart = 0.dp,
                             bottomEnd = 0.dp
                         ),
                         color = MaterialTheme.colorScheme.surface,
                         tonalElevation = 8.dp
                     ) {
                         Column(
                             modifier = Modifier
                                 .fillMaxSize()
                                 .navigationBarsPadding() // Keep action buttons perfectly safe and readable above navigation bar
                                 .padding(start = 20.dp, end = 20.dp, top = 16.dp, bottom = 48.dp),
                             verticalArrangement = Arrangement.spacedBy(12.dp)
                         ) {
                             // Interactive drag handle area to resize
                             Box(
                                 modifier = Modifier
                                     .align(Alignment.CenterHorizontally)
                                     .padding(bottom = 8.dp)
                                     .size(width = 120.dp, height = 24.dp) // Generous, comfortable touch target
                                     .pointerInput(Unit) {
                                         detectDragGestures(
                                             onDragStart = {
                                                 isManuallyResized = true
                                             },
                                             onDrag = { change, dragAmount ->
                                                 change.consume()
                                                 val fractionChange = -dragAmount.y / totalHeightPx
                                                 targetFraction = (targetFraction + fractionChange).coerceIn(0.55f, 1.0f)
                                             }
                                         )
                                     },
                                 contentAlignment = Alignment.Center
                             ) {
                                 Box(
                                     modifier = Modifier
                                         .size(width = 40.dp, height = 4.dp)
                                         .background(
                                             color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.3f),
                                             shape = CircleShape
                                         )
                                 )
                             }
                    // Android 17 / Pixel Inspired Header
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(16.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Box(
                            modifier = Modifier
                                .size(56.dp)
                                .background(MaterialTheme.colorScheme.primaryContainer, shape = RoundedCornerShape(16.dp)),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Rounded.Gavel,
                                contentDescription = null,
                                tint = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.size(28.dp)
                            )
                        }

                        Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
                            Text(
                                text = if (isGreek) "Νομική Αποδοχή" else "Legal Agreement",
                                style = MaterialTheme.typography.headlineMedium.copy(
                                    fontWeight = FontWeight.Black,
                                    fontSize = 24.sp,
                                    letterSpacing = (-0.5).sp
                                ),
                                color = MaterialTheme.colorScheme.onSurface
                            )
                        }
                    }

                    Text(
                        text = if (isGreek) {
                            "Για να συνεχίσετε να χρησιμοποιείτε το Pixel Water, παρακαλούμε διαβάστε και αποδεχτείτε τις παρακάτω νομικές αποποιήσεις:"
                        } else {
                            "To continue using Pixel Water, please carefully review and accept the legal disclaimers below:"
                        },
                        fontSize = 13.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        lineHeight = 18.sp
                    )

                    HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f))

                    // Bento-style solid cards (No transparency)
                    Column(
                        modifier = Modifier
                            .weight(1f)
                            .verticalScroll(scrollState),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        // Card 1: Age limit
                        LegalTermsCard(
                            icon = Icons.Rounded.Person,
                            iconColor = MaterialTheme.colorScheme.primary,
                            title = if (isGreek) "1. Νόμιμη Ηλικία (18+)" else "1. Legal Age Requirement (18+)",
                            content = if (isGreek) {
                                "Όλοι οι χρήστες πρέπει να είναι 18+ ετών. Οι ανήλικοι απαιτούν ρητή αποδοχή και επίβλεψη από γονείς ή κηδεμόνες."
                            } else {
                                "All users must be 18 years or older. Minor users require explicit acceptance and supervision by parents or legal guardians."
                            }
                        )

                        // Card 2: Medical Disclaimer
                        LegalTermsCard(
                            icon = Icons.Rounded.HealthAndSafety,
                            iconColor = MaterialTheme.colorScheme.primary,
                            title = if (isGreek) "2. Ιατρική Αποποίηση" else "2. Medical Disclaimer",
                            content = if (isGreek) {
                                "Η εφαρμογή αυτή αποτελεί βοηθητικό εργαλείο καταγραφής και ενημέρωσης. Δεν παρέχει ιατρικές συμβουλές, διαγνώσεις ή θεραπεία."
                            } else {
                                "This app is a helper and educational tracking resource. It does not provide medical advice, diagnosis, or clinical treatment."
                            }
                        )

                        // Card 3: Overhydration Danger (Warm warning theme)
                        LegalTermsCard(
                            icon = Icons.Rounded.Warning,
                            iconColor = MaterialTheme.colorScheme.error,
                            containerColor = MaterialTheme.colorScheme.errorContainer.copy(alpha = 0.15f),
                            title = if (isGreek) "3. Κίνδυνος Υπερενυδάτωσης & Πίεσης Αίματος" else "3. Overhydration & Blood Pressure Warning",
                            content = if (isGreek) {
                                "Η υπερβολική ή εξαιρετικά γρήγορη κατανάλωση νερού μπορεί να προκαλέσει απότομη αύξηση της αρτηριακής πίεσης (υπερογκαιμική πίεση), αιμοαραίωση και υπονατριαιμία, που είναι επικίνδυνες για την υγεία. Καταναλώνετε υγρά με σύνεση."
                            } else {
                                "Drinking excessive amounts of water too rapidly can cause acute blood pressure surges (hypervolemic pressure), plasma dilution, and hyponatremia, which are dangerous to health. Please monitor your intake responsibly."
                            }
                        )

                        // Card 4: Limitation of Liability
                        LegalTermsCard(
                            icon = Icons.Rounded.Shield,
                            iconColor = MaterialTheme.colorScheme.secondary,
                            title = if (isGreek) "4. Περιορισμός Ευθύνης" else "4. Limitation of Liability",
                            content = if (isGreek) {
                                "Με τη χρήση της εφαρμογής συμφωνείτε ότι ο δημιουργός δεν φέρει καμία ευθύνη για τυχόν ζημίες. Αναλαμβάνετε 100% την προσωπική ευθύνη."
                            } else {
                                "By using this application, you agree that the developer is not liable for any health issues. You assume 100% personal responsibility."
                            }
                        )
                    }

                    Spacer(modifier = Modifier.height(4.dp))

                    // Android 17 style Chunky Clickable Agree Tile
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(20.dp))
                            .border(
                                width = 2.dp,
                                color = if (hasCheckedAgeAndTerms) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outlineVariant,
                                shape = RoundedCornerShape(20.dp)
                            )
                            .clickable { hasCheckedAgeAndTerms = !hasCheckedAgeAndTerms },
                        colors = CardDefaults.cardColors(
                            containerColor = if (hasCheckedAgeAndTerms) {
                                MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.2f)
                            } else {
                                MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
                            }
                        )
                    ) {
                        Row(
                            modifier = Modifier.padding(16.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Checkbox(
                                checked = hasCheckedAgeAndTerms,
                                onCheckedChange = { hasCheckedAgeAndTerms = it },
                                colors = CheckboxDefaults.colors(
                                    checkedColor = MaterialTheme.colorScheme.primary
                                )
                            )
                            Spacer(modifier = Modifier.width(12.dp))
                            Text(
                                text = if (isGreek) {
                                    "Βεβαιώνω ότι είμαι 18+ (ή έχω γονική συναίνεση) και συμφωνώ ρητά με όλους τους παραπάνω αναφερόμενους όρους και προϋποθέσεις ανεπιφύλακτα."
                                } else {
                                    "I certify that I am 18+ (or have parental consent) and I explicitly agree with all the above stated terms and conditions unconditionally."
                                },
                                style = MaterialTheme.typography.bodyMedium.copy(
                                    fontWeight = FontWeight.SemiBold,
                                    lineHeight = 18.sp
                                ),
                                color = MaterialTheme.colorScheme.onSurface
                            )
                        }
                    }

                    // Action Buttons
                    val context = androidx.compose.ui.platform.LocalContext.current
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        OutlinedButton(
                            onClick = {
                                viewModel.triggerButtonHaptic()
                                if (legalDisclaimerAccepted) {
                                    viewModel.setForceShowDisclaimerDialog(false)
                                } else {
                                    // Exit app completely!
                                    (context as? android.app.Activity)?.finishAffinity()
                                    java.lang.System.exit(0)
                                }
                            },
                            modifier = Modifier
                                .weight(1f)
                                .height(52.dp),
                            shape = RoundedCornerShape(26.dp)
                        ) {
                            Text(
                                text = if (isGreek) "Ακύρωση" else "Cancel",
                                fontWeight = FontWeight.Bold,
                                fontSize = 15.sp
                            )
                        }

                        Button(
                            onClick = {
                                viewModel.triggerButtonHaptic()
                                viewModel.acceptLegalDisclaimer()
                                viewModel.setForceShowDisclaimerDialog(false)
                            },
                            enabled = hasCheckedAgeAndTerms,
                            modifier = Modifier
                                .weight(1.5f)
                                .height(52.dp),
                            shape = RoundedCornerShape(26.dp),
                            colors = ButtonDefaults.buttonColors(
                                containerColor = MaterialTheme.colorScheme.primary,
                                contentColor = MaterialTheme.colorScheme.onPrimary
                            )
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                Text(
                                    text = if (isGreek) "Αποδοχή & Συνέχεια" else "Accept & Continue",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 15.sp
                                )
                                Icon(
                                    imageVector = Icons.Rounded.ArrowForward,
                                    contentDescription = null,
                                    modifier = Modifier.size(18.dp)
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}
}

    // Google Health setup window dialogue
    if (firstUseSetupCompleted && legalDisclaimerAccepted && !forceShowDisclaimerDialog) {
        if (!hasCompletedSetup) {
            GoogleHealthSetupWindow(
                viewModel = viewModel,
                isDismissible = false,
                onDismissRequest = {}
            )
        } else if (showSetupDialog) {
            GoogleHealthSetupWindow(
                viewModel = viewModel,
                isDismissible = true,
                onDismissRequest = {
                    showSetupDialog = false
                }
            )
        }
    }

    // Recently Added Feature Pop-Up Bubble Message
    if (showRecentlyAddedBubble && firstUseSetupCompleted && legalDisclaimerAccepted && !forceShowDisclaimerDialog && !showSetupDialog) {
        val isGreekLanguage = appLanguage == "el"
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(horizontal = 16.dp, vertical = 24.dp),
            contentAlignment = Alignment.BottomCenter
        ) {
            Card(
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surfaceColorAtElevation(8.dp)
                ),
                elevation = CardDefaults.cardElevation(defaultElevation = 12.dp),
                shape = RoundedCornerShape(24.dp),
                border = BorderStroke(1.5.dp, MaterialTheme.colorScheme.primary.copy(alpha = 0.6f)),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 72.dp)
                    .drawPillDropShadow(
                        shape = RoundedCornerShape(24.dp),
                        isDark = isDark,
                        elevationDp = 16.dp,
                        offsetYDp = 8.dp
                    )
            ) {
                Column(
                    modifier = Modifier.padding(18.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Row(
                            horizontalArrangement = Arrangement.spacedBy(10.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(36.dp)
                                    .background(MaterialTheme.colorScheme.primaryContainer, shape = CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Rounded.FitnessCenter,
                                    contentDescription = null,
                                    tint = MaterialTheme.colorScheme.primary,
                                    modifier = Modifier.size(20.dp)
                                )
                            }
                            Text(
                                text = if (isGreekLanguage) "Νέες Επιλογές Κρεατίνης! ✨" else "New Creatine Goal Options! ✨",
                                fontSize = 15.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                        }
                        IconButton(
                            onClick = {
                                viewModel.triggerButtonHaptic()
                                viewModel.dismissRecentlyAddedBubble()
                            },
                            modifier = Modifier.size(28.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Rounded.Close,
                                contentDescription = "Close",
                                tint = MaterialTheme.colorScheme.onSurfaceVariant,
                                modifier = Modifier.size(18.dp)
                            )
                        }
                    }

                    Text(
                        text = if (isGreekLanguage) {
                            "Μπορείτε πλέον να ορίσετε την ακριβή ημερήσια δόση κρεατίνης (3g, 5g, 10g ή προσαρμοσμένο slider) για ακόμα πιο ακριβή υπολογισμό του ημερήσιου στόχου νερού."
                        } else {
                            "You can now customize your exact daily creatine intake (3g, 5g, 10g or custom slider) to get even more accurate water goal recommendations for your body."
                        },
                        fontSize = 13.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        lineHeight = 18.sp
                    )

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.End,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        TextButton(
                            onClick = {
                                viewModel.triggerButtonHaptic()
                                viewModel.dismissRecentlyAddedBubble()
                            }
                        ) {
                            Text(
                                text = if (isGreekLanguage) "Αργότερα" else "Later",
                                fontSize = 13.sp,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                        Spacer(modifier = Modifier.width(8.dp))
                        Button(
                            onClick = {
                                viewModel.triggerButtonHaptic()
                                viewModel.dismissRecentlyAddedBubble()
                                showSetupDialog = true
                            },
                            shape = RoundedCornerShape(14.dp),
                            colors = ButtonDefaults.buttonColors(
                                containerColor = MaterialTheme.colorScheme.primary
                            )
                        ) {
                            Icon(
                                imageVector = Icons.Rounded.ArrowForward,
                                contentDescription = null,
                                modifier = Modifier.size(16.dp)
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Text(
                                text = if (isGreekLanguage) "Υπολογιστής Στόχου" else "Goal Calculator",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                }
            }
        }
    }

    if (showStorageBackupWindow) {
        StorageBackupWindow(
            viewModel = viewModel,
            appLanguage = appLanguage,
            isGoogleLoggedIn = isGoogleLoggedIn,
            googleAccountEmail = googleAccountEmail,
            googleAccountName = googleAccountName,
            onOpenGoogleLoginDialog = { showGoogleLoginDialog = true },
            onOpenFirebaseLoginDialog = { showFirebaseLoginDialog = true },
            onSignOutGoogle = { viewModel.signOutGoogle() },
            onBackupSuccess = { logCount, prefCount, file ->
                driveBackupLogCount = logCount
                driveBackupPrefCount = prefCount
                driveBackupFileName = file
                showDriveBackupDialog = true
            },
            onDismissRequest = {
                showStorageBackupWindow = false
            }
        )
    }

    // Google Account Picker Dialog
    if (showGoogleLoginDialog) {
        androidx.compose.ui.window.Dialog(
            onDismissRequest = { showGoogleLoginDialog = false }
        ) {
            Surface(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 8.dp),
                shape = RoundedCornerShape(24.dp),
                color = MaterialTheme.colorScheme.surface,
                tonalElevation = 6.dp,
                border = androidx.compose.foundation.BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f))
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(24.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    // Google Logo Branding Watermark icon
                    Box(
                        modifier = Modifier
                            .size(40.dp)
                            .background(Color.White, CircleShape)
                            .border(1.dp, Color(0xFFE0E0E0), CircleShape),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = "G",
                            color = Color(0xFF4285F4),
                            fontWeight = FontWeight.Black,
                            fontSize = 24.sp
                        )
                    }

                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        Text(
                            text = if (appLanguage == "el") "Σύνδεση Λογαριασμού" else "Connect Account",
                            fontWeight = FontWeight.Bold,
                            fontSize = 18.sp,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        Text(
                            text = if (appLanguage == "el") "για συνέχιση στο Pixel Water" else "to continue to Pixel Water",
                            fontSize = 13.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }

                    androidx.compose.material3.HorizontalDivider(
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f),
                        thickness = 1.dp
                    )

                    // Input Field
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        OutlinedTextField(
                            value = customGoogleEmailInput,
                            onValueChange = { customGoogleEmailInput = it },
                            label = { Text(if (appLanguage == "el") "Διεύθυνση Email" else "Email Address") },
                            placeholder = { Text("e.g. janedoe@gmail.com") },
                            singleLine = true,
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.fillMaxWidth()
                        )

                        // Google backups disclaimer
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(
                                    color = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.12f),
                                    shape = RoundedCornerShape(12.dp)
                                )
                                .padding(12.dp)
                        ) {
                            Text(
                                text = if (appLanguage == "el")
                                    "Η σύνδεση μέσω email ενεργοποιεί χειροκίνητη ή αυτόματη δημιουργία αντιγράφων ασφαλείας στο Google Drive."
                                    else "Connecting via email enables manual or automatic background synchronization to Google Drive.",
                                fontSize = 11.sp,
                                lineHeight = 15.sp,
                                color = MaterialTheme.colorScheme.primary
                            )
                        }
                    }

                    // Bottom CTA Action Buttons
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        TextButton(
                            onClick = {
                                showGoogleLoginDialog = false
                                viewModel.triggerButtonHaptic()
                            },
                            modifier = Modifier.weight(1f)
                        ) {
                            Text(if (appLanguage == "el") "Ακύρωση" else "Cancel", fontWeight = FontWeight.Bold)
                        }

                        Button(
                            onClick = {
                                val emailVal = customGoogleEmailInput.trim()
                                val isValidEmail = android.util.Patterns.EMAIL_ADDRESS.matcher(emailVal).matches()

                                if (isValidEmail) {
                                    viewModel.triggerButtonHaptic()
                                    viewModel.signInWithGoogle(emailVal, "Google User")
                                    showGoogleLoginDialog = false
                                } else {
                                    val errorMsg = if (appLanguage == "el") "Παρακαλώ εισάγετε έγκυρο email." else "Please enter a valid email."
                                    Toast.makeText(context, errorMsg, Toast.LENGTH_SHORT).show()
                                }
                            },
                            shape = RoundedCornerShape(12.dp),
                            modifier = Modifier.weight(1.2f)
                        ) {
                            Text(
                                text = if (appLanguage == "el") "Σύνδεση" else "Connect",
                                fontWeight = FontWeight.Black
                            )
                        }
                    }
                }
            }
        }
    }

    if (showFirebaseLoginDialog) {
        androidx.compose.ui.window.Dialog(
            onDismissRequest = { showFirebaseLoginDialog = false }
        ) {
            Surface(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 8.dp),
                shape = RoundedCornerShape(28.dp),
                color = MaterialTheme.colorScheme.surface,
                tonalElevation = 8.dp,
                border = androidx.compose.foundation.BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f))
            ) {
                var authTabMode by remember { mutableStateOf(0) } // 0: Passwordless, 1: Password
                var isLoginLoading by remember { mutableStateOf(false) }

                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(24.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    // Firebase Authentication badge
                    Row(
                        modifier = Modifier
                            .background(Color(0xFFDD2C00).copy(alpha = 0.15f), RoundedCornerShape(100))
                            .padding(horizontal = 14.dp, vertical = 6.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Rounded.LocalFireDepartment,
                            contentDescription = null,
                            tint = Color(0xFFDD2C00),
                            modifier = Modifier.size(16.dp)
                        )
                        Text(
                            text = if (appLanguage == "el") "Ταυτοποίηση Firebase" else "Firebase Authentication",
                            color = Color(0xFFDD2C00),
                            fontWeight = FontWeight.Bold,
                            fontSize = 11.sp
                        )
                    }

                    Column(
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        Text(
                            text = if (appLanguage == "el") "Πύλη Σύνδεσης" else "Account Connection Portal",
                            fontWeight = FontWeight.Black,
                            fontSize = 18.sp,
                            color = MaterialTheme.colorScheme.onSurface,
                            textAlign = androidx.compose.ui.text.style.TextAlign.Center
                        )
                        Text(
                            text = if (appLanguage == "el") 
                                "Ασφαλής συγχρονισμός και αντίγραφα Google Cloud" 
                                else "Secure synchronization and Google Cloud backups",
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                            textAlign = androidx.compose.ui.text.style.TextAlign.Center
                        )
                    }

                    // Elegant Auth Selector
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(MaterialTheme.colorScheme.onSurface.copy(alpha = 0.04f), RoundedCornerShape(50))
                            .padding(4.dp),
                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        listOf(
                            (if (appLanguage == "el") "Σύνδεσμος (Passwordless)" else "Magic Link") to 0,
                            (if (appLanguage == "el") "Κωδικός Πρόσβασης" else "Password") to 1
                        ).forEach { (label, idx) ->
                            val isSelected = authTabMode == idx
                            Box(
                                modifier = Modifier
                                    .weight(1f)
                                    .background(
                                        if (isSelected) MaterialTheme.colorScheme.surface else Color.Transparent,
                                        RoundedCornerShape(50)
                                    )
                                    .clickable {
                                        authTabMode = idx
                                        viewModel.triggerButtonHaptic()
                                    }
                                    .padding(vertical = 8.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    text = label,
                                    fontSize = 11.sp,
                                    fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                                    color = if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                        }
                    }

                    // Input fields and descriptions based on current tab
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        OutlinedTextField(
                            value = customGoogleEmailInput,
                            onValueChange = { customGoogleEmailInput = it },
                            label = { Text(if (appLanguage == "el") "Διεύθυνση Email" else "Email Address") },
                            placeholder = { Text("e.g. user@example.com") },
                            leadingIcon = {
                                Icon(
                                    imageVector = Icons.Rounded.Mail,
                                    contentDescription = null,
                                    tint = MaterialTheme.colorScheme.primary.copy(alpha = 0.7f),
                                    modifier = Modifier.size(20.dp)
                                )
                            },
                            singleLine = true,
                            shape = RoundedCornerShape(14.dp),
                            modifier = Modifier.fillMaxWidth()
                        )

                        if (authTabMode == 1) {
                            OutlinedTextField(
                                value = customGooglePasswordInput,
                                onValueChange = { customGooglePasswordInput = it },
                                label = { Text(if (appLanguage == "el") "Κωδικός" else "Password") },
                                placeholder = { Text("6+ characters") },
                                leadingIcon = {
                                    Icon(
                                        imageVector = Icons.Rounded.Lock,
                                        contentDescription = null,
                                        tint = MaterialTheme.colorScheme.primary.copy(alpha = 0.7f),
                                        modifier = Modifier.size(20.dp)
                                    )
                                },
                                singleLine = true,
                                visualTransformation = androidx.compose.ui.text.input.PasswordVisualTransformation(),
                                shape = RoundedCornerShape(14.dp),
                                modifier = Modifier.fillMaxWidth()
                            )

                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.End
                            ) {
                                TextButton(
                                    onClick = {
                                        viewModel.triggerButtonHaptic()
                                        val emailVal = customGoogleEmailInput.trim()
                                        if (emailVal.isBlank()) {
                                            val err = if (appLanguage == "el") "Παρακαλώ εισάγετε πρώτα το email σας παραπάνω." else "Please enter your email above first."
                                            Toast.makeText(context, err, Toast.LENGTH_SHORT).show()
                                        } else {
                                            viewModel.sendPasswordResetEmail(emailVal) { success, msg ->
                                                Toast.makeText(context, msg, Toast.LENGTH_LONG).show()
                                            }
                                        }
                                    },
                                    contentPadding = PaddingValues(horizontal = 4.dp, vertical = 2.dp),
                                    modifier = Modifier.height(28.dp)
                                ) {
                                    Text(
