                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        TextButton(
                            onClick = {
                                showFirebaseLoginDialog = false
                                viewModel.triggerButtonHaptic()
                            },
                            modifier = Modifier.weight(1f)
                        ) {
                            Text(if (appLanguage == "el") "Ακύρωση" else "Cancel", fontWeight = FontWeight.Bold)
                        }

                        if (isLoginLoading) {
                            androidx.compose.material3.CircularProgressIndicator(modifier = Modifier.size(24.dp))
                        }

                        Button(
                            enabled = !isLoginLoading,
                            onClick = {
                                val emailVal = customGoogleEmailInput.trim()
                                val isValidEmail = android.util.Patterns.EMAIL_ADDRESS.matcher(emailVal).matches()

                                if (isValidEmail) {
                                    isLoginLoading = true
                                    viewModel.triggerButtonHaptic()
                                    if (authTabMode == 0) {
                                        // Passwordless Email Link Auth
                                        viewModel.sendPasswordlessEmailLink(emailVal) { success, msg ->
                                            isLoginLoading = false
                                            Toast.makeText(context, msg, Toast.LENGTH_LONG).show()
                                            if (success) {
                                                showFirebaseLoginDialog = false
                                            }
                                        }
                                    } else {
                                        // Standard password registration and login
                                        val passVal = customGooglePasswordInput.trim()
                                        if (passVal.length >= 6) {
                                            viewModel.signInWithFirebase(emailVal, passVal) { success, msg ->
                                                isLoginLoading = false
                                                Toast.makeText(context, msg, Toast.LENGTH_SHORT).show()
                                                if (success) {
                                                    showFirebaseLoginDialog = false
                                                }
                                            }
                                        } else {
                                            isLoginLoading = false
                                            Toast.makeText(context, if (appLanguage == "el") "Ο κωδικός πρέπει να είναι >= 6 χαρακτήρες." else "Password should be >= 6 characters.", Toast.LENGTH_SHORT).show()
                                        }
                                    }
                                } else {
                                    Toast.makeText(context, if (appLanguage == "el") "Παρακαλώ εισάγετε έγκυρο email." else "Please enter a valid email address.", Toast.LENGTH_SHORT).show()
                                }
                            },
                            shape = RoundedCornerShape(14.dp),
                            modifier = Modifier.weight(1.3f),
