                val sdf = java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US)
                val monthsList = List(3) { idx ->
                    val startM = (endOfPeriodCal.clone() as java.util.Calendar).apply {
                        add(java.util.Calendar.DAY_OF_YEAR, -((idx + 1) * 30 - 1))
                    }
                    val endM = (endOfPeriodCal.clone() as java.util.Calendar).apply {
                        add(java.util.Calendar.DAY_OF_YEAR, -(idx * 30))
                    }
                    var sum = 0
                    for (d in 0 until 30) {
                        val tempCal = (startM.clone() as java.util.Calendar).apply { add(java.util.Calendar.DAY_OF_YEAR, d) }
                        sum += allLogs.filter { it.dateString == sdf.format(tempCal.time) }.sumOf { it.amountMl }
                    }
                    val avg = sum / 30
                    Triple(startM, endM, avg)
                }

                Card(
                    modifier = Modifier
                        .fillMaxWidth()
