@Composable
fun PremiumActiveSliderRow(
    icon: androidx.compose.ui.graphics.vector.ImageVector,
    title: String,
    valueText: String,
    value: Float,
    valueRange: ClosedFloatingPointRange<Float>,
    stepsCount: Int,
    onValueChange: (Float) -> Unit,
    triggerHaptic: () -> Unit = {},
    modifier: Modifier = Modifier
) {
    ChunkySettingCard(modifier = modifier) {
        Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Row(
                    modifier = Modifier.weight(1f),
                    horizontalArrangement = Arrangement.spacedBy(16.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Box(
                        modifier = Modifier
                            .size(40.dp)
                            .background(MaterialTheme.colorScheme.surfaceVariant, shape = CircleShape),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = icon,
                            contentDescription = null,
                            tint = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.size(20.dp)
                        )
                    }
                    Column {
                        Text(
                            text = title,
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                    }
                }
                
                Text(
                    text = valueText,
                    fontSize = 14.sp,
                    fontWeight = FontWeight.Black,
                    color = MaterialTheme.colorScheme.primary
                )
            }
            
            CapsulePatternSlider(
                value = value,
                onValueChange = onValueChange,
                valueRange = valueRange,
                stepsCount = stepsCount,
                triggerHaptic = triggerHaptic,
                modifier = Modifier.fillMaxWidth()
            )
        }
    }
}

@Composable
fun ResettableCapsuleSliderRow(
    title: String,
    value: Float,
    defaultValue: Float,
    valueRange: ClosedFloatingPointRange<Float>,
    onValueChange: (Float) -> Unit,
    triggerHaptic: () -> Unit,
    activeColor: Color? = null,
    unit: String = "",
    isInt: Boolean = false,
    modifier: Modifier = Modifier
) {
    var isDragged by remember { mutableStateOf(false) }
    // Show reset button if not currently dragging and value differs from default
    val showReset = !isDragged && kotlin.math.abs(value - defaultValue) > 0.001f

    Column(modifier = modifier, verticalArrangement = Arrangement.spacedBy(4.dp)) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = title,
                fontSize = 12.sp,
                fontWeight = FontWeight.Medium,
                color = MaterialTheme.colorScheme.onSurface
            )
            Row(verticalAlignment = Alignment.CenterVertically) {
                Text(
                    text = if (isInt) {
                        if (unit.isNotEmpty()) "${value.toInt()} $unit" else "${value.toInt()}"
                    } else {
                        if (unit.isNotEmpty()) String.format(java.util.Locale.US, "%.1f %s", value, unit) else String.format(java.util.Locale.US, "%.1f", value)
                    },
                    fontSize = 12.sp,
                    fontWeight = FontWeight.Bold,
                    color = activeColor ?: MaterialTheme.colorScheme.primary
                )
            }
        }
        
        Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
            CapsulePatternSlider(
                value = value,
                onValueChange = onValueChange,
                valueRange = valueRange,
                triggerHaptic = triggerHaptic,
                activeColor = activeColor,
                onDragStateChange = { isDragged = it },
                modifier = Modifier.weight(1f)
            )
            androidx.compose.animation.AnimatedVisibility(
                visible = showReset,
                enter = androidx.compose.animation.fadeIn() + androidx.compose.animation.expandHorizontally(),
                exit = androidx.compose.animation.fadeOut() + androidx.compose.animation.shrinkHorizontally()
            ) {
                IconButton(
                    onClick = { 
                        onValueChange(defaultValue)
                        triggerHaptic()
                    },
                    modifier = Modifier.padding(start = 8.dp).size(36.dp)
                ) {
                    Icon(
                        imageVector = Icons.Rounded.Restore, 
                        contentDescription = "Reset",
                        tint = activeColor ?: MaterialTheme.colorScheme.primary
                    )
                }
            }
        }
    }
}

@Composable
fun CapsulePatternSlider(
    value: Float,
    onValueChange: (Float) -> Unit,
    valueRange: ClosedFloatingPointRange<Float>,
    stepsCount: Int = 0,
    triggerHaptic: () -> Unit = {},
    activeColor: Color? = null,
    onDragStateChange: (Boolean) -> Unit = {},
    showDots: Boolean = true,
    modifier: Modifier = Modifier
) {
    val currentOnValueChange by androidx.compose.runtime.rememberUpdatedState(onValueChange)
    val currentValueRange by androidx.compose.runtime.rememberUpdatedState(valueRange)
    val currentStepsCount by androidx.compose.runtime.rememberUpdatedState(stepsCount)
    val currentOnDragStateChange by androidx.compose.runtime.rememberUpdatedState(onDragStateChange)
    val currentShowDots by androidx.compose.runtime.rememberUpdatedState(showDots)

    val isDark = MaterialTheme.colorScheme.background.luminance() < 0.5f
    val appTheme = LocalAppTheme.current

    val isTransparent = LocalTransparentComponentsEnabled.current
    val transLimit = LocalComponentsTransparency.current
    val tc = if (isTransparent) transLimit else 1f

    val activeColorSharp = activeColor ?: (if (isDark) Color(0xFF00BFA5) else MaterialTheme.colorScheme.primary)
    val inactiveColorSharp = if (isDark) Color(0xFF2C2D30) else Color(0xFFE2E4E8)
    val thumbColorSharp = activeColor ?: (if (isDark) Color.White else MaterialTheme.colorScheme.primary)

    val activeTrackColor = activeColorSharp.copy(alpha = activeColorSharp.alpha * tc)
    val inactiveTrackColor = inactiveColorSharp.copy(alpha = inactiveColorSharp.alpha * tc)
    val thumbColor = thumbColorSharp.copy(alpha = thumbColorSharp.alpha * tc)

    val activeTickColor = if (isDark) Color(0xFF2C2D30).copy(alpha = 0.6f * tc) else Color.White.copy(alpha = 0.6f * tc)
    val inactiveTickColor = if (isDark) Color.White.copy(alpha = 0.6f * tc) else Color(0xFF888B92).copy(alpha = 0.6f * tc)

    val rangeSpan = valueRange.endInclusive - valueRange.start
    val targetFraction = if (rangeSpan > 0f) {
        ((value - valueRange.start) / rangeSpan).coerceIn(0f, 1f)
    } else {
        0f
    }

    val fraction by animateFloatAsState(
        targetValue = targetFraction,
        animationSpec = spring(
            dampingRatio = Spring.DampingRatioMediumBouncy,
            stiffness = Spring.StiffnessLow
        ),
        label = "organic_slider_bounce"
    )

    val hapticStepIndex = remember(targetFraction, stepsCount) {
        if (stepsCount > 0) {
            val div = if (stepsCount > 1) stepsCount - 1 else 1
            kotlin.math.round(targetFraction * div).toInt()
        } else {
            kotlin.math.round(targetFraction * 27).toInt().coerceIn(0, 27)
        }
    }

    var isInitialized by remember { mutableStateOf(false) }
    LaunchedEffect(hapticStepIndex) {
        if (isInitialized) {
            triggerHaptic()
        } else {
            isInitialized = true
        }
    }

    BoxWithConstraints(
        modifier = modifier
            .fillMaxWidth()
            .height(36.dp)
    ) {
        val widthPx = constraints.maxWidth.toFloat()

        Canvas(
            modifier = Modifier
                .fillMaxSize()
                .pointerInput(widthPx) {
                    detectTapGestures { offset ->
                        if (widthPx > 0f) {
                            val rRange = currentValueRange
                            val rSpan = rRange.endInclusive - rRange.start
                            val thumbWidth = 4.dp.toPx()
                            val minThumbX = thumbWidth / 2f + 4.dp.toPx()
                            val maxThumbX = size.width - (thumbWidth / 2f) - 4.dp.toPx()
                            val frac = ((offset.x - minThumbX) / (maxThumbX - minThumbX)).coerceIn(0f, 1f)
                            var rawVal = rRange.start + frac * rSpan
                            val stepCountValue = currentStepsCount
                            if (stepCountValue > 0) {
                                val div = if (stepCountValue > 1) stepCountValue - 1 else 1
                                val stepSize = rSpan / div
                                val stepIdx = kotlin.math.round((rawVal - rRange.start) / stepSize).toInt()
                                rawVal = (rRange.start + stepIdx * stepSize).coerceIn(rRange)
                            }
                            currentOnValueChange(rawVal)
                        }
                    }
                }
                .pointerInput(widthPx) {
                    detectHorizontalDragGestures(
                        onDragStart = { currentOnDragStateChange(true) },
                        onDragEnd = { currentOnDragStateChange(false) },
                        onDragCancel = { currentOnDragStateChange(false) }
                    ) { change, _ ->
                        change.consume()
                        if (widthPx > 0f) {
                            val rRange = currentValueRange
                            val rSpan = rRange.endInclusive - rRange.start
                            val thumbWidth = 4.dp.toPx()
                            val minThumbX = thumbWidth / 2f + 4.dp.toPx()
                            val maxThumbX = size.width - (thumbWidth / 2f) - 4.dp.toPx()
                            val frac = ((change.position.x - minThumbX) / (maxThumbX - minThumbX)).coerceIn(0f, 1f)
                            var rawVal = rRange.start + frac * rSpan
                            val stepCountValue = currentStepsCount
                            if (stepCountValue > 0) {
                                val div = if (stepCountValue > 1) stepCountValue - 1 else 1
                                val stepSize = rSpan / div
                                val stepIdx = kotlin.math.round((rawVal - rRange.start) / stepSize).toInt()
                                rawVal = (rRange.start + stepIdx * stepSize).coerceIn(rRange)
                            }
                            currentOnValueChange(rawVal)
                        }
                    }
                }
        ) {
            val canvasWidth = size.width
            val canvasHeight = size.height

            val trackHeight = 24.dp.toPx()
            val trackY = (canvasHeight - trackHeight) / 2f
            val thumbWidth = 4.dp.toPx()
            val thumbHeight = 32.dp.toPx()
            val thumbY = (canvasHeight - thumbHeight) / 2f
            val gap = 4.dp.toPx()

            val minThumbX = thumbWidth / 2f + 4.dp.toPx()
            val maxThumbX = canvasWidth - (thumbWidth / 2f) - 4.dp.toPx()
            val thumbX = minThumbX + fraction * (maxThumbX - minThumbX)

            // 1. Draw Inactive Background Track on the right
            val inactiveStart = thumbX + gap
            val inactiveWidth = (canvasWidth - 2.dp.toPx()) - inactiveStart
            if (inactiveWidth > 0f) {
                drawRoundRect(
                    color = inactiveTrackColor,
                    topLeft = Offset(inactiveStart, trackY),
                    size = Size(inactiveWidth, trackHeight),
                    cornerRadius = CornerRadius(trackHeight / 2f, trackHeight / 2f)
                )
            }

            // 2. Draw Active Track on the left
            val activeWidth = (thumbX - gap) - 2.dp.toPx()
            if (activeWidth > 0f) {
                drawRoundRect(
                    color = activeTrackColor,
                    topLeft = Offset(2.dp.toPx(), trackY),
                    size = Size(activeWidth, trackHeight),
                    cornerRadius = CornerRadius(trackHeight / 2f, trackHeight / 2f)
                )
            }

            // 3. Draw Tick Marks (dots) inside the tracks (only on the inactive part)
            val stepCountValue = currentStepsCount
            if (currentShowDots && stepCountValue > 1) {
                val dotRadius = 2.dp.toPx()
                for (i in 0 until stepCountValue) {
                    val stepFraction = i.toFloat() / (stepCountValue - 1)
                    val stepX = minThumbX + stepFraction * (maxThumbX - minThumbX)

                    if (stepX > thumbX + gap) {
                        drawCircle(
                            color = inactiveTickColor,
                            radius = dotRadius,
                            center = Offset(stepX, canvasHeight / 2f)
                        )
                    }
                }
            }

            // 4. Draw Thumb/Cursor (vertical pill)
            drawRoundRect(
                color = thumbColor,
                topLeft = Offset(thumbX - thumbWidth / 2f, thumbY),
                size = Size(thumbWidth, thumbHeight),
                cornerRadius = CornerRadius(thumbWidth / 2f, thumbWidth / 2f)
            )
        }
    }
}

fun androidx.compose.foundation.lazy.LazyListScope.renderRemindersSection(
    viewModel: WaterViewModel,
    remindersEnabled: Boolean,
    remindersDestination: String,
    reminderInterval: Int,
    startHour: Int,
    endHour: Int,
    hasNotificationPermission: Boolean,
    launcher: androidx.activity.result.ActivityResultLauncher<String>,
    appLanguage: String,
    context: Context,
    watchCompanionDetected: Boolean
) {
    if (false) {
        item {
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 4.dp),
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.errorContainer
                ),
                shape = RoundedCornerShape(20.dp)
            ) {
                Row(
                    modifier = Modifier.padding(16.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Icon(
                        imageVector = Icons.Rounded.Warning,
                        contentDescription = "Permission missing icon",
                        tint = MaterialTheme.colorScheme.onErrorContainer
                    )
                    Spacer(modifier = Modifier.width(12.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = if (appLanguage == "el") "Λείπει η Άδεια Ειδοποιήσεων" else "Alert Permission Missing",
                            fontWeight = FontWeight.Bold,
                            fontSize = 14.sp,
                            color = MaterialTheme.colorScheme.onErrorContainer
                        )
                        Text(
