@Composable
fun ChunkySettingSwitch(
    checked: Boolean,
    onCheckedChange: (Boolean) -> Unit,
    modifier: Modifier = Modifier,
    enabled: Boolean = true
) {
    val hapticToggle = LocalToggleHapticTrigger.current
    val isTransparent = LocalTransparentComponentsEnabled.current
    val transLimit = LocalComponentsTransparency.current
    val tc = if (isTransparent) transLimit else 1f

    Switch(
        checked = checked,
        onCheckedChange = if (enabled) {
            {
                hapticToggle(!it)
                onCheckedChange(it)
            }
        } else null,
        modifier = modifier,
        enabled = enabled,
        thumbContent = {
            if (checked) {
                Icon(
                    imageVector = Icons.Rounded.Check,
                    contentDescription = null,
                    modifier = Modifier.size(16.dp),
                    tint = if (enabled) MaterialTheme.colorScheme.onPrimary.copy(alpha = tc) else MaterialTheme.colorScheme.onPrimary.copy(alpha = 0.5f * tc)
                )
            } else {
                Icon(
                    imageVector = Icons.Rounded.Close,
                    contentDescription = null,
                    modifier = Modifier.size(16.dp),
                    tint = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = tc)
                )
            }
        },
        colors = SwitchDefaults.colors(
            checkedThumbColor = MaterialTheme.colorScheme.primary.copy(alpha = tc),
            checkedTrackColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = tc.coerceAtMost(0.8f)),
            uncheckedThumbColor = MaterialTheme.colorScheme.outline.copy(alpha = tc),
            uncheckedTrackColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = tc.coerceAtMost(0.8f)),
            uncheckedBorderColor = Color.Transparent
        )
    )
}

