val LocalShowOutlines = staticCompositionLocalOf { true }
val LocalOutlineWidth = staticCompositionLocalOf { 1.dp }
val LocalFrostedGlassEnabled = staticCompositionLocalOf { false }
val LocalFrostedGlassTransparency = staticCompositionLocalOf { 0.55f }
val LocalTransparentComponentsEnabled = staticCompositionLocalOf { false }
val LocalComponentsTransparency = staticCompositionLocalOf { 0.35f }
val LocalBlurEffectEnabled = staticCompositionLocalOf { false }
val LocalExperimentalBlurRadius = staticCompositionLocalOf { 20f }
val LocalIsRainbowBorderEnabled = staticCompositionLocalOf { false }
val LocalExperimentalBorderWidth = staticCompositionLocalOf { 1.0f }
val LocalExperimentalCardScale = staticCompositionLocalOf { 1.0f }
val LocalExperimentalHueShiftDuration = staticCompositionLocalOf { 5f }
val LocalBaseCardColor = staticCompositionLocalOf<Color?> { null }
val LocalAppTheme = staticCompositionLocalOf { "DYNAMIC" }
val LocalSettingsDividerStyle = staticCompositionLocalOf { "STRAIGHT" }
val LocalSettingsDividerContrast = staticCompositionLocalOf { "HIGH" }
val LocalSettingsGapScale = staticCompositionLocalOf { 1.0f }
val LocalSettingsAdaptiveGrouping = staticCompositionLocalOf { true }
val LocalSettingsAdaptiveCornerRadius = staticCompositionLocalOf { 0 }
val LocalButtonHapticTrigger = staticCompositionLocalOf <() -> Unit> { {} }
val LocalToggleHapticTrigger = staticCompositionLocalOf <(Boolean) -> Unit> { {} }
