@Composable
fun appBorder(color: Color): androidx.compose.foundation.BorderStroke? {
    val isGapsMode = LocalSettingsDividerStyle.current == "GAPS"
    if (isGapsMode || !LocalShowOutlines.current) return null
    return androidx.compose.foundation.BorderStroke(LocalOutlineWidth.current, color)
}

@Composable
fun Modifier.appBorder(
    color: Color,
    shape: androidx.compose.ui.graphics.Shape
): Modifier {
    val show = LocalShowOutlines.current
    val w = LocalOutlineWidth.current
    val isGapsMode = LocalSettingsDividerStyle.current == "GAPS"
    return if (show && !isGapsMode) {
        this.border(w, color, shape)
    } else {
        this
    }
}

class FourLobedCardShape(
    val amplitude: Float = 0.26f
) : androidx.compose.ui.graphics.Shape {
    override fun createOutline(
        size: androidx.compose.ui.geometry.Size,
        layoutDirection: androidx.compose.ui.unit.LayoutDirection,
        density: androidx.compose.ui.unit.Density
    ): androidx.compose.ui.graphics.Outline {
        val w = size.width
        val h = size.height
        val cx = w / 2f
        val cy = h / 2f
        val maxRCos = 0.9846f
        val insetPx = with(density) { 1.5.dp.toPx() }
        val effectiveW = (w - insetPx * 2).coerceAtLeast(1f)
        val effectiveH = (h - insetPx * 2).coerceAtLeast(1f)
        val sx = (effectiveW / 2f) / maxRCos
        val sy = (effectiveH / 2f) / maxRCos

        val path = androidx.compose.ui.graphics.Path().apply {
            val pointsCount = 180
            for (i in 0 until pointsCount) {
                val angleRad = (i * 2.0 * Math.PI / pointsCount).toFloat()
                val r = 1f - amplitude * kotlin.math.cos(4f * angleRad)
                val x = cx + sx * r * kotlin.math.cos(angleRad)
                val y = cy + sy * r * kotlin.math.sin(angleRad)
                if (i == 0) {
                    moveTo(x, y)
                } else {
                    lineTo(x, y)
                }
            }
            close()
        }
        return androidx.compose.ui.graphics.Outline.Generic(path)
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is FourLobedCardShape) return false
        return amplitude == other.amplitude
    }

    override fun hashCode(): Int {
        return amplitude.hashCode()
    }
}

class SixLobedCardShape(
    val amplitude: Float = 0.14f
) : androidx.compose.ui.graphics.Shape {
    override fun createOutline(
        size: androidx.compose.ui.geometry.Size,
        layoutDirection: androidx.compose.ui.unit.LayoutDirection,
        density: androidx.compose.ui.unit.Density
    ): androidx.compose.ui.graphics.Outline {
        val w = size.width
        val h = size.height
        val cx = w / 2f
        val cy = h / 2f
        val insetPx = with(density) { 1.dp.toPx() }
        val maxR = (minOf(w, h) / 2f) - insetPx
        val baseRadius = maxR / (1f + amplitude)

        val path = androidx.compose.ui.graphics.Path().apply {
            val pointsCount = 240
            for (i in 0 until pointsCount) {
                val angleRad = (i * 2.0 * Math.PI / pointsCount).toFloat()
                // 6 lobes: peaks at 30, 90 (top), 150, 210, 270 (bottom), 330 deg; valleys at 0 (east), 180 (west)
                val wave = -kotlin.math.cos(6f * angleRad)
                val r = baseRadius * (1f + amplitude * wave)
                val x = cx + r * kotlin.math.cos(angleRad)
                val y = cy + r * kotlin.math.sin(angleRad)
                if (i == 0) {
                    moveTo(x, y)
                } else {
                    lineTo(x, y)
                }
            }
            close()
        }
        return androidx.compose.ui.graphics.Outline.Generic(path)
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is SixLobedCardShape) return false
        return amplitude == other.amplitude
    }

    override fun hashCode(): Int {
        return amplitude.hashCode()
    }
}

object GlassTheme {
    @Composable
    fun getCardBackgroundBrush(
        isDark: Boolean,
        transparency: Float = LocalFrostedGlassTransparency.current,
        surfaceColor: Color = MaterialTheme.colorScheme.surface,
        surfaceVariantColor: Color = MaterialTheme.colorScheme.surfaceVariant
    ): Brush {
        val targetAlpha = (0.35f * transparency).coerceIn(0.08f, 0.60f)
        val tintColor = if (isDark) {
            (if (surfaceColor == Color.Black) Color(0xFF1E2022) else surfaceColor).copy(alpha = targetAlpha)
        } else {
            surfaceColor.copy(alpha = targetAlpha)
        }
        return androidx.compose.ui.graphics.SolidColor(tintColor)
    }

    @Composable
    fun getCardBorderBrush(
        isDark: Boolean,
        primaryColor: Color = MaterialTheme.colorScheme.primary,
        outlineVariantColor: Color = MaterialTheme.colorScheme.outlineVariant,
        outlineColor: Color = MaterialTheme.colorScheme.outline
    ): Brush {
        val strokeColor = if (isDark) {
            Color.White.copy(alpha = 0.08f)
        } else {
            outlineVariantColor.copy(alpha = 0.15f)
        }
        return androidx.compose.ui.graphics.SolidColor(strokeColor)
    }

    @Composable
    fun getInnerSheenBrush(isDark: Boolean): Brush {
        return androidx.compose.ui.graphics.SolidColor(Color.Transparent)
    }

    @Composable
    fun getSubCardColor(
        isDark: Boolean,
        transparency: Float = LocalFrostedGlassTransparency.current
    ): Color {
        val targetAlpha = (0.28f * transparency).coerceIn(0.08f, 0.50f)
        return MaterialTheme.colorScheme.surfaceVariant.copy(alpha = targetAlpha)
    }

    @Composable
    fun getSubCardBorderColor(isDark: Boolean): Color {
        return if (isDark) Color.White.copy(alpha = 0.08f) else MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.15f)
    }
}

@Composable
fun ChunkyGapsLayout(
    modifier: Modifier = Modifier,
    containerColor: Color? = null,
    content: @Composable () -> Unit
) {
    val generalCornerRadius = LocalGeneralCornerRadius.current
    val baseCardColor = LocalBaseCardColor.current ?: MaterialTheme.colorScheme.surfaceVariant
    val expBorderWidth = LocalExperimentalBorderWidth.current.dp
    val isRainbowBorder = LocalIsRainbowBorderEnabled.current
    val isBlurEffect = LocalBlurEffectEnabled.current
    val isFrostedGlassEnabled = LocalFrostedGlassEnabled.current
    val frostedTransparency = LocalFrostedGlassTransparency.current
    val isDark = MaterialTheme.colorScheme.background.luminance() < 0.5f
    val outlineColor = MaterialTheme.colorScheme.outlineVariant
    val outlineWidth = LocalOutlineWidth.current
    val density = androidx.compose.ui.platform.LocalDensity.current
    val surfaceColor = MaterialTheme.colorScheme.surface
    
    val hueShiftDuration = LocalExperimentalHueShiftDuration.current
    val infiniteTransition = androidx.compose.animation.core.rememberInfiniteTransition(label = "rainbow_border_gaps")
    val hueShift by infiniteTransition.animateFloat(
        initialValue = 0f,
        targetValue = 360f,
        animationSpec = androidx.compose.animation.core.infiniteRepeatable(
            animation = androidx.compose.animation.core.tween((hueShiftDuration * 1000).toInt().coerceAtLeast(100), easing = androidx.compose.animation.core.LinearEasing),
            repeatMode = androidx.compose.animation.core.RepeatMode.Restart
        ),
        label = "hue_shift_gaps"
    )
    val rainbowColors = listOf(
        Color.hsl((hueShift + 0f) % 360f, 0.85f, 0.6f),
        Color.hsl((hueShift + 60f) % 360f, 0.85f, 0.6f),
        Color.hsl((hueShift + 120f) % 360f, 0.85f, 0.6f),
        Color.hsl((hueShift + 180f) % 360f, 0.85f, 0.6f),
        Color.hsl((hueShift + 240f) % 360f, 0.85f, 0.6f),
        Color.hsl((hueShift + 300f) % 360f, 0.85f, 0.6f),
        Color.hsl((hueShift + 360f) % 360f, 0.85f, 0.6f)
    )
    val rainbowBrush = androidx.compose.ui.graphics.Brush.sweepGradient(colors = rainbowColors)

    val cardAreas = remember { androidx.compose.runtime.mutableStateListOf<Pair<Float, Float>>() }

    val isTransparentGaps = LocalTransparentComponentsEnabled.current
    val transLimitGaps = LocalComponentsTransparency.current

    val cardBgColor = if (isFrostedGlassEnabled) {
        Color.Transparent
    } else if (isTransparentGaps) {
        (containerColor ?: baseCardColor).copy(alpha = transLimitGaps)
    } else {
        containerColor ?: baseCardColor
    }

    val gapScale = LocalSettingsGapScale.current
    val isAdaptive = LocalSettingsAdaptiveGrouping.current
    val adaptiveGrpRadius = LocalSettingsAdaptiveCornerRadius.current

    val glassBgBrush = GlassTheme.getCardBackgroundBrush(isDark, frostedTransparency, surfaceColor, baseCardColor)
    val glassBorderBrush = GlassTheme.getCardBorderBrush(isDark)
    val glassSheenBrush = GlassTheme.getInnerSheenBrush(isDark)

    Layout(
        content = content,
        modifier = modifier.drawBehind {
            val densityVal = this
            val paddingHzPx = densityVal.run { 16.dp.toPx() }
            val paddingVtPx = densityVal.run { 12.dp.toPx() }
            val cornerRadiusPx = densityVal.run { maxOf(0, generalCornerRadius).dp.toPx() }
            val adaptiveCornerPx = densityVal.run { maxOf(0, adaptiveGrpRadius).dp.toPx() }
            val borderWidthPx = densityVal.run { expBorderWidth.toPx() }

            val areasToDraw = synchronized(cardAreas) { cardAreas.toList() }
            val N = areasToDraw.size

            areasToDraw.forEachIndexed { idx, (top, cardHeight) ->
                if (cardHeight > 0) {
                    val topLeftR = if (isAdaptive && N > 1 && idx > 0) adaptiveCornerPx else cornerRadiusPx
                    val topRightR = if (isAdaptive && N > 1 && idx > 0) adaptiveCornerPx else cornerRadiusPx
                    val bottomLeftR = if (isAdaptive && N > 1 && idx < N - 1) adaptiveCornerPx else cornerRadiusPx
                    val bottomRightR = if (isAdaptive && N > 1 && idx < N - 1) adaptiveCornerPx else cornerRadiusPx

                    val roundRect = androidx.compose.ui.geometry.RoundRect(
                        left = 0f,
                        top = top,
                        right = size.width,
                        bottom = top + cardHeight,
                        topLeftCornerRadius = androidx.compose.ui.geometry.CornerRadius(topLeftR, topLeftR),
                        topRightCornerRadius = androidx.compose.ui.geometry.CornerRadius(topRightR, topRightR),
                        bottomLeftCornerRadius = androidx.compose.ui.geometry.CornerRadius(bottomLeftR, bottomLeftR),
                        bottomRightCornerRadius = androidx.compose.ui.geometry.CornerRadius(bottomRightR, bottomRightR)
                    )
                    val path = Path().apply {
                        addRoundRect(roundRect)
                    }

                    if (isBlurEffect && !isFrostedGlassEnabled && !isTransparentGaps) {
                        val shadowRoundRect = androidx.compose.ui.geometry.RoundRect(
                            left = 0f,
                            top = top + 3f,
                            right = size.width,
                            bottom = top + cardHeight + 5f,
                            topLeftCornerRadius = androidx.compose.ui.geometry.CornerRadius(topLeftR, topLeftR),
                            topRightCornerRadius = androidx.compose.ui.geometry.CornerRadius(topRightR, topRightR),
                            bottomLeftCornerRadius = androidx.compose.ui.geometry.CornerRadius(bottomLeftR, bottomLeftR),
                            bottomRightCornerRadius = androidx.compose.ui.geometry.CornerRadius(bottomRightR, bottomRightR)
                        )
                        val shadowPath = Path().apply {
                            addRoundRect(shadowRoundRect)
                        }
                        drawPath(path = shadowPath, color = Color.Black.copy(alpha = if (isDark) 0.20f else 0.08f))
                    }

                    if (isFrostedGlassEnabled) {
                        drawPath(path = path, brush = glassBgBrush)
                    } else if (cardBgColor != Color.Transparent) {
                        drawPath(path = path, color = cardBgColor)
                    }

                    if (isRainbowBorder) {
                        drawPath(
                            path = path,
                            brush = rainbowBrush,
                            style = androidx.compose.ui.graphics.drawscope.Stroke(width = borderWidthPx)
                        )
                    } else if (isFrostedGlassEnabled) {
                        drawPath(
                            path = path,
                            brush = glassBorderBrush,
                            style = androidx.compose.ui.graphics.drawscope.Stroke(width = 1.dp.toPx())
                        )
                    }
                }
            }
        }
    ) { measurables, constraints ->
        val groups = mutableListOf<MutableList<Measurable>>()
        var currentGroup = mutableListOf<Measurable>()
        for (measurable in measurables) {
            val layoutId = measurable.layoutId
            if (layoutId == "divider") {
                if (currentGroup.isNotEmpty()) {
                    groups.add(currentGroup)
                    currentGroup = mutableListOf()
                }
            } else {
                currentGroup.add(measurable)
            }
        }
        if (currentGroup.isNotEmpty()) {
            groups.add(currentGroup)
        }

        val paddingHzPx = 16.dp.roundToPx()
        val paddingVtPx = 12.dp.roundToPx()
        val gapPx = if (isAdaptive) (3.dp * gapScale).roundToPx() else (8.dp * gapScale).roundToPx()

        val groupPlaceables: List<List<androidx.compose.ui.layout.Placeable>> = groups.map { group: MutableList<androidx.compose.ui.layout.Measurable> ->
            group.map { measurable: androidx.compose.ui.layout.Measurable ->
                measurable.measure(
                    constraints.copy(
                        maxWidth = (constraints.maxWidth - (paddingHzPx.toInt() * 2)).coerceAtLeast(0),
                        minWidth = 0
                    )
                )
            }
        }

        val groupHeights = groupPlaceables.map { placeables ->
            if (placeables.isEmpty()) 0 else placeables.sumOf { it.height } + paddingVtPx * 2
        }

        val totalHeight = groupHeights.sum() + (groupHeights.size - 1).coerceAtLeast(0) * gapPx

        synchronized(cardAreas) {
            cardAreas.clear()
            var topY = 0f
            groupHeights.forEach { cardHeight ->
                if (cardHeight > 0) {
                    cardAreas.add(topY to cardHeight.toFloat())
                    topY += cardHeight + gapPx
                }
            }
        }

        layout(constraints.maxWidth, totalHeight) {
            var currentY = 0
            groupPlaceables.forEachIndexed { groupIndex, placeables ->
                val cardHeight = groupHeights[groupIndex]
                if (cardHeight > 0) {
                    var yOffset = currentY + paddingVtPx
                    placeables.forEach { placeable ->
                        placeable.placeRelative(paddingHzPx, yOffset)
                        yOffset += placeable.height
                    }
                    currentY += cardHeight + gapPx
                }
            }
        }
    }
}

@Composable
fun ChunkySettingCard(
    modifier: Modifier = Modifier,
    containerColor: Color? = null,
    content: @Composable ColumnScope.() -> Unit
) {
    val isOledActive = MaterialTheme.colorScheme.background == Color.Black
    val isDark = MaterialTheme.colorScheme.background.luminance() < 0.5f
    val baseCardColor = LocalBaseCardColor.current ?: MaterialTheme.colorScheme.surfaceVariant
    val generalCornerRadius = LocalGeneralCornerRadius.current
    
    val appTheme = LocalAppTheme.current
    val isFrostedGlassEnabled = LocalFrostedGlassEnabled.current
    val isBlurEffect = LocalBlurEffectEnabled.current
    
    val expBlurRadius = LocalExperimentalBlurRadius.current.dp
    val isRainbowBorder = LocalIsRainbowBorderEnabled.current
    val expBorderWidth = LocalExperimentalBorderWidth.current.dp
    val expCardScale = LocalExperimentalCardScale.current

    val hueShiftDuration = LocalExperimentalHueShiftDuration.current
    val infiniteTransition = androidx.compose.animation.core.rememberInfiniteTransition(label = "rainbow_border")
    val hueShift by infiniteTransition.animateFloat(
        initialValue = 0f,
        targetValue = 360f,
        animationSpec = androidx.compose.animation.core.infiniteRepeatable(
            animation = androidx.compose.animation.core.tween((hueShiftDuration * 1000).toInt().coerceAtLeast(100), easing = androidx.compose.animation.core.LinearEasing),
            repeatMode = androidx.compose.animation.core.RepeatMode.Restart
        ),
        label = "hue_shift"
    )
    val rainbowColors = listOf(
        Color.hsl((hueShift + 0f) % 360f, 0.85f, 0.6f),
        Color.hsl((hueShift + 60f) % 360f, 0.85f, 0.6f),
        Color.hsl((hueShift + 120f) % 360f, 0.85f, 0.6f),
        Color.hsl((hueShift + 180f) % 360f, 0.85f, 0.6f),
        Color.hsl((hueShift + 240f) % 360f, 0.85f, 0.6f),
        Color.hsl((hueShift + 300f) % 360f, 0.85f, 0.6f),
        Color.hsl((hueShift + 360f) % 360f, 0.85f, 0.6f)
    )
    val rainbowBrush = androidx.compose.ui.graphics.Brush.sweepGradient(colors = rainbowColors)

    val isTransparent = LocalTransparentComponentsEnabled.current
    val transLimit = LocalComponentsTransparency.current
    val isGapsMode = LocalSettingsDividerStyle.current == "GAPS"

    val finalCardColor = if (isGapsMode) {
        Color.Transparent
    } else if (isFrostedGlassEnabled) {
        Color.Transparent
    } else if (isTransparent) {
        (containerColor ?: baseCardColor).copy(alpha = transLimit)
    } else {
        containerColor ?: baseCardColor
    }

    Box(
        modifier = Modifier
            .fillMaxWidth()
            .then(
                if (expCardScale != 1.0f) Modifier.graphicsLayer {
                    scaleX = expCardScale
                    scaleY = expCardScale
                } else Modifier
            )
            .padding(vertical = 4.dp)
            .then(
                if (isBlurEffect && !isFrostedGlassEnabled && !isGapsMode && !isTransparent) Modifier.shadow(
                    elevation = 8.dp,
                    shape = RoundedCornerShape(maxOf(0, generalCornerRadius).dp),
                    ambientColor = Color.Black.copy(alpha = if (isDark) 0.25f else 0.08f),
                    spotColor = Color.Black.copy(alpha = if (isDark) 0.35f else 0.12f)
                ) else Modifier
            )
            .animateContentSize(
                animationSpec = androidx.compose.animation.core.spring(
                    dampingRatio = androidx.compose.animation.core.Spring.DampingRatioNoBouncy,
                    stiffness = androidx.compose.animation.core.Spring.StiffnessMediumLow
                )
            )
            .clip(RoundedCornerShape(maxOf(0, generalCornerRadius).dp))
            .then(modifier)
    ) {
        if (!isGapsMode) {
            // Blurred background layer sibling
            val isFrostedGlassEnabledVal = LocalFrostedGlassEnabled.current
            val frostedTransparency = LocalFrostedGlassTransparency.current
            val cardCornerShape = RoundedCornerShape(maxOf(0, generalCornerRadius).dp)

            Box(
                modifier = Modifier
                    .matchParentSize()
                    .then(
                        if (isBlurEffect && !isFrostedGlassEnabledVal && !isTransparent) {
                            Modifier.blur(
                                radius = expBlurRadius,
                                edgeTreatment = androidx.compose.ui.draw.BlurredEdgeTreatment(cardCornerShape)
                            )
                        } else Modifier
                    )
                    .then(
                        if (isFrostedGlassEnabledVal) {
                            Modifier.background(
                                brush = GlassTheme.getCardBackgroundBrush(isDark, frostedTransparency, MaterialTheme.colorScheme.surface, baseCardColor),
                                shape = cardCornerShape
                            )
                        } else {
                            Modifier.background(
                                color = finalCardColor,
                                shape = cardCornerShape
                            )
                        }
                    )
                    .then(
                        if (isRainbowBorder) {
                            Modifier.border(
                                width = expBorderWidth,
                                brush = rainbowBrush,
                                shape = cardCornerShape
                            )
                        } else if (isFrostedGlassEnabledVal) {
                            Modifier.border(
                                width = 1.dp,
                                brush = GlassTheme.getCardBorderBrush(isDark),
                                shape = cardCornerShape
                            )
                        } else if (isTransparent) {
                            Modifier
                        } else if (!isDark) {
                            Modifier.border(
                                width = 1.dp,
                                color = MaterialTheme.colorScheme.outline.copy(alpha = 0.25f),
                                shape = cardCornerShape
                            )
                        } else {
                            Modifier
                        }
                    )
                    .clip(cardCornerShape)
            )
        }
        
        // Foreground layer sibling
        CompositionLocalProvider(LocalContentColor provides MaterialTheme.colorScheme.onSurface) {
            if (isGapsMode) {
                Column(modifier = Modifier.fillMaxWidth()) {
                    val scope = this
                    ChunkyGapsLayout(
                        modifier = Modifier.fillMaxWidth(),
                        containerColor = containerColor
                    ) {
                        scope.content()
                    }
                }
            } else {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(18.dp),
                    verticalArrangement = Arrangement.Center
                ) {
                    content()
                }
            }
        }
    }
}

@Composable
fun ChunkyIconSwitchRow(
    icon: androidx.compose.ui.graphics.vector.ImageVector,
    title: String,
    subtitle: String,
    checked: Boolean,
    onCheckedChange: (Boolean) -> Unit,
    modifier: Modifier = Modifier
) {
    ChunkySettingCard(modifier = modifier) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Row(
                modifier = Modifier.weight(1f),
                horizontalArrangement = Arrangement.spacedBy(16.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Box(
                    modifier = Modifier
                        .size(40.dp)
                        .background(MaterialTheme.colorScheme.surfaceVariant, shape = CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = icon,
                        contentDescription = null,
                        tint = if (checked) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant,
                        modifier = Modifier.size(20.dp)
                    )
                }
                Column {
                    Text(
                        text = title,
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    Spacer(modifier = Modifier.height(2.dp))
                    Text(
                        text = subtitle,
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.8f)
                    )
                }
            }
            ChunkySettingSwitch(
                checked = checked,
                onCheckedChange = onCheckedChange
            )
        }
    }
}

@Composable
fun ChunkyHapticEngineRow(
    viewModel: WaterViewModel,
    appLanguage: String,
    modifier: Modifier = Modifier
) {
    val hapticMode by viewModel.hapticMode.collectAsStateWithLifecycle()
    val context = androidx.compose.ui.platform.LocalContext.current
    val isLinear = remember(context) { HapticManager.isLinearMotor(context) }
    
    val titleVal = if (appLanguage == "el") "Μηχανή Απτικής" else "Haptic Engine"
    
    val motorTypeDesc = if (appLanguage == "el") {
        if (isLinear) "Ανιχνεύθηκε γραμμικός κινητήρας (LRA). Συνιστάται η Βελτιωμένη απτική." else "Ανιχνεύθηκε απλός κινητήρας (ERM). Συνιστάται η Προεπιλογή."
    } else {
        if (isLinear) "Linear resonant motor (LRA) haptics detected. Enhanced haptics suggested." else "Standard vibration motor (ERM/simple) detected. Default haptics suggested."
    }
    
    val subtitleVal = if (appLanguage == "el") "Επιλέξτε μεταξύ Default (κλασική απτική) ή Enhanced (απτική υψηλής ακρίβειας). $motorTypeDesc" else "Choose between Default (vibration effects) or Enhanced (highly crisp micro-ticks). $motorTypeDesc"
    
    val defaultText = if (appLanguage == "el") {
        if (!isLinear) "Προεπιλογή (Προτεινόμενο)" else "Προεπιλογή"
    } else {
        if (!isLinear) "Default (Suggested)" else "Default"
    }
    
    val enhancedText = if (appLanguage == "el") {
        if (isLinear) "Βελτιωμένη (Προτεινόμενο)" else "Βελτιωμένη"
    } else {
        if (isLinear) "Enhanced (Suggested)" else "Enhanced"
    }

    ChunkySettingCard(modifier = modifier) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(16.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Box(
                    modifier = Modifier
                        .size(40.dp)
                        .background(MaterialTheme.colorScheme.surfaceVariant, shape = androidx.compose.foundation.shape.CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = Icons.Rounded.Settings,
                        contentDescription = null,
                        tint = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.size(20.dp)
                    )
                }
                Column(modifier = Modifier.weight(1f)) {
                    Text(
                        text = titleVal,
                        fontSize = 16.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    Text(
                        text = subtitleVal,
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
            }

            val hapticModes = HapticMode.values().toList()
            GoogleHealthSegmentedControl(
                items = hapticModes,
                selectedItem = hapticMode,
                onItemSelection = { mode ->
                    viewModel.updateHapticMode(mode)
                },
                itemLabel = { mode ->
                    if (mode == HapticMode.DEFAULT) defaultText else enhancedText
                },
                triggerHaptic = { viewModel.triggerButtonHaptic() }
            )
        }
    }
}

