    hapticsSlidersEnabled: Boolean,
    hapticsButtonsEnabled: Boolean,
    hapticsGoalEnabled: Boolean,
    fireworksFeedbackEnabled: Boolean,
    customFireworkHapticsEnabled: Boolean,
    fireworkDurationMs: Int,
    fireworkGapMs: Int,
    fireworkStrength: Int,
    fireworkPatternPreset: VibrationPatternPreset,
    isFireworkHapticTestActive: Boolean,
    geminiApiKey: String,
    vibrationDurationMs: Int,
    vibrationGapMs: Int,
    vibrationStrength: Int,
    animationHapticStrength: Int,
    vibrationPatternPreset: VibrationPatternPreset,
    isHapticTestActive: Boolean,
    onNavigateToAppearance: () -> Unit,
    onNavigateToReminders: () -> Unit = {},
    remindersInSettings: Boolean = false,
    onNavigateToHaptics: () -> Unit,
    onNavigateToWearOsSettings: () -> Unit,
    onNavigateToWidget: () -> Unit,
    onNavigateToTileSettings: () -> Unit,
    onNavigateToNotifications: () -> Unit,
    onNavigateToAiIntegration: () -> Unit,
    onNavigateToContactMe: () -> Unit,
    onNavigateToApkUpdates: () -> Unit,
    onNavigateToLegalDisclaimer: () -> Unit,
    onNavigateToDeveloperOptions: () -> Unit,
    appLanguage: String,
    titleFaceStyle: Int,
    isGoogleLoggedIn: Boolean,
    isGoogleDriveBackupEnabled: Boolean,
    googleAccountEmail: String,
    googleAccountName: String,
    isDeveloper: Boolean,
    onOpenGoogleLoginDialog: () -> Unit,
    onOpenFirebaseLoginDialog: () -> Unit,
    onSignOutGoogle: () -> Unit,
    onBackupSuccess: (Int, Int, String) -> Unit,
    onOpenStorageBackupDialog: () -> Unit,
    onOpenSetupDialog: () -> Unit,
    onOpenNerdModePopup: () -> Unit
) {
    // 0. Language / AI Integration Settings
    item {
