        var isLanguageOptionsExpanded by remember { mutableStateOf(false) }

        Column(modifier = Modifier.fillMaxWidth()) {
            ChunkySettingCard(
                modifier = Modifier.clickable { 
                    viewModel.updateAppLanguage(if (appLanguage == "en") "el" else "en")
