                    triggerSnapHaptic = { viewModel.triggerToggleSnapHaptic() },
                    triggerUnlatchHaptic = { viewModel.triggerTitleFaceUnlatchHaptic() },
                    triggerTensionHaptic = { viewModel.triggerTitleFaceTensionHaptic() }
                )

                androidx.compose.animation.AnimatedVisibility(
                    visible = isNerdMode && isFaceSettingsExpanded
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(top = 16.dp),
                        verticalArrangement = Arrangement.spacedBy(16.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .height(1.dp)
                                .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f))
                        )
                        
                        // Position Option
                        Column(
                            modifier = Modifier.fillMaxWidth(),
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Text(
                                text = if (appLanguage == "el") "Θέση Φάτσας Τίτλου" else "Title Face Position",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                            MultiWayToggle(
                                selectedIndex = titleFacePosition,
                                options = if (appLanguage == "el") listOf("Δίπλα στον τίτλο", "Πάνω δεξιά") else listOf("Next to title", "Top right"),
                                onModeSelect = { viewModel.updateTitleFacePosition(it) },
                                triggerLightHaptic = { viewModel.triggerToggleLightHaptic() },
                                triggerSnapHaptic = { viewModel.triggerToggleSnapHaptic() }
                            )
                        }

                        // Vividness Option
                        Column(
                            modifier = Modifier.fillMaxWidth(),
                            verticalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = if (appLanguage == "el") "Ζωντάνια Φάτσας" else "Title Face Vividness",
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                                Text(
                                    text = "$titleFaceVividness/5",
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.primary
                                )
                            }
                            CapsulePatternSlider(
                                value = titleFaceVividness.toFloat(),
                                onValueChange = { 
                                    viewModel.updateTitleFaceVividness(it.toInt().coerceIn(1, 5))
                                },
                                valueRange = 1f..5f,
                                stepsCount = 5,
                                triggerHaptic = { viewModel.triggerSliderHaptic() },
                                modifier = Modifier.fillMaxWidth()
                            )
                        }

                        // Palette Color Option (Visible in Nerd Mode when Dynamic Theme is active)
                        if (appTheme == "DYNAMIC") {
                            Column(
                                modifier = Modifier.fillMaxWidth(),
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Text(
                                    text = if (appLanguage == "el") "Χρώμα Παλέτας Φάτσας" else "Title Face Palette Color",
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                                val selectedPaletteIndex = when (titleFacePaletteRole) {
                                    "PRIMARY" -> 0
                                    "SECONDARY" -> 1
                                    "TERTIARY" -> 2
                                    else -> 0
                                }
                                MultiWayToggle(
                                    selectedIndex = selectedPaletteIndex,
                                    options = if (appLanguage == "el") listOf("Πρωτεύον", "Δευτερεύον", "Τριτεύον") else listOf("Primary", "Secondary", "Tertiary"),
                                    onModeSelect = { roleIdx ->
                                        val newRole = when (roleIdx) {
                                            0 -> "PRIMARY"
                                            1 -> "SECONDARY"
                                            2 -> "TERTIARY"
                                            else -> "PRIMARY"
                                        }
                                        viewModel.updateTitleFacePaletteRole(newRole)
                                    },
                                    triggerLightHaptic = { viewModel.triggerToggleLightHaptic() },
                                    triggerSnapHaptic = { viewModel.triggerToggleSnapHaptic() }
                                )
                            }
                        }
                    }
                }
            }
        }
