                    val collapseLongInsightsEnabled by viewModel.collapseLongInsightsEnabled.collectAsStateWithLifecycle()
                    val collapseInsightThresholdLines by viewModel.collapseInsightThresholdLines.collectAsStateWithLifecycle()
                        
                    androidx.compose.material3.HorizontalDivider(
                        modifier = Modifier.padding(vertical = 14.dp),
                        color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f)
                    )
                        
                    Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween,
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.weight(1f)) {
                                Icon(
                                    imageVector = Icons.Rounded.KeyboardArrowDown, 
                                    contentDescription = null, 
                                    tint = if (collapseLongInsightsEnabled) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant
                                )
                                Spacer(modifier = Modifier.width(16.dp))
                                Column {
                                    Text(
                                        if (viewModel.appLanguage.value == "el") "Σύμπτυξη Μεγάλων Insight" else "Collapse Long Insights", 
                                        fontWeight = FontWeight.Bold
                                    )
                                    Text(
                                        if (viewModel.appLanguage.value == "el") "Απόκρυψη του υπόλοιπου κειμένου όταν το insight είναι πολύ μεγάλο" else "Hide the remaining text of the hydration insight if it exceeds a certain length", 
                                        fontSize = 12.sp, 
                                        color = MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                }
                            }
                            
                            ChunkySettingSwitch(
                                checked = collapseLongInsightsEnabled,
                                onCheckedChange = { 
                                    viewModel.updateCollapseLongInsightsEnabled(it) 
                                    viewModel.triggerToggleHaptic()
                                }
                            )
                        }
                        
                        androidx.compose.animation.AnimatedVisibility(
                            visible = collapseLongInsightsEnabled,
                            enter = androidx.compose.animation.fadeIn() + androidx.compose.animation.expandVertically(),
                            exit = androidx.compose.animation.fadeOut() + androidx.compose.animation.shrinkVertically()
                        ) {
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(start = 40.dp, top = 12.dp),
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Text(
                                    if (viewModel.appLanguage.value == "el") "Όριο Γραμμών Ενεργοποίησης" else "Trigger Threshold Lines",
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.SemiBold,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                                Text(
                                    if (viewModel.appLanguage.value == "el") "Επιλέξτε μετά από πόσες γραμμές κειμένου θα ενεργοποιηθεί η σύμπτυξη" else "Choose after how many lines of text the collapse will trigger",
                                    fontSize = 11.sp,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                                
                                androidx.compose.foundation.lazy.LazyRow(
                                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                                    modifier = Modifier.fillMaxWidth()
                                ) {
                                    val lineOptions = listOf(3, 5, 8, 10, 12, 15, 20)
                                    items(lineOptions.size) { idx ->
                                        val lineNum = lineOptions[idx]
                                        val isSelected = collapseInsightThresholdLines == lineNum
                                        val cornerRadius by androidx.compose.animation.core.animateDpAsState(
                                            targetValue = if (isSelected) 24.dp else 10.dp,
                                            label = "threshold_corner"
                                        )
                                        Box(
                                            modifier = Modifier
                                                .clip(RoundedCornerShape(cornerRadius))
                                                .background(
                                                    if (isSelected) MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)
                                                )
                                                .border(
                                                    width = if (isSelected) 2.dp else 1.dp,
                                                    color = if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outline.copy(alpha = 0.15f),
                                                    shape = RoundedCornerShape(cornerRadius)
                                                )
                                                .clickable {
                                                    viewModel.updateCollapseInsightThresholdLines(lineNum)
                                                    viewModel.triggerButtonHaptic()
                                                }
                                                .padding(horizontal = 12.dp, vertical = 6.dp),
                                            contentAlignment = Alignment.Center
                                        ) {
                                            Text(
                                                text = if (viewModel.appLanguage.value == "el") "$lineNum Γραμμές" else "$lineNum Lines",
                                                fontWeight = FontWeight.Bold,
                                                fontSize = 12.sp,
                                                color = if (isSelected) MaterialTheme.colorScheme.onPrimaryContainer else MaterialTheme.colorScheme.onSurfaceVariant
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                    
                    androidx.compose.animation.AnimatedVisibility(
                        visible = isPreviewExpanded,
                        enter = androidx.compose.animation.fadeIn() + androidx.compose.animation.expandVertically(),
                        exit = androidx.compose.animation.fadeOut() + androidx.compose.animation.shrinkVertically()
                    ) {
