                            ) {
                                Text(if (viewModel.appLanguage.value == "el") "Ανανέωση Καιρού" else "Refresh Weather", fontSize = 12.sp)
                            }
                            
                            androidx.compose.material3.OutlinedButton(
                                onClick = {
                                    val currentTemp = viewModel.weatherTemperature.value ?: 0.0
                                    val simTemp = if (currentTemp >= 32.0) currentTemp else 39.5
                                    val simHum = viewModel.weatherRelativeHumidity.value ?: 62.0
                                    val simApp = viewModel.weatherApparentTemperature.value ?: 46.5
                                    viewModel.checkoutExtremeHeatProposal(
                                        temp = simTemp,
                                        city = locationCity.ifBlank { "Athens" },
