@Composable
fun PixelSegmentedToggle(
    labels: List<String>,
    selectedIndex: Int,
    onSelect: (Int) -> Unit,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    usePaletteColors: Boolean = false
) {
    val alpha = if (enabled) 1f else 0.5f
    val context = androidx.compose.ui.platform.LocalContext.current
    val view = androidx.compose.ui.platform.LocalView.current

    androidx.compose.foundation.layout.BoxWithConstraints(
        modifier = modifier
            .fillMaxWidth()
            .height(48.dp)
            .background(
                color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = alpha * 0.35f),
                shape = CircleShape
            )
            .border(
                width = 1.dp,
                color = MaterialTheme.colorScheme.outline.copy(alpha = alpha * 0.15f),
                shape = CircleShape
            )
            .padding(4.dp)
            .clip(CircleShape),
        contentAlignment = Alignment.CenterStart
    ) {
        val totalWidth = maxWidth
        val segmentCount = labels.size
        val segmentWidth = totalWidth / segmentCount

        // Animated sliding background capsule
        val indicatorOffset by androidx.compose.animation.core.animateDpAsState(
            targetValue = segmentWidth * selectedIndex,
            animationSpec = androidx.compose.animation.core.spring(
                stiffness = androidx.compose.animation.core.Spring.StiffnessMedium,
                dampingRatio = androidx.compose.animation.core.Spring.DampingRatioLowBouncy
            ),
            label = "segmented_indicator_offset"
        )

        Box(
            modifier = Modifier
                .offset(x = indicatorOffset)
                .width(segmentWidth)
                .fillMaxHeight()
                .background(
                    color = if (usePaletteColors) {
                        when (selectedIndex) {
                            0 -> MaterialTheme.colorScheme.primary
                            1 -> MaterialTheme.colorScheme.secondary
                            else -> MaterialTheme.colorScheme.tertiary
                        }
                    } else {
                        MaterialTheme.colorScheme.primary
                    }.copy(alpha = if (enabled) 1f else 0.5f),
                    shape = CircleShape
                )
        )

        // Labels Row
        Row(
            modifier = Modifier.fillMaxSize(),
            verticalAlignment = Alignment.CenterVertically
        ) {
            labels.forEachIndexed { index, text ->
                val isSelected = selectedIndex == index
                val contentColor = if (isSelected) {
                    if (usePaletteColors) {
                        when (index) {
                            0 -> MaterialTheme.colorScheme.onPrimary
                            1 -> MaterialTheme.colorScheme.onSecondary
                            else -> MaterialTheme.colorScheme.onTertiary
                        }
                    } else {
                        MaterialTheme.colorScheme.onPrimary
                    }
                } else {
                    MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = alpha)
                }

                Box(
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxHeight()
                        .clip(CircleShape)
                        .clickable(enabled = enabled) {
                            if (selectedIndex != index) {
                                // Trigger tactile snap haptic directly
                                HapticManager.triggerToggleSnapHaptic(context, view, 25, 85)
                                onSelect(index)
                            }
                        },
                    contentAlignment = Alignment.Center
                ) {
                    Row(
                        horizontalArrangement = Arrangement.Center,
                        verticalAlignment = Alignment.CenterVertically,
                        modifier = Modifier.padding(horizontal = 4.dp)
                    ) {
                        if (isSelected) {
                            Icon(
                                imageVector = Icons.Rounded.Check,
                                contentDescription = null,
                                modifier = Modifier
                                    .size(16.dp)
                                    .padding(end = 4.dp),
                                tint = contentColor
                            )
                        }
                        Text(
                            text = text,
                            fontSize = 12.sp,
                            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                            color = contentColor,
                            maxLines = 1,
                            overflow = androidx.compose.ui.text.style.TextOverflow.Ellipsis
                        )
                    }
                }
            }
        }
    }
}

@Composable
fun ThreeWayAnimToggle(
    currentMode: Int,
    appLanguage: String,
    onModeSelect: (Int) -> Unit,
    triggerLightHaptic: () -> Unit,
    triggerSnapHaptic: () -> Unit
) {
    val labels = if (appLanguage == "el") {
        listOf("Ολίσθηση", "Αναπήδηση", "Ξεθώριασμα")
    } else {
        listOf("Sliding", "Bouncing", "Fading")
    }

    PixelSegmentedToggle(
        labels = labels,
        selectedIndex = currentMode,
        onSelect = { 
            if (currentMode != it) {
                triggerSnapHaptic()
                onModeSelect(it)
            }
        }
    )
}

@Composable
fun ThreeWayColorToggle(
    currentMode: Int,
    appLanguage: String,
    onModeSelect: (Int) -> Unit,
    triggerLightHaptic: () -> Unit,
    triggerSnapHaptic: () -> Unit,
    usePaletteColors: Boolean = false,
    enabled: Boolean = true
) {
    val labels = if (appLanguage == "el") {
        listOf("Πρωτεύον", "Δευτερεύον", "Τριτεύον")
    } else {
        listOf("Primary", "Secondary", "Tertiary")
    }

    PixelSegmentedToggle(
        labels = labels,
        selectedIndex = currentMode.coerceIn(0, 2),
        onSelect = { 
            if (currentMode != it) {
                triggerSnapHaptic()
                onModeSelect(it)
            }
        },
        enabled = enabled,
        usePaletteColors = usePaletteColors
    )
}

fun androidx.compose.foundation.lazy.LazyListScope.renderAppearanceSettingsSection(
    viewModel: WaterViewModel,
    themeMode: String,
    appTheme: String,
    isFrostedGlassEnabled: Boolean,
    frostedGlassTransparency: Float,
    transparentComponentsEnabled: Boolean,
    componentsTransparency: Float,
    oledModeEnabled: Boolean,
    lightModeDarkTextEnabled: Boolean,
    tabTransitionMode: Int,
    isSwipeTabNavEnabled: Boolean,
    bounceStiffness: Float,
    bounceDamping: Float,
    fadeStiffness: Float,
    fadeDamping: Float,
    slideStiffness: Float,
    slideDamping: Float,
    appLanguage: String,
    isDeveloper: Boolean,
    isEmailDeveloper: Boolean,
    onNavigateToCornerRadius: () -> Unit,
    onScrollLockChange: (Boolean) -> Unit = {},
    onTriggerConfetti: () -> Unit = {},
    isScrollInProgress: Boolean = false
) {
    renderRedesignedAppearanceSettingsSection(
        viewModel, themeMode, appTheme, isFrostedGlassEnabled, frostedGlassTransparency,
        transparentComponentsEnabled, componentsTransparency, oledModeEnabled,
        lightModeDarkTextEnabled, tabTransitionMode, isSwipeTabNavEnabled,
        bounceStiffness, bounceDamping, fadeStiffness, fadeDamping,
        slideStiffness, slideDamping, appLanguage, isDeveloper, isEmailDeveloper,
        onNavigateToCornerRadius, onScrollLockChange, onTriggerConfetti,
        isScrollInProgress
    )
}

fun androidx.compose.foundation.lazy.LazyListScope.renderCornerRadiusSettingsSection(
    viewModel: WaterViewModel,
    navbarCornerRadius: Int,
    generalCornerRadius: Int
) {
    item {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(vertical = 12.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
