fun androidx.compose.foundation.lazy.LazyListScope.renderContactMeSection(
    viewModel: WaterViewModel,
    appLanguage: String,
    onTriggerConfetti: () -> Unit,
    onTriggerSaturdayPopup: () -> Unit,
    onTriggerLennyRain: () -> Unit
) {
    item {
        ChunkySettingCard {
            var clickCount200 by remember { mutableStateOf(0) }
            var clickCount10 by remember { mutableStateOf(0) }
            val secretLennyCount by viewModel.secretLennyCount.collectAsStateWithLifecycle()
            
            val isGoogleLoggedIn by viewModel.isGoogleLoggedIn.collectAsStateWithLifecycle()
            val googleAccountEmail by viewModel.googleAccountEmail.collectAsStateWithLifecycle()
            val isDeveloper by viewModel.isDeveloper.collectAsStateWithLifecycle()
            
            val emailLower = googleAccountEmail.lowercase()
            val developerEmails = remember { listOf("antoniskouroudis1@gmail.com") }
            val isEmailDeveloper = isGoogleLoggedIn && developerEmails.contains(emailLower)
            
            val premiumEmailsSet = remember {
                setOf(
                    "antoniskouroudis1@gmail.com",
                    "emmadrenou@gmail.com",
                    "prodromoskouroudis@gmail.com",
                    "kouroudisprodromos@gmail.com",
                    "joannakam06@gmail.com",
                    "euapapasot@gmail.com",
                    "kiahpelagi@gmail.com",
                    "kiahpelagi@gmail.con",
                    "konstantinoskouroudis@gmail.com"
                )
            }
            
            val isPremium = isGoogleLoggedIn && (premiumEmailsSet.contains(emailLower) || isDeveloper)
            val isDevUserVal = isDeveloper || isEmailDeveloper
            val showBuyMeACoffee = !isPremium || isDevUserVal
            
            Column(
                modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                // Contact Details Header & Icon
                Box(
                    modifier = Modifier
                        .size(60.dp)
                        .background(MaterialTheme.colorScheme.primaryContainer, shape = CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = Icons.Rounded.Email,
                        contentDescription = "Email developer",
                        tint = MaterialTheme.colorScheme.onPrimaryContainer,
                        modifier = Modifier.size(28.dp)
                    )
                }

                Column(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    Text(
                        text = if (appLanguage == "el") "Επικοινωνία" else "Contact Me",
                        fontSize = 20.sp,
                        fontWeight = FontWeight.ExtraBold,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    Text(
                        text = if (appLanguage == "el") 
                            "Έχετε κάποιες προτάσεις, θέματα ή σχόλια; Μη διστάσετε να έρθετε σε επαφή!" 
                            else "Have any suggestions, feedback, or facing issues? Don't hesitate to reach out!",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.8f),
                        textAlign = TextAlign.Center,
                        lineHeight = 16.sp,
                        modifier = Modifier.padding(horizontal = 16.dp)
                    )
                }

                // Email Address container Card/Box
                val context = LocalContext.current
                androidx.compose.material3.Surface(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(12.dp))
                        .clickable {
                            viewModel.triggerButtonHaptic()
                            val intent = android.content.Intent(android.content.Intent.ACTION_SENDTO).apply {
                                data = android.net.Uri.parse("mailto:kouroudesantonios@gmail.com")
                                putExtra(android.content.Intent.EXTRA_SUBJECT, "HydraTrack Feedback")
                            }
                            try {
                                context.startActivity(intent)
                            } catch (e: Exception) {
                                // No email app
                                android.widget.Toast.makeText(context, "No email app found", android.widget.Toast.LENGTH_SHORT).show()
                            }
                        },
                    color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
                ) {
                    Box(
                        modifier = Modifier.padding(16.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(4.dp)) {
                            Text(
                                text = if (appLanguage == "el") "Διεύθυνση Email" else "Email Address",
                                fontSize = 10.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.primary,
                                letterSpacing = 1.sp
                            )
                            Text(
                                text = "kouroudesantonios@gmail.com",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Black,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                    }
                }

                // Buy Me a Coffee Button
                if (showBuyMeACoffee) {
                    val uriHandler = androidx.compose.ui.platform.LocalUriHandler.current
                    androidx.compose.material3.Button(
                        onClick = {
                            viewModel.triggerButtonHaptic()
                            uriHandler.openUri("https://www.buymeacoffee.com/akourouc")
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(64.dp),
                        shape = RoundedCornerShape(16.dp),
                        colors = ButtonDefaults.buttonColors(
                            containerColor = Color(0xFFFFDD00),
                            contentColor = Color.Black
                        ),
                        elevation = ButtonDefaults.buttonElevation(defaultElevation = 2.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.Center,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            // Buy Me a Coffee "Logo" Icon (Custom Coffee cup)
                            Icon(
                                imageVector = Icons.Rounded.LocalCafe,
                                contentDescription = "Buy me a coffee",
                                modifier = Modifier.size(24.dp),
                                tint = Color.Black
                            )
                            Spacer(modifier = Modifier.width(12.dp))
                            Column(horizontalAlignment = Alignment.Start) {
                                Text(
                                    text = if (appLanguage == "el") "Αγόρασέ μου έναν καφέ" else "Buy me a coffee",
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.ExtraBold,
                                    color = Color.Black
                                )
                                Text(
                                    text = if (appLanguage == "el") 
                                        "Αγόρασέ μου ένα καφέ αν απολαμβάνεις την εφαρμογή και θέλεις να με υποστηρίξεις •‿•" 
                                        else "Buy me a coffee if you enjoy the app and would like to support me •‿•",
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.Medium,
                                    lineHeight = 12.sp,
                                    color = Color.Black.copy(alpha = 0.8f)
                                )
                            }
                        }
                    }

                    androidx.compose.material3.HorizontalDivider(
                        color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.08f),
                        thickness = 1.dp
                    )
                }

                // The secret interactive click button section
                Text(
                    text = if (appLanguage == "el") "Κάντε κλικ στο κουμπί για μια έκπληξη..." else "Click the button for a surprise...",
                    fontSize = 11.sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f),
                    textAlign = TextAlign.Center
                )

                androidx.compose.animation.AnimatedContent(
                    targetState = clickCount200 >= 200,
                    label = "secret_reveal_animation_200"
                ) { revealed ->
                    if (revealed) {
                        val lennys = listOf(
                            "¯\\_(ツ)_/¯",
                            "╮(. ❛ ᴗ ❛.)╭",
                            "¯\\_༼ •́ ͜ʖ •̀ ༽_/¯",
                            "🫣"
                        )
                        val idx = (secretLennyCount - 1).coerceAtLeast(0) % lennys.size
                        val lennyFace = lennys[idx]
                        val finalText = if (appLanguage == "el") "χεχε $lennyFace" else lennyFace

                        Surface(
                            shape = RoundedCornerShape(12.dp),
                            color = MaterialTheme.colorScheme.tertiaryContainer,
                            border = androidx.compose.foundation.BorderStroke(1.dp, MaterialTheme.colorScheme.tertiary.copy(alpha = 0.3f)),
                            modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp)
                                .clickable { clickCount200 = 0 }
                        ) {
                            Box(
                                modifier = Modifier.fillMaxWidth().padding(16.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    text = finalText,
                                    fontSize = 24.sp,
                                    fontWeight = FontWeight.Black,
                                    color = MaterialTheme.colorScheme.onTertiaryContainer,
                                    textAlign = TextAlign.Center
                                )
                            }
                        }
                    } else {
                        Surface(
                            onClick = {
                                clickCount200++
                                if (clickCount200 == 200) {
                                    viewModel.triggerFireworksHaptic()
                                    viewModel.incrementSecretLennyCount()
                                    onTriggerLennyRain()
                                } else {
                                    viewModel.triggerButtonHaptic()
                                }
                            },
                            shape = RoundedCornerShape(12.dp),
                            color = MaterialTheme.colorScheme.secondary,
                            modifier = Modifier.fillMaxWidth().height(48.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = if (appLanguage == "el") "Πάτα με!" else "Click me",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 14.sp,
                                    color = MaterialTheme.colorScheme.onSecondary
                                )
                                // Pill counter
                                Surface(
                                    color = MaterialTheme.colorScheme.onSecondary.copy(alpha = 0.2f),
                                    shape = RoundedCornerShape(100),
                                    modifier = Modifier.padding(start = 8.dp)
                                ) {
                                    Text(
                                        text = "$clickCount200 / 200",
                                        fontWeight = FontWeight.Black,
                                        fontSize = 11.sp,
                                        color = MaterialTheme.colorScheme.onSecondary,
                                        modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp)
                                    )
                                }
                            }
                        }
                    }
                }

                androidx.compose.animation.AnimatedContent(
                    targetState = clickCount10 >= 10,
                    label = "secret_reveal_animation_10"
                ) { revealed ->
                    if (revealed) {
                        Surface(
                            shape = RoundedCornerShape(12.dp),
                            color = MaterialTheme.colorScheme.secondaryContainer,
                            border = androidx.compose.foundation.BorderStroke(1.dp, MaterialTheme.colorScheme.secondary.copy(alpha = 0.3f)),
                            modifier = Modifier.fillMaxWidth().padding(horizontal = 8.dp)
                        ) {
                            Box(
                                modifier = Modifier.fillMaxWidth().padding(16.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    text = if (appLanguage == "el") "ευχαριστώ που χρησιμοποιείς την εφαρμογή μου ( ◜‿◝ )♡" else "thank you for downloading ( ◜‿◝ )♡",
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.Black,
                                    color = MaterialTheme.colorScheme.onSecondaryContainer,
                                    textAlign = TextAlign.Center
                                )
                            }
                        }
                    } else {
                        Surface(
                            onClick = {
                                clickCount10++
                                if (clickCount10 == 10) {
                                    viewModel.triggerFireworksHaptic()
                                    onTriggerConfetti()
                                } else {
                                    viewModel.triggerButtonHaptic()
                                }
                            },
                            shape = RoundedCornerShape(12.dp),
                            color = MaterialTheme.colorScheme.tertiary,
                            modifier = Modifier.fillMaxWidth().height(48.dp)
                        ) {
                            Row(
                                modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = if (appLanguage == "el") "Πάτα με!" else "Click me",
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 14.sp,
                                    color = MaterialTheme.colorScheme.onTertiary
                                )
                                // Pill counter
                                Surface(
                                    color = MaterialTheme.colorScheme.onTertiary.copy(alpha = 0.2f),
                                    shape = RoundedCornerShape(100),
                                    modifier = Modifier.padding(start = 8.dp)
                                ) {
                                    Text(
                                        text = "$clickCount10 / 10",
                                        fontWeight = FontWeight.Black,
                                        fontSize = 11.sp,
                                        color = MaterialTheme.colorScheme.onTertiary,
                                        modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp)
                                    )
                                }
                            }
                        }
                    }
                }

                Box(modifier = Modifier.fillMaxWidth().padding(top = 8.dp), contentAlignment = Alignment.Center) {
                    TextButton(onClick = {
                        onTriggerSaturdayPopup()
                        viewModel.triggerButtonHaptic()
                    }) {
                        Text("😊", fontSize = 16.sp)
                    }
                }
            }
        }
    }
}

fun androidx.compose.foundation.lazy.LazyListScope.renderApkUpdatesSection(
    viewModel: WaterViewModel,
    appLanguage: String,
    isDeveloper: Boolean,
    isEmailDeveloper: Boolean,
    onNavigateToGimmick: () -> Unit = {}
) {
    item {
        ChunkySettingCard {
            Column(
                modifier = Modifier.fillMaxWidth().padding(12.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(16.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Box(
                        modifier = Modifier
                            .size(52.dp)
                            .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.12f), shape = CircleShape),
                        contentAlignment = Alignment.Center
                    ) {
                        Icon(
                            imageVector = Icons.Rounded.Refresh,
                            contentDescription = "Device updates",
                            tint = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.size(24.dp)
                        )
                    }
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = if (appLanguage == "el") "Ενημέρωση Pixel Water" else "Pixel Water Update",
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        Spacer(modifier = Modifier.height(2.dp))
                        Text(
                            text = if (appLanguage == "el") "Τελευταίος έλεγχος: Μόλις τώρα • GitHub Releases" else "Last checked: Just now • Verified via GitHub releases",
                            fontSize = 11.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.75f)
                        )
                    }
                }

                Button(
                    onClick = {
                        viewModel.triggerButtonHaptic()
                        viewModel.checkForUpdates()
                    },
                    shape = CircleShape,
                    colors = ButtonDefaults.buttonColors(
                        containerColor = Color(0xFFC4D199),
                        contentColor = Color(0xFF2B360F)
                    ),
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(56.dp)
                        .testTag("check_updates_btn")
                ) {
                    Icon(
                        imageVector = Icons.Rounded.SystemUpdate, 
                        contentDescription = null, 
                        modifier = Modifier.size(24.dp)
                    )
                    Spacer(modifier = Modifier.width(10.dp))
                    Text(
                        text = if (appLanguage == "el") "Έλεγχος για ενημερώσεις" else "Check for updates", 
                        fontWeight = FontWeight.Bold, 
                        fontSize = 16.sp,
                        letterSpacing = 0.15.sp
                    )
                }
            }
        }
    }

    item {
        var crashReportingEnabled by remember { mutableStateOf(viewModel.isCrashReportingEnabled()) }
        ChunkySettingCard {
            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(
                        modifier = Modifier.weight(1f),
                        horizontalArrangement = Arrangement.spacedBy(16.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(40.dp)
                                .background(MaterialTheme.colorScheme.errorContainer, shape = CircleShape),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Rounded.Warning,
                                contentDescription = "Crash Reporting",
                                tint = MaterialTheme.colorScheme.onErrorContainer,
                                modifier = Modifier.size(20.dp)
                            )
                        }
                        Column {
                            Text(
                                text = if (appLanguage == "el") "Αυτόματη Αναφορά Σφαλμάτων" else "Auto Crash Reporting",
                                fontSize = 15.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = if (appLanguage == "el") "Αυτόματη αποστολή καταγραφών σφαλμάτων στον προγραμματιστή" else "Automatically send crash logs to developer",
                                fontSize = 11.sp,
                                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.8f)
                            )
                        }
                    }
                    ChunkySettingSwitch(
                        checked = crashReportingEnabled,
                        onCheckedChange = { 
                            crashReportingEnabled = it
                            viewModel.setCrashReportingEnabled(it)
                            viewModel.triggerButtonHaptic()
                        }
                    )
                }

                OutlinedButton(
                    onClick = { 
                        viewModel.triggerButtonHaptic()
                        viewModel.sendManualCrashReport()
                    },
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Icon(imageVector = Icons.AutoMirrored.Rounded.Send, contentDescription = null, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(if (appLanguage == "el") "Μη αυτόματη Αναφορά Σφάλματος ή Προβλήματος" else "Send Manual Crash or Bug Report", fontWeight = FontWeight.Bold, fontSize = 13.sp)
                }
            }
        }
    }

    item {
        var selectedInstruction by remember { mutableStateOf<String?>(null) }
