private fun adjustColorSaturation(color: Color, saturationFactor: Float): Color {
    val hsv = FloatArray(3)
    val red = (color.red * 255).toInt().coerceIn(0, 255)
    val green = (color.green * 255).toInt().coerceIn(0, 255)
    val blue = (color.blue * 255).toInt().coerceIn(0, 255)
    val argb = android.graphics.Color.rgb(red, green, blue)
    android.graphics.Color.colorToHSV(argb, hsv)
    hsv[1] = (hsv[1] * saturationFactor).coerceIn(0f, 1f)
    val rgbInt = android.graphics.Color.HSVToColor(hsv)
    return Color(
        red = android.graphics.Color.red(rgbInt) / 255f,
        green = android.graphics.Color.green(rgbInt) / 255f,
        blue = android.graphics.Color.blue(rgbInt) / 255f,
        alpha = color.alpha
    )
}

private fun shiftColorHue(color: Color, hueShiftDegrees: Float, sFactor: Float = 1.0f, vFactor: Float = 1.0f): Color {
    val hsv = FloatArray(3)
    val red = (color.red * 255).toInt().coerceIn(0, 255)
    val green = (color.green * 255).toInt().coerceIn(0, 255)
    val blue = (color.blue * 255).toInt().coerceIn(0, 255)
    val argb = android.graphics.Color.rgb(red, green, blue)
    android.graphics.Color.colorToHSV(argb, hsv)
    hsv[0] = (hsv[0] + hueShiftDegrees) % 360f
    if (hsv[0] < 0) hsv[0] += 360f
    hsv[1] = (hsv[1] * sFactor).coerceIn(0f, 1f)
    hsv[2] = (hsv[2] * vFactor).coerceIn(0f, 1f)
    val rgbInt = android.graphics.Color.HSVToColor(hsv)
    return Color(
        red = android.graphics.Color.red(rgbInt) / 255f,
        green = android.graphics.Color.green(rgbInt) / 255f,
        blue = android.graphics.Color.blue(rgbInt) / 255f,
        alpha = color.alpha
    )
}

@Composable
fun MaterialShapesBackground(
    rotationEnabled: Boolean,
    speed: Float = 1.0f,
    isDark: Boolean,
    monochromeEnabled: Boolean = false,
    monochromeSource: Int = 0,
    customR: Float = 0f,
    customG: Float = 191f,
    customB: Float = 165f,
    shapeContrastMode: Int = 1,
    variabilityEnabled: Boolean = false,
    shapeVariabilityMode: Int = 1,
    rotMultA: Float = 1.0f,
    rotMultB: Float = -0.727f,
    rotMultC: Float = 0.533f,
    rotMultD: Float = -0.615f,
    viewModel: WaterViewModel? = null,
    modifier: Modifier = Modifier
) {
    // Relaxed dynamic-only check so STATIC and other custom seed themes can also draw shapes
    if (LocalAppTheme.current == "NONE") return

    val safeSpeed = (speed * 0.6f).coerceIn(0.01f, 0.6f)
    val context = androidx.compose.ui.platform.LocalContext.current
    val prefs = remember(context) { context.getSharedPreferences("pixelwater_prefs", android.content.Context.MODE_PRIVATE) }
    val indSpeedA = prefs.getFloat("gimmick_ind_speed_a", 0.5f)
    val indSpeedB = prefs.getFloat("gimmick_ind_speed_b", 0.5f)
    val indSpeedC = prefs.getFloat("gimmick_ind_speed_c", 0.5f)
    val indSpeedD = prefs.getFloat("gimmick_ind_speed_d", 0.5f)
    
    var offsetA by remember { mutableStateOf(0f) }
    var offsetB by remember { mutableStateOf(45f) }
    var offsetC by remember { mutableStateOf(90f) }
    var offsetD by remember { mutableStateOf(120f) }

    LaunchedEffect(rotationEnabled, safeSpeed, rotMultA, rotMultB, rotMultC, rotMultD, indSpeedA, indSpeedB, indSpeedC, indSpeedD) {
        if (rotationEnabled) {
            var lastTime = withFrameNanos { it }
            while (true) {
                val now = withFrameNanos { it }
                val deltaSec = (now - lastTime) / 1_000_000_000f
                if (deltaSec > 0f) {
                    offsetA = ((offsetA + 9.0f * safeSpeed * indSpeedA * rotMultA * deltaSec) % 360f + 360f) % 360f
                    offsetB = ((offsetB + 9.0f * safeSpeed * indSpeedB * rotMultB * deltaSec) % 360f + 360f) % 360f
                    offsetC = ((offsetC + 9.0f * safeSpeed * indSpeedC * rotMultC * deltaSec) % 360f + 360f) % 360f
                    offsetD = ((offsetD + 9.0f * safeSpeed * indSpeedD * rotMultD * deltaSec) % 360f + 360f) % 360f
                }
                lastTime = now
            }
        }
    }

    val angleA = offsetA
    val angleB = offsetB
    val angleC = offsetC
    val angleD = offsetD

    // Material theme colors
    val shapeUseIndependentDynamicPalette = viewModel?.shapeUseIndependentDynamicPalette?.collectAsStateWithLifecycle()?.value ?: false
    val shapeDynamicPaletteIndex = viewModel?.shapeDynamicPaletteIndex?.collectAsStateWithLifecycle()?.value ?: 0
    val wallpaperColors = viewModel?.wallpaperThemeColors?.collectAsStateWithLifecycle()?.value ?: emptyList()

    val finalColorScheme = if (shapeUseIndependentDynamicPalette) {
        val seeds = if (wallpaperColors.isNotEmpty()) wallpaperColors else listOf(0xFF1D5AAB.toInt(), 0xFF4B5563.toInt(), 0xFFD97706.toInt())
        val seedColorInt = seeds[shapeDynamicPaletteIndex % seeds.size]
        val secSeedInt = if (!monochromeEnabled) seeds[(shapeDynamicPaletteIndex + 1) % seeds.size] else null
        val tertSeedInt = if (!monochromeEnabled) seeds[(shapeDynamicPaletteIndex + 2) % seeds.size] else null
        com.pixelwater.app.ui.theme.generateColorSchemeFromSeed(
            seedColorInt = seedColorInt,
            isDark = isDark,
            isMonochrome = monochromeEnabled,
            monochromeTarget = monochromeSource,
            secondarySeedInt = secSeedInt,
            tertiarySeedInt = tertSeedInt
        )
    } else {
        MaterialTheme.colorScheme
    }

    val themePrimary = finalColorScheme.primary
    val themeSecondary = finalColorScheme.secondary
    val themeTertiary = finalColorScheme.tertiary
    val themePrimaryContainer = finalColorScheme.primaryContainer
    val themeSecondaryContainer = finalColorScheme.secondaryContainer
    val themeTertiaryContainer = finalColorScheme.tertiaryContainer
    
    val monochromeColor = when (monochromeSource) {
        0 -> themePrimary
        1 -> themeSecondary
        2 -> themeTertiary
        else -> if (customR.toInt() == 255 && customG.toInt() == 255 && customB.toInt() == 255) Color.White else Color(customR / 255f, customG / 255f, customB / 255f)
    }

    val colorA = if (monochromeEnabled) monochromeColor else themePrimary
    
    val colorB = if (monochromeEnabled) {
        monochromeColor
    } else if (variabilityEnabled) {
        when (shapeVariabilityMode) {
            0 -> themePrimary
            2 -> themeTertiaryContainer
            else -> themeSecondary
        }
    } else {
        themeSecondary
    }
    
    val colorC = if (monochromeEnabled) {
        monochromeColor
    } else if (variabilityEnabled) {
        when (shapeVariabilityMode) {
            0 -> themePrimary
            2 -> themeSecondaryContainer
            else -> themeTertiary
        }
    } else {
        themeTertiary
    }
    
    val colorD = if (monochromeEnabled) {
        monochromeColor
    } else if (variabilityEnabled) {
        when (shapeVariabilityMode) {
            0 -> themePrimary
            2 -> themePrimaryContainer
            else -> themePrimary
        }
    } else {
        themePrimary
    }

    // Custom Color Overrides
    val shapeAColorMode = viewModel?.shapeAColorMode?.collectAsStateWithLifecycle()?.value ?: 0
    val shapeBColorMode = viewModel?.shapeBColorMode?.collectAsStateWithLifecycle()?.value ?: 1
    val shapeCColorMode = viewModel?.shapeCColorMode?.collectAsStateWithLifecycle()?.value ?: 2
    val shapeDColorMode = viewModel?.shapeDColorMode?.collectAsStateWithLifecycle()?.value ?: 0

    val shapeAColorR = viewModel?.shapeAColorR?.collectAsStateWithLifecycle()?.value ?: 255f
    val shapeAColorG = viewModel?.shapeAColorG?.collectAsStateWithLifecycle()?.value ?: 0f
    val shapeAColorB = viewModel?.shapeAColorB?.collectAsStateWithLifecycle()?.value ?: 0f

    val shapeBColorR = viewModel?.shapeBColorR?.collectAsStateWithLifecycle()?.value ?: 0f
    val shapeBColorG = viewModel?.shapeBColorG?.collectAsStateWithLifecycle()?.value ?: 255f
    val shapeBColorB = viewModel?.shapeBColorB?.collectAsStateWithLifecycle()?.value ?: 0f

    val shapeCColorR = viewModel?.shapeCColorR?.collectAsStateWithLifecycle()?.value ?: 0f
    val shapeCColorG = viewModel?.shapeCColorG?.collectAsStateWithLifecycle()?.value ?: 0f
    val shapeCColorB = viewModel?.shapeCColorB?.collectAsStateWithLifecycle()?.value ?: 255f

    val shapeDColorR = viewModel?.shapeDColorR?.collectAsStateWithLifecycle()?.value ?: 255f
    val shapeDColorG = viewModel?.shapeDColorG?.collectAsStateWithLifecycle()?.value ?: 255f
    val shapeDColorB = viewModel?.shapeDColorB?.collectAsStateWithLifecycle()?.value ?: 255f

    val shapeSaturation = viewModel?.shapeSaturation?.collectAsStateWithLifecycle()?.value ?: 1.0f

    val configProfile = viewModel?.configProfile?.collectAsStateWithLifecycle()?.value ?: "PLUG_AND_PLAY"
    val isPlugAndPlay = configProfile == "PLUG_AND_PLAY"
    val pnpColor = MaterialTheme.colorScheme.surfaceVariant

    val evaluatedColorA = adjustColorSaturation(
        when (shapeAColorMode) {
            0 -> colorA
            1 -> colorB
            2 -> colorC
            3 -> Color(shapeAColorR / 255f, shapeAColorG / 255f, shapeAColorB / 255f)
            else -> colorA
        },
        shapeSaturation
    )

    val evaluatedColorB = adjustColorSaturation(
        when (shapeBColorMode) {
            0 -> colorA
            1 -> colorB
            2 -> colorC
            3 -> Color(shapeBColorR / 255f, shapeBColorG / 255f, shapeBColorB / 255f)
            else -> colorB
        },
        shapeSaturation
    )

    val evaluatedColorC = adjustColorSaturation(
        when (shapeCColorMode) {
            0 -> colorA
            1 -> colorB
            2 -> colorC
            3 -> Color(shapeCColorR / 255f, shapeCColorG / 255f, shapeCColorB / 255f)
            else -> colorC
        },
        shapeSaturation
    )

    val evaluatedColorD = adjustColorSaturation(
        when (shapeDColorMode) {
            0 -> colorA
            1 -> colorB
            2 -> colorC
            3 -> Color(shapeDColorR / 255f, shapeDColorG / 255f, shapeDColorB / 255f)
            else -> colorD
        },
        shapeSaturation
    )

    val shapePaletteShiftEnabled = viewModel?.shapePaletteShiftEnabled?.collectAsStateWithLifecycle()?.value ?: true

    val finalColorA = if (shapePaletteShiftEnabled) shiftColorHue(evaluatedColorA, -12f, sFactor = 0.95f) else evaluatedColorA
    val finalColorB = if (shapePaletteShiftEnabled) shiftColorHue(evaluatedColorB, 8f, sFactor = 1.05f) else evaluatedColorB
    val finalColorC = if (shapePaletteShiftEnabled) shiftColorHue(evaluatedColorC, -24f, sFactor = 0.90f) else evaluatedColorC
    val finalColorD = if (shapePaletteShiftEnabled) shiftColorHue(evaluatedColorD, 24f, sFactor = 1.10f) else evaluatedColorD
    
    // Very subtle low-opacity factor for dynamic integration, influenced by contrast mode
    val backgroundContrast = viewModel?.backgroundContrast?.collectAsStateWithLifecycle()?.value ?: 1.0f
    val baseAlpha = if (isDark) 0.08f else 0.05f
    val alphaFactor = if (backgroundContrast <= 1.0f) {
        baseAlpha * backgroundContrast
    } else {
        val t = (backgroundContrast - 1.0f) / 2.0f
        val curve = t * t
        baseAlpha + (0.95f - baseAlpha) * curve
    }
    val alphaA = alphaFactor
    val alphaB = (alphaFactor * 0.9f).coerceIn(0f, 1f)
    val alphaC = (alphaFactor * 1.1f).coerceIn(0f, 1f)
    val alphaD = (alphaFactor * 0.8f).coerceIn(0f, 1f)

    Box(modifier = modifier.fillMaxSize()) {
        // Shape A: 4-lobed clover style, top-left
        Canvas(
            modifier = Modifier
                .align(Alignment.TopStart)
                .offset(x = (-80).dp, y = (-40).dp)
                .size(340.dp)
                .graphicsLayer(rotationZ = angleA)
        ) {
            val path = createLobedPath(
                centerX = size.width / 2f,
                centerY = size.height / 2f,
                baseRadius = size.width * 0.45f,
                lobes = 4,
                amplitude = size.width * 0.08f,
                isSin = false
            )
            drawPath(path = path, color = finalColorA.copy(alpha = alphaA))
        }

        // Shape B: 5-lobed starry style, bottom-right
        Canvas(
            modifier = Modifier
                .align(Alignment.BottomEnd)
                .offset(x = 100.dp, y = 120.dp)
                .size(400.dp)
                .graphicsLayer(rotationZ = angleB)
        ) {
            val path = createLobedPath(
                centerX = size.width / 2f,
                centerY = size.height / 2f,
                baseRadius = size.width * 0.45f,
                lobes = 5,
                amplitude = size.width * 0.07f,
                isSin = true
            )
            drawPath(path = path, color = finalColorB.copy(alpha = alphaB))
        }

        // Shape C: 3-lobed rounded triangle, center-left
        Canvas(
            modifier = Modifier
                .align(Alignment.CenterStart)
                .offset(x = (-120).dp, y = 140.dp)
                .size(320.dp)
                .graphicsLayer(rotationZ = angleC)
        ) {
            val path = createLobedPath(
                centerX = size.width / 2f,
                centerY = size.height / 2f,
                baseRadius = size.width * 0.42f,
                lobes = 3,
                amplitude = size.width * 0.09f,
                isSin = false
            )
            drawPath(path = path, color = finalColorC.copy(alpha = alphaC))
        }

        // Shape D: 6-lobed subtle blob, top-right
        Canvas(
            modifier = Modifier
                .align(Alignment.TopEnd)
                .offset(x = 120.dp, y = 200.dp)
                .size(280.dp)
                .graphicsLayer(rotationZ = angleD)
        ) {
            val path = createLobedPath(
                centerX = size.width / 2f,
                centerY = size.height / 2f,
                baseRadius = size.width * 0.44f,
                lobes = 6,
                amplitude = size.width * 0.05f,
                isSin = true
            )
            drawPath(path = path, color = finalColorD.copy(alpha = alphaD))
        }
    }
}

@Composable
fun AuraGlowBackground(
    rotationEnabled: Boolean,
    speed: Float = 1.0f,
    isDark: Boolean,
    monochromeEnabled: Boolean = false,
    monochromeSource: Int = 0,
    customR: Float = 0f,
    customG: Float = 191f,
    customB: Float = 165f,
    shapeContrastMode: Int = 1,
    variabilityEnabled: Boolean = false,
    shapeVariabilityMode: Int = 1,
    rotMultA: Float = 1.0f,
    rotMultB: Float = -0.727f,
    rotMultC: Float = 0.533f,
    rotMultD: Float = -0.615f,
    viewModel: WaterViewModel? = null,
    modifier: Modifier = Modifier
) {
    val safeSpeed = (speed * 0.6f).coerceIn(0.01f, 0.6f)
    val context = androidx.compose.ui.platform.LocalContext.current
    val prefs = remember(context) { context.getSharedPreferences("pixelwater_prefs", android.content.Context.MODE_PRIVATE) }
    val indSpeedA = prefs.getFloat("gimmick_ind_speed_a", 0.5f)
    val indSpeedB = prefs.getFloat("gimmick_ind_speed_b", 0.5f)
    val indSpeedC = prefs.getFloat("gimmick_ind_speed_c", 0.5f)
    val indSpeedD = prefs.getFloat("gimmick_ind_speed_d", 0.5f)
    
    // Slight moving/hovering animation over time
    var phaseA by remember { mutableStateOf(0f) }
    var phaseB by remember { mutableStateOf(45f) }
    var phaseC by remember { mutableStateOf(90f) }
    var phaseD by remember { mutableStateOf(120f) }

    LaunchedEffect(rotationEnabled, safeSpeed, rotMultA, rotMultB, rotMultC, rotMultD, indSpeedA, indSpeedB, indSpeedC, indSpeedD) {
        if (rotationEnabled) {
            var lastTime = withFrameNanos { it }
            while (true) {
                val now = withFrameNanos { it }
                val deltaSec = (now - lastTime) / 1_000_000_000f
                if (deltaSec > 0f) {
                    phaseA = (phaseA + 0.15f * safeSpeed * indSpeedA * rotMultA * deltaSec) % (2f * Math.PI.toFloat())
                    phaseB = (phaseB + 0.15f * safeSpeed * indSpeedB * rotMultB * deltaSec) % (2f * Math.PI.toFloat())
                    phaseC = (phaseC + 0.15f * safeSpeed * indSpeedC * rotMultC * deltaSec) % (2f * Math.PI.toFloat())
                    phaseD = (phaseD + 0.15f * safeSpeed * indSpeedD * rotMultD * deltaSec) % (2f * Math.PI.toFloat())
                }
                lastTime = now
            }
        }
    }

    // Material theme colors
    val shapeUseIndependentDynamicPalette = viewModel?.shapeUseIndependentDynamicPalette?.collectAsStateWithLifecycle()?.value ?: false
    val shapeDynamicPaletteIndex = viewModel?.shapeDynamicPaletteIndex?.collectAsStateWithLifecycle()?.value ?: 0
    val wallpaperColors = viewModel?.wallpaperThemeColors?.collectAsStateWithLifecycle()?.value ?: emptyList()

    val finalColorScheme = if (shapeUseIndependentDynamicPalette) {
        val seeds = if (wallpaperColors.isNotEmpty()) wallpaperColors else listOf(0xFF1D5AAB.toInt(), 0xFF4B5563.toInt(), 0xFFD97706.toInt())
        val seedColorInt = seeds[shapeDynamicPaletteIndex % seeds.size]
        val secSeedInt = if (!monochromeEnabled) seeds[(shapeDynamicPaletteIndex + 1) % seeds.size] else null
        val tertSeedInt = if (!monochromeEnabled) seeds[(shapeDynamicPaletteIndex + 2) % seeds.size] else null
        com.pixelwater.app.ui.theme.generateColorSchemeFromSeed(
            seedColorInt = seedColorInt,
            isDark = isDark,
            isMonochrome = monochromeEnabled,
            monochromeTarget = monochromeSource,
            secondarySeedInt = secSeedInt,
            tertiarySeedInt = tertSeedInt
        )
    } else {
        MaterialTheme.colorScheme
    }

    val themePrimary = finalColorScheme.primary
    val themeSecondary = finalColorScheme.secondary
    val themeTertiary = finalColorScheme.tertiary
    val themePrimaryContainer = finalColorScheme.primaryContainer
    val themeSecondaryContainer = finalColorScheme.secondaryContainer
    val themeTertiaryContainer = finalColorScheme.tertiaryContainer
    
    val monochromeColor = when (monochromeSource) {
        0 -> themePrimary
        1 -> themeSecondary
        2 -> themeTertiary
        else -> if (customR.toInt() == 255 && customG.toInt() == 255 && customB.toInt() == 255) Color.White else Color(customR / 255f, customG / 255f, customB / 255f)
    }

    val colorA = if (monochromeEnabled) monochromeColor else themePrimary
    
    val colorB = if (monochromeEnabled) {
        monochromeColor
    } else if (variabilityEnabled) {
        when (shapeVariabilityMode) {
            0 -> themePrimary
            2 -> themeTertiaryContainer
            else -> themeSecondary
        }
    } else {
        themeSecondary
    }
    
    val colorC = if (monochromeEnabled) {
        monochromeColor
    } else if (variabilityEnabled) {
        when (shapeVariabilityMode) {
            0 -> themePrimary
            2 -> themeSecondaryContainer
            else -> themeTertiary
        }
    } else {
        themeTertiary
    }
    
    val colorD = if (monochromeEnabled) {
        monochromeColor
    } else if (variabilityEnabled) {
        when (shapeVariabilityMode) {
            0 -> themePrimary
            2 -> themePrimaryContainer
            else -> themePrimary
        }
    } else {
        themePrimary
    }

    // Custom Color Overrides
    val shapeAColorMode = viewModel?.shapeAColorMode?.collectAsStateWithLifecycle()?.value ?: 0
    val shapeBColorMode = viewModel?.shapeBColorMode?.collectAsStateWithLifecycle()?.value ?: 1
    val shapeCColorMode = viewModel?.shapeCColorMode?.collectAsStateWithLifecycle()?.value ?: 2
    val shapeDColorMode = viewModel?.shapeDColorMode?.collectAsStateWithLifecycle()?.value ?: 0

    val shapeAColorR = viewModel?.shapeAColorR?.collectAsStateWithLifecycle()?.value ?: 255f
    val shapeAColorG = viewModel?.shapeAColorG?.collectAsStateWithLifecycle()?.value ?: 0f
    val shapeAColorB = viewModel?.shapeAColorB?.collectAsStateWithLifecycle()?.value ?: 0f

    val shapeBColorR = viewModel?.shapeBColorR?.collectAsStateWithLifecycle()?.value ?: 0f
    val shapeBColorG = viewModel?.shapeBColorG?.collectAsStateWithLifecycle()?.value ?: 255f
    val shapeBColorB = viewModel?.shapeBColorB?.collectAsStateWithLifecycle()?.value ?: 0f

    val shapeCColorR = viewModel?.shapeCColorR?.collectAsStateWithLifecycle()?.value ?: 0f
    val shapeCColorG = viewModel?.shapeCColorG?.collectAsStateWithLifecycle()?.value ?: 0f
    val shapeCColorB = viewModel?.shapeCColorB?.collectAsStateWithLifecycle()?.value ?: 255f

    val shapeDColorR = viewModel?.shapeDColorR?.collectAsStateWithLifecycle()?.value ?: 255f
    val shapeDColorG = viewModel?.shapeDColorG?.collectAsStateWithLifecycle()?.value ?: 255f
    val shapeDColorB = viewModel?.shapeDColorB?.collectAsStateWithLifecycle()?.value ?: 255f

    val shapeSaturation = viewModel?.shapeSaturation?.collectAsStateWithLifecycle()?.value ?: 1.0f

    val configProfile = viewModel?.configProfile?.collectAsStateWithLifecycle()?.value ?: "PLUG_AND_PLAY"
    val isPlugAndPlay = configProfile == "PLUG_AND_PLAY"
    val pnpColor = MaterialTheme.colorScheme.surfaceVariant

    val evaluatedColorA = adjustColorSaturation(
        when (shapeAColorMode) {
            0 -> colorA
            1 -> colorB
            2 -> colorC
            3 -> Color(shapeAColorR / 255f, shapeAColorG / 255f, shapeAColorB / 255f)
            else -> colorA
        },
        shapeSaturation
    )

    val evaluatedColorB = adjustColorSaturation(
        when (shapeBColorMode) {
            0 -> colorA
            1 -> colorB
            2 -> colorC
            3 -> Color(shapeBColorR / 255f, shapeBColorG / 255f, shapeBColorB / 255f)
            else -> colorB
        },
        shapeSaturation
    )

    val evaluatedColorC = adjustColorSaturation(
        when (shapeCColorMode) {
            0 -> colorA
            1 -> colorB
            2 -> colorC
            3 -> Color(shapeCColorR / 255f, shapeCColorG / 255f, shapeCColorB / 255f)
            else -> colorC
        },
        shapeSaturation
    )

    val evaluatedColorD = adjustColorSaturation(
        when (shapeDColorMode) {
            0 -> colorA
            1 -> colorB
            2 -> colorC
            3 -> Color(shapeDColorR / 255f, shapeDColorG / 255f, shapeDColorB / 255f)
            else -> colorD
        },
        shapeSaturation
    )

    val shapePaletteShiftEnabled = viewModel?.shapePaletteShiftEnabled?.collectAsStateWithLifecycle()?.value ?: true

    val finalColorA = if (shapePaletteShiftEnabled) shiftColorHue(evaluatedColorA, -12f, sFactor = 0.95f) else evaluatedColorA
    val finalColorB = if (shapePaletteShiftEnabled) shiftColorHue(evaluatedColorB, 8f, sFactor = 1.05f) else evaluatedColorB
    val finalColorC = if (shapePaletteShiftEnabled) shiftColorHue(evaluatedColorC, -24f, sFactor = 0.90f) else evaluatedColorC
    val finalColorD = if (shapePaletteShiftEnabled) shiftColorHue(evaluatedColorD, 24f, sFactor = 1.10f) else evaluatedColorD
    
    // For Aura Glow, we want a softer baseAlpha but larger size to create beautiful overlapping gradients.
    // Contrast mode scales the aura intensity.
    val backgroundContrast = viewModel?.backgroundContrast?.collectAsStateWithLifecycle()?.value ?: 1.0f
    val baseAlpha = if (isDark) 0.18f else 0.12f
    val alphaFactor = if (backgroundContrast <= 1.0f) {
        baseAlpha * backgroundContrast
    } else {
        val t = (backgroundContrast - 1.0f) / 2.0f
        val curve = t * t
        baseAlpha + (0.95f - baseAlpha) * curve
    }
    val alphaA = alphaFactor
    val alphaB = (alphaFactor * 0.9f).coerceIn(0f, 1f)
    val alphaC = (alphaFactor * 1.1f).coerceIn(0f, 1f)
    val alphaD = (alphaFactor * 0.8f).coerceIn(0f, 1f)

    Box(modifier = modifier.fillMaxSize()) {
        // We use Canvas to draw fine radial gradients that slightly float/move based on phase variables.
        Canvas(modifier = Modifier.fillMaxSize()) {
            val width = size.width
            val height = size.height

            // Aura A (Top-Start)
            // Slightly drift center based on phaseA
            val centerAX = width * 0.15f + kotlin.math.sin(phaseA).toFloat() * (width * 0.06f)
            val centerAY = height * 0.15f + kotlin.math.cos(phaseA).toFloat() * (height * 0.05f)
            val radiusA = width * 0.55f
            drawCircle(
                brush = Brush.radialGradient(
                    colors = listOf(finalColorA.copy(alpha = alphaA), Color.Transparent),
                    center = Offset(centerAX, centerAY),
                    radius = radiusA
                ),
                radius = radiusA,
                center = Offset(centerAX, centerAY)
            )

            // Aura B (Bottom-End)
            val centerBX = width * 0.85f + kotlin.math.cos(phaseB).toFloat() * (width * 0.07f)
            val centerBY = height * 0.85f + kotlin.math.sin(phaseB).toFloat() * (height * 0.06f)
            val radiusB = width * 0.65f
            drawCircle(
                brush = Brush.radialGradient(
                    colors = listOf(finalColorB.copy(alpha = alphaB), Color.Transparent),
                    center = Offset(centerBX, centerBY),
                    radius = radiusB
                ),
                radius = radiusB,
                center = Offset(centerBX, centerBY)
            )

            // Aura C (Center-Start)
            val centerCX = width * 0.10f + kotlin.math.sin(phaseC).toFloat() * (width * 0.05f)
            val centerCY = height * 0.50f + kotlin.math.cos(phaseC).toFloat() * (height * 0.08f)
            val radiusC = width * 0.50f
            drawCircle(
                brush = Brush.radialGradient(
                    colors = listOf(finalColorC.copy(alpha = alphaC), Color.Transparent),
                    center = Offset(centerCX, centerCY),
                    radius = radiusC
                ),
                radius = radiusC,
                center = Offset(centerCX, centerCY)
            )

            // Aura D (Top-End)
            val centerDX = width * 0.90f + kotlin.math.cos(phaseD).toFloat() * (width * 0.06f)
            val centerDY = height * 0.35f + kotlin.math.sin(phaseD).toFloat() * (height * 0.05f)
            val radiusD = width * 0.45f
            drawCircle(
                brush = Brush.radialGradient(
                    colors = listOf(finalColorD.copy(alpha = alphaD), Color.Transparent),
                    center = Offset(centerDX, centerDY),
                    radius = radiusD
                ),
                radius = radiusD,
                center = Offset(centerDX, centerDY)
            )
        }
    }
}

private fun createLobedPath(
    centerX: Float,
    centerY: Float,
    baseRadius: Float,
    lobes: Int,
    amplitude: Float,
    isSin: Boolean
): Path {
    val path = Path()
    val pointsCount = 180
    for (i in 0 until pointsCount) {
        val angleRad = (i * 2 * Math.PI / pointsCount).toFloat()
        val wave = if (isSin) {
            kotlin.math.sin(lobes * angleRad)
        } else {
            kotlin.math.cos(lobes * angleRad)
        }
        val r = baseRadius + amplitude * wave
        val x = centerX + r * kotlin.math.cos(angleRad)
        val y = centerY + r * kotlin.math.sin(angleRad)
        if (i == 0) {
            path.moveTo(x, y)
        } else {
            path.lineTo(x, y)
        }
    }
    path.close()
    return path
}

@Composable
fun FourPointColorToggle(
    currentMode: Int,
    appLanguage: String,
    onModeSelect: (Int) -> Unit,
    triggerLightHaptic: () -> Unit,
    triggerSnapHaptic: () -> Unit,
    enabled: Boolean = true
) {
    val labels = if (appLanguage == "el") {
        listOf("Πρωτεύον", "Δευτερεύον", "Τριτεύον", "RGB")
    } else {
        listOf("Primary", "Secondary", "Tertiary", "RGB")
    }

    PixelSegmentedToggle(
        labels = labels,
        selectedIndex = currentMode,
        onSelect = { 
            if (currentMode != it) {
                triggerSnapHaptic()
                onModeSelect(it)
            }
        },
        enabled = enabled,
        usePaletteColors = false
    )
}

@Composable
fun IndependentShapeSpeedsCard(
    viewModel: WaterViewModel,
    appLanguage: String,
    modifier: Modifier = Modifier
) {
    var isExpanded by rememberSaveable { mutableStateOf(false) }

    val rotMultA by viewModel.shapeRotMultA.collectAsStateWithLifecycle()
    val rotMultB by viewModel.shapeRotMultB.collectAsStateWithLifecycle()
    val rotMultC by viewModel.shapeRotMultC.collectAsStateWithLifecycle()
    val rotMultD by viewModel.shapeRotMultD.collectAsStateWithLifecycle()

    val isTransparent = LocalTransparentComponentsEnabled.current
    val transLimit = LocalComponentsTransparency.current
    val tc = if (isTransparent) transLimit else 1f

    val isDark = MaterialTheme.colorScheme.background.luminance() < 0.5f

    val themePrimary = MaterialTheme.colorScheme.primary
    val themeSecondary = MaterialTheme.colorScheme.secondary
    val themeTertiary = MaterialTheme.colorScheme.tertiary

    val shapeMonochromeEnabled by viewModel.shapeMonochromeEnabled.collectAsStateWithLifecycle()
    val shapeMonochromeSource by viewModel.shapeMonochromeSource.collectAsStateWithLifecycle()
    val shapeCustomR by viewModel.shapeCustomR.collectAsStateWithLifecycle()
    val shapeCustomG by viewModel.shapeCustomG.collectAsStateWithLifecycle()
    val shapeCustomB by viewModel.shapeCustomB.collectAsStateWithLifecycle()
    val shapeVariabilityEnabled by viewModel.shapeVariabilityEnabled.collectAsStateWithLifecycle()
    val shapeVariabilityMode by viewModel.shapeVariabilityMode.collectAsStateWithLifecycle()

    val monochromeColor = when (shapeMonochromeSource) {
        0 -> themePrimary
        1 -> themeSecondary
        2 -> themeTertiary
        else -> if (shapeCustomR.toInt() == 255 && shapeCustomG.toInt() == 255 && shapeCustomB.toInt() == 255) Color.White else Color(shapeCustomR / 255f, shapeCustomG / 255f, shapeCustomB / 255f)
    }

    val colorA = if (shapeMonochromeEnabled) monochromeColor else themePrimary
    val colorB = if (shapeMonochromeEnabled) monochromeColor else if (shapeVariabilityEnabled) {
        when (shapeVariabilityMode) {
            0 -> themePrimary
            2 -> MaterialTheme.colorScheme.tertiaryContainer
            else -> themeSecondary
        }
    } else {
        themeSecondary
    }
    val colorC = if (shapeMonochromeEnabled) monochromeColor else if (shapeVariabilityEnabled) {
        when (shapeVariabilityMode) {
            0 -> themePrimary
            2 -> MaterialTheme.colorScheme.secondaryContainer
            else -> themeTertiary
        }
    } else {
        themeTertiary
    }
    val colorD = if (shapeMonochromeEnabled) monochromeColor else if (shapeVariabilityEnabled) {
        when (shapeVariabilityMode) {
            0 -> themePrimary
            2 -> MaterialTheme.colorScheme.primaryContainer
            else -> themePrimary
        }
    } else {
        themePrimary
    }

    val shapeAColorMode by viewModel.shapeAColorMode.collectAsStateWithLifecycle()
    val shapeBColorMode by viewModel.shapeBColorMode.collectAsStateWithLifecycle()
    val shapeCColorMode by viewModel.shapeCColorMode.collectAsStateWithLifecycle()
    val shapeDColorMode by viewModel.shapeDColorMode.collectAsStateWithLifecycle()

    val shapeAColorR by viewModel.shapeAColorR.collectAsStateWithLifecycle()
    val shapeAColorG by viewModel.shapeAColorG.collectAsStateWithLifecycle()
    val shapeAColorB by viewModel.shapeAColorB.collectAsStateWithLifecycle()

    val shapeBColorR by viewModel.shapeBColorR.collectAsStateWithLifecycle()
    val shapeBColorG by viewModel.shapeBColorG.collectAsStateWithLifecycle()
    val shapeBColorB by viewModel.shapeBColorB.collectAsStateWithLifecycle()

    val shapeCColorR by viewModel.shapeCColorR.collectAsStateWithLifecycle()
    val shapeCColorG by viewModel.shapeCColorG.collectAsStateWithLifecycle()
    val shapeCColorB by viewModel.shapeCColorB.collectAsStateWithLifecycle()

    val shapeDColorR by viewModel.shapeDColorR.collectAsStateWithLifecycle()
    val shapeDColorG by viewModel.shapeDColorG.collectAsStateWithLifecycle()
    val shapeDColorB by viewModel.shapeDColorB.collectAsStateWithLifecycle()

    val evalColorA = when (shapeAColorMode) {
        0 -> colorA
        1 -> colorB
        2 -> colorC
        3 -> Color(shapeAColorR / 255f, shapeAColorG / 255f, shapeAColorB / 255f)
        else -> colorA
    }
    val evalColorB = when (shapeBColorMode) {
        0 -> colorA
        1 -> colorB
        2 -> colorC
        3 -> Color(shapeBColorR / 255f, shapeBColorG / 255f, shapeBColorB / 255f)
        else -> colorB
    }
    val evalColorC = when (shapeCColorMode) {
        0 -> colorA
        1 -> colorB
        2 -> colorC
        3 -> Color(shapeCColorR / 255f, shapeCColorG / 255f, shapeCColorB / 255f)
        else -> colorC
    }
    val evalColorD = when (shapeDColorMode) {
        0 -> colorA
        1 -> colorB
        2 -> colorC
        3 -> Color(shapeDColorR / 255f, shapeDColorG / 255f, shapeDColorB / 255f)
        else -> colorD
    }

    Column(
        modifier = modifier
            .fillMaxWidth()
            .clip(androidx.compose.foundation.shape.RoundedCornerShape(20.dp))
            .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.40f * tc))
            .then(
                if (!isDark) {
                    Modifier.border(
                        width = 1.dp,
                        color = MaterialTheme.colorScheme.outline.copy(alpha = 0.25f),
                        shape = androidx.compose.foundation.shape.RoundedCornerShape(20.dp)
                    )
                } else Modifier
            )
            .animateContentSize()
    ) {
        // Tappable Header Row
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .clickable {
                    isExpanded = !isExpanded
                    viewModel.triggerButtonHaptic()
                }
                .padding(14.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Icon(
                    imageVector = Icons.Rounded.Speed,
                    contentDescription = null,
                    tint = MaterialTheme.colorScheme.primary.copy(alpha = tc),
                    modifier = Modifier.size(20.dp)
                )
                Column {
                    Text(
                        text = if (appLanguage == "el") "Ανεξάρτητη Ταχύτητα Σχημάτων" else "Independent Shape Speeds",
                        fontWeight = FontWeight.Bold,
                        fontSize = 15.sp,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    Text(
                        text = if (isExpanded) {
                            if (appLanguage == "el") "Απόκρυψη ρυθμίσεων ταχύτητας σχήματος" else "Hide independent speed options"
                        } else {
                            if (appLanguage == "el") "Εμφάνιση ρυθμίσεων ταχύτητας σχήματος" else "Show independent speed options"
                        },
                        fontSize = 11.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f * tc)
                    )
                }
            }

            IconButton(
                onClick = {
                    isExpanded = !isExpanded
                    viewModel.triggerButtonHaptic()
                },
                modifier = Modifier.size(32.dp)
            ) {
                Icon(
                    imageVector = if (isExpanded) Icons.Rounded.KeyboardArrowUp else Icons.Rounded.KeyboardArrowDown,
                    contentDescription = if (isExpanded) "Collapse" else "Expand",
                    tint = MaterialTheme.colorScheme.onSurfaceVariant
                )
            }
        }

        AnimatedVisibility(
            visible = isExpanded,
            enter = fadeIn() + expandVertically(),
            exit = fadeOut() + shrinkVertically()
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(start = 14.dp, end = 14.dp, bottom = 14.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                val shapesData = listOf(
                    Triple("A", evalColorA, rotMultA),
                    Triple("B", evalColorB, rotMultB),
                    Triple("C", evalColorC, rotMultC),
                    Triple("D", evalColorD, rotMultD)
                )

                shapesData.forEach { (name, color, multiplier) ->
                    val label = when (name) {
                        "A" -> if (appLanguage == "el") "Σχήμα Α (Πάνω Αριστερά)" else "Shape A (Top-Left)"
                        "B" -> if (appLanguage == "el") "Σχήμα Β (Κάτω Δεξιά)" else "Shape B (Bottom-Right)"
                        "C" -> if (appLanguage == "el") "Σχήμα Γ (Μέση Αριστερά)" else "Shape C (Mid-Left)"
                        else -> if (appLanguage == "el") "Σχήμα Δ (Μέση Δεξιά)" else "Shape D (Mid-Right)"
                    }

                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(MaterialTheme.colorScheme.surface.copy(alpha = 0.35f * tc), androidx.compose.foundation.shape.RoundedCornerShape(12.dp))
                            .padding(10.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(12.dp)
                                        .clip(CircleShape)
                                        .background(color)
                                )
                                Text(
                                    text = label,
                                    fontWeight = FontWeight.SemiBold,
                                    fontSize = 12.sp,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                            }

                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                Text(
                                    text = if (multiplier == 0f) {
                                        if (appLanguage == "el") "Παγωμένο" else "Frozen"
                                    } else {
                                        "${String.format(java.util.Locale.US, "%.2f", multiplier)}x"
                                    },
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 12.sp,
                                    color = if (multiplier == 0f) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary
                                )

                                IconButton(
                                    onClick = {
                                        val newVal = if (multiplier == 0f) {
                                            when (name) {
                                                "A" -> 1.0f
                                                "B" -> -0.727f
                                                "C" -> 0.533f
                                                else -> -0.615f
                                            }
                                        } else {
                                            0.0f
                                        }
                                        when (name) {
                                            "A" -> viewModel.updateShapeRotMultA(newVal)
                                            "B" -> viewModel.updateShapeRotMultB(newVal)
                                            "C" -> viewModel.updateShapeRotMultC(newVal)
                                            else -> viewModel.updateShapeRotMultD(newVal)
                                        }
                                        viewModel.triggerButtonHaptic()
                                    },
                                    modifier = Modifier.size(24.dp)
                                ) {
                                    Icon(
                                        imageVector = if (multiplier == 0f) Icons.Rounded.PlayArrow else Icons.Rounded.Pause,
                                        contentDescription = null,
                                        tint = MaterialTheme.colorScheme.onSurfaceVariant,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(6.dp))

                        CapsulePatternSlider(
                            value = multiplier,
                            onValueChange = { newValue ->
                                val formatted = String.format(java.util.Locale.US, "%.2f", newValue).toFloat()
                                when (name) {
                                    "A" -> viewModel.updateShapeRotMultA(formatted)
                                    "B" -> viewModel.updateShapeRotMultB(formatted)
                                    "C" -> viewModel.updateShapeRotMultC(formatted)
                                    else -> viewModel.updateShapeRotMultD(formatted)
                                }
                            },
                            valueRange = -2.0f..2.0f,
                            triggerHaptic = { viewModel.triggerSliderHaptic() },
                            activeColor = color,
                            modifier = Modifier.fillMaxWidth()
                        )
                    }
                }
            }
        }
    }
}

@Composable
fun InteractiveSpinCanvasCard(
    viewModel: WaterViewModel,
    appLanguage: String,
    onScrollLockChange: (Boolean) -> Unit = {},
    modifier: Modifier = Modifier
) {
    val rotMultA by viewModel.shapeRotMultA.collectAsStateWithLifecycle()
    val rotMultB by viewModel.shapeRotMultB.collectAsStateWithLifecycle()
    val rotMultC by viewModel.shapeRotMultC.collectAsStateWithLifecycle()
    val rotMultD by viewModel.shapeRotMultD.collectAsStateWithLifecycle()
    
    val isDark = MaterialTheme.colorScheme.background.luminance() < 0.5f
    val shapeMonochromeEnabled by viewModel.shapeMonochromeEnabled.collectAsStateWithLifecycle()
    val shapeMonochromeSource by viewModel.shapeMonochromeSource.collectAsStateWithLifecycle()
    val shapeCustomR by viewModel.shapeCustomR.collectAsStateWithLifecycle()
    val shapeCustomG by viewModel.shapeCustomG.collectAsStateWithLifecycle()
    val shapeCustomB by viewModel.shapeCustomB.collectAsStateWithLifecycle()
    val shapeContrastMode by viewModel.shapeContrastMode.collectAsStateWithLifecycle()
    val shapeVariabilityEnabled by viewModel.shapeVariabilityEnabled.collectAsStateWithLifecycle()
    val shapeVariabilityMode by viewModel.shapeVariabilityMode.collectAsStateWithLifecycle()
    val materialShapesRotationSpeed by viewModel.materialShapesRotationSpeed.collectAsStateWithLifecycle()
    val auraGlowRotationSpeed by viewModel.auraGlowRotationSpeed.collectAsStateWithLifecycle()
    val auraGlowEnabled by viewModel.auraGlowEnabled.collectAsStateWithLifecycle()
    val materialShapesEnabled by viewModel.materialShapesEnabled.collectAsStateWithLifecycle()

    val currentSpeed = if (materialShapesEnabled) materialShapesRotationSpeed else auraGlowRotationSpeed

    // Customize Dialog states
    var activeCustomizingShape by remember { mutableStateOf<String?>(null) }
    
    val shapeAColorMode by viewModel.shapeAColorMode.collectAsStateWithLifecycle()
    val shapeBColorMode by viewModel.shapeBColorMode.collectAsStateWithLifecycle()
    val shapeCColorMode by viewModel.shapeCColorMode.collectAsStateWithLifecycle()
    val shapeDColorMode by viewModel.shapeDColorMode.collectAsStateWithLifecycle()

    val shapeAColorR by viewModel.shapeAColorR.collectAsStateWithLifecycle()
    val shapeAColorG by viewModel.shapeAColorG.collectAsStateWithLifecycle()
    val shapeAColorB by viewModel.shapeAColorB.collectAsStateWithLifecycle()

    val shapeBColorR by viewModel.shapeBColorR.collectAsStateWithLifecycle()
    val shapeBColorG by viewModel.shapeBColorG.collectAsStateWithLifecycle()
    val shapeBColorB by viewModel.shapeBColorB.collectAsStateWithLifecycle()

    val shapeCColorR by viewModel.shapeCColorR.collectAsStateWithLifecycle()
    val shapeCColorG by viewModel.shapeCColorG.collectAsStateWithLifecycle()
    val shapeCColorB by viewModel.shapeCColorB.collectAsStateWithLifecycle()

    val shapeDColorR by viewModel.shapeDColorR.collectAsStateWithLifecycle()
    val shapeDColorG by viewModel.shapeDColorG.collectAsStateWithLifecycle()
    val shapeDColorB by viewModel.shapeDColorB.collectAsStateWithLifecycle()

    val shapeUseIndependentDynamicPalette by viewModel.shapeUseIndependentDynamicPalette.collectAsStateWithLifecycle()
    val shapeDynamicPaletteIndex by viewModel.shapeDynamicPaletteIndex.collectAsStateWithLifecycle()
    val wallpaperColors by viewModel.wallpaperThemeColors.collectAsStateWithLifecycle()
    val shapeSaturation by viewModel.shapeSaturation.collectAsStateWithLifecycle()

    val finalColorScheme = if (shapeUseIndependentDynamicPalette) {
        val seeds = if (wallpaperColors.isNotEmpty()) wallpaperColors else listOf(0xFF1D5AAB.toInt(), 0xFF4B5563.toInt(), 0xFFD97706.toInt())
        val seedColorInt = seeds[shapeDynamicPaletteIndex % seeds.size]
        val shapeMonochromeEnabled = viewModel?.shapeMonochromeEnabled?.collectAsStateWithLifecycle()?.value ?: false
        val shapeMonochromeSource = viewModel?.shapeMonochromeSource?.collectAsStateWithLifecycle()?.value ?: 0
        val secSeedInt = if (!shapeMonochromeEnabled) seeds[(shapeDynamicPaletteIndex + 1) % seeds.size] else null
        val tertSeedInt = if (!shapeMonochromeEnabled) seeds[(shapeDynamicPaletteIndex + 2) % seeds.size] else null
        com.pixelwater.app.ui.theme.generateColorSchemeFromSeed(
            seedColorInt = seedColorInt,
            isDark = isDark,
            isMonochrome = shapeMonochromeEnabled,
            monochromeTarget = shapeMonochromeSource,
            secondarySeedInt = secSeedInt,
            tertiarySeedInt = tertSeedInt
        )
    } else {
        MaterialTheme.colorScheme
    }

    val themePrimary = finalColorScheme.primary
    val themeSecondary = finalColorScheme.secondary
    val themeTertiary = finalColorScheme.tertiary
    val themePrimaryContainer = finalColorScheme.primaryContainer
    val themeSecondaryContainer = finalColorScheme.secondaryContainer
    val themeTertiaryContainer = finalColorScheme.tertiaryContainer
    
    val monochromeColor = when (shapeMonochromeSource) {
        0 -> themePrimary
        1 -> themeSecondary
        2 -> themeTertiary
        else -> if (shapeCustomR.toInt() == 255 && shapeCustomG.toInt() == 255 && shapeCustomB.toInt() == 255) Color.White else Color(shapeCustomR / 255f, shapeCustomG / 255f, shapeCustomB / 255f)
    }

    val colorA = if (shapeMonochromeEnabled) monochromeColor else themePrimary
    val colorB = if (shapeMonochromeEnabled) monochromeColor else if (shapeVariabilityEnabled) {
        when (shapeVariabilityMode) {
            0 -> themePrimary
            2 -> themeTertiaryContainer
            else -> themeSecondary
        }
    } else {
        themeSecondary
    }
    val colorC = if (shapeMonochromeEnabled) monochromeColor else if (shapeVariabilityEnabled) {
        when (shapeVariabilityMode) {
            0 -> themePrimary
            2 -> themeSecondaryContainer
            else -> themeTertiary
        }
    } else {
        themeTertiary
    }
    val colorD = if (shapeMonochromeEnabled) monochromeColor else if (shapeVariabilityEnabled) {
        when (shapeVariabilityMode) {
            0 -> themePrimary
            2 -> themePrimaryContainer
            else -> themePrimary
        }
    } else {
        themePrimary
    }

    // Evaluated shape colors, applying individual overrides if configured
    val evaluatedColorA = adjustColorSaturation(
        when (shapeAColorMode) {
            0 -> colorA
            1 -> colorB
            2 -> colorC
            3 -> Color(shapeAColorR / 255f, shapeAColorG / 255f, shapeAColorB / 255f)
            else -> colorA
        },
        shapeSaturation
    )

    val evaluatedColorB = adjustColorSaturation(
        when (shapeBColorMode) {
            0 -> colorA
            1 -> colorB
            2 -> colorC
            3 -> Color(shapeBColorR / 255f, shapeBColorG / 255f, shapeBColorB / 255f)
            else -> colorB
        },
        shapeSaturation
    )

    val evaluatedColorC = adjustColorSaturation(
        when (shapeCColorMode) {
            0 -> colorA
            1 -> colorB
            2 -> colorC
            3 -> Color(shapeCColorR / 255f, shapeCColorG / 255f, shapeCColorB / 255f)
            else -> colorC
        },
        shapeSaturation
    )

    val evaluatedColorD = adjustColorSaturation(
        when (shapeDColorMode) {
            0 -> colorA
            1 -> colorB
            2 -> colorC
            3 -> Color(shapeDColorR / 255f, shapeDColorG / 255f, shapeDColorB / 255f)
            else -> colorD
        },
        shapeSaturation
    )

    val backgroundContrast = viewModel?.backgroundContrast?.collectAsStateWithLifecycle()?.value ?: 1.0f
    val baseAlpha = if (isDark) 0.16f else 0.11f
    val contrastAlpha = if (backgroundContrast <= 1.0f) {
        baseAlpha * backgroundContrast
    } else {
        val t = (backgroundContrast - 1.0f) / 2.0f
        baseAlpha + t * (1.0f - baseAlpha)
    }
    val alphaFactor = when (shapeContrastMode) {
        0 -> contrastAlpha * 0.6f
        2 -> contrastAlpha * 2.2f
        3 -> 0.55f
        4 -> 0.85f
        else -> contrastAlpha * 1.0f
    }

    Column(
        modifier = modifier
            .fillMaxWidth()
            .clip(androidx.compose.foundation.shape.RoundedCornerShape(20.dp))
            .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f))
            .then(
                if (!isDark) {
                    Modifier.border(
                        width = 1.dp,
                        color = MaterialTheme.colorScheme.outline.copy(alpha = 0.25f),
                        shape = androidx.compose.foundation.shape.RoundedCornerShape(20.dp)
                    )
                } else Modifier
            )
            .padding(12.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        Column(horizontalAlignment = Alignment.CenterHorizontally) {
            Text(
                text = if (appLanguage == "el") "Διαδραστικός Καμβάς Περιστροφής" else "Interactive Spin Canvas",
                fontWeight = FontWeight.Bold,
                fontSize = 15.sp,
                color = MaterialTheme.colorScheme.onSurface
            )
            Spacer(modifier = Modifier.height(2.dp))
            Text(
                text = if (appLanguage == "el") 
                    "Σύρετε οριζόντια οποιοδήποτε σχήμα για να περιστραφεί ή πατήστε το για να το προσαρμόσετε." 
                    else "Swipe horizontally on a shape to adjust spin, or tap once to change color.",
                fontSize = 11.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                textAlign = TextAlign.Center,
                modifier = Modifier.padding(horizontal = 4.dp)
            )
        }

        Box(
            modifier = Modifier
                .width(220.dp)
                .height(300.dp)
                .clip(androidx.compose.foundation.shape.RoundedCornerShape(32.dp))
                .border(3.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.4f), androidx.compose.foundation.shape.RoundedCornerShape(32.dp))
                .background(if (isDark) Color(0xFF111416) else Color(0xFFF0F4F8))
                .padding(6.dp)
        ) {
            var localOffsetA by remember { mutableStateOf(0f) }
            var localOffsetB by remember { mutableStateOf(45f) }
            var localOffsetC by remember { mutableStateOf(90f) }
            var localOffsetD by remember { mutableStateOf(120f) }

            val context = androidx.compose.ui.platform.LocalContext.current
            val prefs = remember(context) { context.getSharedPreferences("pixelwater_prefs", android.content.Context.MODE_PRIVATE) }
            val indSpeedA = prefs.getFloat("gimmick_ind_speed_a", 0.5f)
            val indSpeedB = prefs.getFloat("gimmick_ind_speed_b", 0.5f)
            val indSpeedC = prefs.getFloat("gimmick_ind_speed_c", 0.5f)
            val indSpeedD = prefs.getFloat("gimmick_ind_speed_d", 0.5f)

            LaunchedEffect(rotMultA, rotMultB, rotMultC, rotMultD, currentSpeed, indSpeedA, indSpeedB, indSpeedC, indSpeedD) {
                val effectiveSpeed = (currentSpeed * 0.6f).coerceIn(0.01f, 0.6f)
                var lastTime = withFrameNanos { it }
                while (true) {
                    val now = withFrameNanos { it }
                    val deltaSec = (now - lastTime) / 1_000_000_000f
                    if (deltaSec > 0f) {
                        localOffsetA = ((localOffsetA + 9.0f * effectiveSpeed * indSpeedA * rotMultA * deltaSec) % 360f + 360f) % 360f
                        localOffsetB = ((localOffsetB + 9.0f * effectiveSpeed * indSpeedB * rotMultB * deltaSec) % 360f + 360f) % 360f
                        localOffsetC = ((localOffsetC + 9.0f * effectiveSpeed * indSpeedC * rotMultC * deltaSec) % 360f + 360f) % 360f
                        localOffsetD = ((localOffsetD + 9.0f * effectiveSpeed * indSpeedD * rotMultD * deltaSec) % 360f + 360f) % 360f
                    }
                    lastTime = now
                }
            }

            InteractiveShapeItem(
                shapeName = "A",
                color = evaluatedColorA.copy(alpha = alphaFactor * 1.5f),
                angle = localOffsetA,
                lobes = 4,
                isSin = false,
                multiplier = rotMultA,
                onMultiplierChange = { viewModel.updateShapeRotMultA(it) },
                onTap = {
                    activeCustomizingShape = "A"
                    viewModel.triggerButtonHaptic()
                },
                onScrollLockChange = onScrollLockChange,
                isAuraGlow = auraGlowEnabled,
                modifier = Modifier
                    .size(90.dp)
                    .align(Alignment.TopStart)
                    .offset(x = (-20).dp, y = 10.dp)
            )

            InteractiveShapeItem(
                shapeName = "D",
                color = evaluatedColorD.copy(alpha = alphaFactor * 1.3f),
                angle = localOffsetD,
                lobes = 6,
                isSin = true,
                multiplier = rotMultD,
                onMultiplierChange = { viewModel.updateShapeRotMultD(it) },
                onTap = {
                    activeCustomizingShape = "D"
                    viewModel.triggerButtonHaptic()
                },
                onScrollLockChange = onScrollLockChange,
                isAuraGlow = auraGlowEnabled,
                modifier = Modifier
                    .size(80.dp)
                    .align(Alignment.TopEnd)
                    .offset(x = 15.dp, y = 50.dp)
            )

            InteractiveShapeItem(
                shapeName = "C",
                color = evaluatedColorC.copy(alpha = alphaFactor * 1.6f),
                angle = localOffsetC,
                lobes = 3,
                isSin = false,
                multiplier = rotMultC,
                onMultiplierChange = { viewModel.updateShapeRotMultC(it) },
                onTap = {
                    activeCustomizingShape = "C"
                    viewModel.triggerButtonHaptic()
                },
                onScrollLockChange = onScrollLockChange,
                isAuraGlow = auraGlowEnabled,
                modifier = Modifier
                    .size(85.dp)
                    .align(Alignment.CenterStart)
                    .offset(x = (-25).dp, y = 110.dp)
            )

            InteractiveShapeItem(
                shapeName = "B",
                color = evaluatedColorB.copy(alpha = alphaFactor * 1.4f),
                angle = localOffsetB,
                lobes = 5,
                isSin = true,
                multiplier = rotMultB,
                onMultiplierChange = { viewModel.updateShapeRotMultB(it) },
                onTap = {
                    activeCustomizingShape = "B"
                    viewModel.triggerButtonHaptic()
                },
                onScrollLockChange = onScrollLockChange,
                isAuraGlow = auraGlowEnabled,
                modifier = Modifier
                    .size(95.dp)
                    .align(Alignment.BottomEnd)
                    .offset(x = 15.dp, y = (-10).dp)
            )
            
            Box(
                modifier = Modifier
                    .width(80.dp)
                    .height(4.dp)
                    .clip(androidx.compose.foundation.shape.RoundedCornerShape(2.dp))
                    .background(MaterialTheme.colorScheme.onSurface.copy(alpha = 0.2f))
                    .align(Alignment.BottomCenter)
                    .offset(y = (-4).dp)
            )
        }

        Row(
            modifier = Modifier.fillMaxWidth().padding(horizontal = 4.dp),
            horizontalArrangement = Arrangement.spacedBy(4.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Button(
                onClick = { viewModel.randomizeShapeRotations() },
                modifier = Modifier.weight(1f).height(38.dp),
                shape = androidx.compose.foundation.shape.RoundedCornerShape(12.dp),
                colors = ButtonDefaults.buttonColors(
                    containerColor = MaterialTheme.colorScheme.primary.copy(alpha = 0.15f),
                    contentColor = MaterialTheme.colorScheme.primary
                ),
                contentPadding = PaddingValues(0.dp)
            ) {
                Icon(Icons.Rounded.Shuffle, contentDescription = null, modifier = Modifier.size(16.dp))
                Spacer(modifier = Modifier.width(4.dp))
                Text(
                    text = if (appLanguage == "el") "Τυχαία" else "Randomize",
                    fontWeight = FontWeight.Bold,
                    fontSize = 11.sp
                )
            }

            val isAllFrozen = rotMultA == 0f && rotMultB == 0f && rotMultC == 0f && rotMultD == 0f
            Button(
                onClick = {
                    viewModel.toggleFreezeAllShapes()
                },
                modifier = Modifier.weight(1f).height(38.dp),
                shape = androidx.compose.foundation.shape.RoundedCornerShape(12.dp),
                colors = ButtonDefaults.buttonColors(
                    containerColor = if (isAllFrozen) {
                        MaterialTheme.colorScheme.primary.copy(alpha = 0.15f)
                    } else {
                        MaterialTheme.colorScheme.error.copy(alpha = 0.12f)
                    },
                    contentColor = if (isAllFrozen) {
                        MaterialTheme.colorScheme.primary
                    } else {
                        MaterialTheme.colorScheme.error
                    }
                ),
                contentPadding = PaddingValues(0.dp)
            ) {
                Icon(
                    imageVector = if (isAllFrozen) Icons.Rounded.PlayArrow else Icons.Rounded.Stop,
                    contentDescription = null,
                    modifier = Modifier.size(17.dp)
                )
                Spacer(modifier = Modifier.width(4.dp))
                Text(
                    text = if (isAllFrozen) {
                        if (appLanguage == "el") "Ξεκλείδωμα" else "Unfreeze All"
                    } else {
                        if (appLanguage == "el") "Ακινητοποίηση" else "Freeze All"
                    },
                    fontWeight = FontWeight.Bold,
                    fontSize = 11.sp
                )
            }

            Button(
                onClick = {
                    viewModel.updateShapeRotMultA(1.0f)
                    viewModel.updateShapeRotMultB(-0.727f)
                    viewModel.updateShapeRotMultC(0.533f)
                    viewModel.updateShapeRotMultD(-0.615f)
                    viewModel.triggerButtonHaptic()
                },
                modifier = Modifier.weight(1f).height(38.dp),
                shape = androidx.compose.foundation.shape.RoundedCornerShape(12.dp),
                colors = ButtonDefaults.buttonColors(
                    containerColor = MaterialTheme.colorScheme.secondary.copy(alpha = 0.12f),
                    contentColor = MaterialTheme.colorScheme.secondary
                ),
                contentPadding = PaddingValues(0.dp)
            ) {
                Icon(Icons.Rounded.Refresh, contentDescription = null, modifier = Modifier.size(15.dp))
                Spacer(modifier = Modifier.width(4.dp))
                Text(
                    text = if (appLanguage == "el") "Επαναφορά" else "Reset",
                    fontWeight = FontWeight.Bold,
                    fontSize = 11.sp
                )
            }
        }

        Spacer(modifier = Modifier.height(8.dp))
        Row(
            modifier = Modifier.fillMaxWidth().padding(horizontal = 4.dp),
            horizontalArrangement = Arrangement.spacedBy(4.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Button(
                onClick = {
                    viewModel.randomizeShapeColors()
                },
                modifier = Modifier.weight(1f).height(38.dp),
                shape = androidx.compose.foundation.shape.RoundedCornerShape(12.dp),
                colors = ButtonDefaults.buttonColors(
                    containerColor = MaterialTheme.colorScheme.tertiary.copy(alpha = 0.15f),
                    contentColor = MaterialTheme.colorScheme.tertiary
                ),
                contentPadding = PaddingValues(0.dp)
            ) {
                Icon(Icons.Rounded.Palette, contentDescription = null, modifier = Modifier.size(16.dp))
                Spacer(modifier = Modifier.width(4.dp))
                Text(
                    text = if (appLanguage == "el") "Τυχαία Χρώματα" else "Random Colors",
                    fontWeight = FontWeight.Bold,
                    fontSize = 11.sp
                )
            }

            Button(
                onClick = {
                    viewModel.resetShapeColors()
                },
                modifier = Modifier.weight(1f).height(38.dp),
                shape = androidx.compose.foundation.shape.RoundedCornerShape(12.dp),
                colors = ButtonDefaults.buttonColors(
                    containerColor = MaterialTheme.colorScheme.secondary.copy(alpha = 0.12f),
                    contentColor = MaterialTheme.colorScheme.secondary
                ),
                contentPadding = PaddingValues(0.dp)
            ) {
                Icon(Icons.Rounded.Refresh, contentDescription = null, modifier = Modifier.size(15.dp))
                Spacer(modifier = Modifier.width(4.dp))
                Text(
                    text = if (appLanguage == "el") "Επαναφορά Χρωμάτων" else "Reset Colors",
                    fontWeight = FontWeight.Bold,
                    fontSize = 11.sp
                )
            }
        }
    }

    // Color customization dialog
    val shapeName = activeCustomizingShape
    if (shapeName != null) {
        val mode = when (shapeName) {
            "A" -> shapeAColorMode
            "B" -> shapeBColorMode
            "C" -> shapeCColorMode
            "D" -> shapeDColorMode
            else -> 0
        }
        val r = when (shapeName) {
            "A" -> shapeAColorR
            "B" -> shapeBColorR
            "C" -> shapeCColorR
            "D" -> shapeDColorR
            else -> 255f
        }
        val g = when (shapeName) {
            "A" -> shapeAColorG
            "B" -> shapeBColorG
            "C" -> shapeCColorG
            "D" -> shapeDColorG
            else -> 0f
        }
        val b = when (shapeName) {
            "A" -> shapeAColorB
            "B" -> shapeBColorB
            "C" -> shapeCColorB
            "D" -> shapeDColorB
            else -> 0f
        }

        val currentEvaluated = when (shapeName) {
            "A" -> evaluatedColorA
            "B" -> evaluatedColorB
            "C" -> evaluatedColorC
            "D" -> evaluatedColorD
            else -> themePrimary
        }

        AlertDialog(
            onDismissRequest = { activeCustomizingShape = null },
            confirmButton = {
                TextButton(onClick = { activeCustomizingShape = null }) {
                    Text(if (appLanguage == "el") "Τέλος" else "Done", fontWeight = FontWeight.Bold)
                }
            },
            title = {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = if (appLanguage == "el") "Προσαρμογή Σχήματος $shapeName" else "Customize Shape $shapeName",
                        fontWeight = FontWeight.ExtraBold,
                        fontSize = 18.sp
                    )
                    Box(
                        modifier = Modifier
                            .size(32.dp)
                            .clip(CircleShape)
                            .background(currentEvaluated)
                            .border(1.5.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.2f), CircleShape)
                    )
                }
            },
            text = {
                Column(
                    modifier = Modifier.fillMaxWidth(),
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    Text(
                        text = if (appLanguage == "el") {
                            "Επιλέξτε πηγή χρώματος από την επιλεγμένη παλέτα ταπετσαρίας ή ορίστε προσαρμοσμένο RGB."
                        } else {
                            "Choose a color source from the selected wallpaper palette or set custom RGB values."
                        },
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )

                    FourPointColorToggle(
                        currentMode = mode,
                        appLanguage = appLanguage,
                        onModeSelect = { newMode ->
                            viewModel.updateShapeColorMode(shapeName, newMode)
                        },
                        triggerLightHaptic = { viewModel.triggerToggleLightHaptic() },
                        triggerSnapHaptic = { viewModel.triggerToggleSnapHaptic() }
                    )

                    if (mode == 3) {
                        HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f))
                        
                        Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                            // RED SLIDER
                            Column {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = if (appLanguage == "el") "Κόκκινο (R)" else "Red (R)",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFFFF2D55)
                                    )
                                    Text(
                                        text = "${r.toInt()}",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.ExtraBold,
                                        color = MaterialTheme.colorScheme.onSurface
                                    )
                                }
                                Spacer(modifier = Modifier.height(4.dp))
                                CapsulePatternSlider(
                                    value = r,
                                    onValueChange = { newR ->
                                        viewModel.updateShapeRGB(shapeName, newR, g, b)
                                    },
                                    valueRange = 0f..255f,
                                    triggerHaptic = { viewModel.triggerSliderHaptic() },
                                    modifier = Modifier.fillMaxWidth()
                                )
                            }

                            // GREEN SLIDER
                            Column {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = if (appLanguage == "el") "Πράσινο (G)" else "Green (G)",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFF4CD964)
                                    )
                                    Text(
                                        text = "${g.toInt()}",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.ExtraBold,
                                        color = MaterialTheme.colorScheme.onSurface
                                    )
                                }
                                Spacer(modifier = Modifier.height(4.dp))
                                CapsulePatternSlider(
                                    value = g,
                                    onValueChange = { newG ->
                                        viewModel.updateShapeRGB(shapeName, r, newG, b)
                                    },
                                    valueRange = 0f..255f,
                                    triggerHaptic = { viewModel.triggerSliderHaptic() },
                                    modifier = Modifier.fillMaxWidth()
                                )
                            }

                            // BLUE SLIDER
                            Column {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = if (appLanguage == "el") "Μπλε (B)" else "Blue (B)",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFF007AFF)
                                    )
                                    Text(
                                        text = "${b.toInt()}",
                                        fontSize = 12.sp,
                                        fontWeight = FontWeight.ExtraBold,
                                        color = MaterialTheme.colorScheme.onSurface
                                    )
                                }
                                Spacer(modifier = Modifier.height(4.dp))
                                CapsulePatternSlider(
                                    value = b,
                                    onValueChange = { newB ->
                                        viewModel.updateShapeRGB(shapeName, r, g, newB)
                                    },
                                    valueRange = 0f..255f,
                                    triggerHaptic = { viewModel.triggerSliderHaptic() },
                                    modifier = Modifier.fillMaxWidth()
                                )
                            }
                        }
                    }
                }
            },
            shape = RoundedCornerShape(28.dp),
            containerColor = MaterialTheme.colorScheme.surface
        )
    }
}

@Composable
fun InteractiveShapeItem(
    shapeName: String,
    color: Color,
    angle: Float,
    lobes: Int,
    isSin: Boolean,
    multiplier: Float,
    onMultiplierChange: (Float) -> Unit,
    onTap: () -> Unit,
    onScrollLockChange: (Boolean) -> Unit = {},
    isAuraGlow: Boolean = false,
    modifier: Modifier = Modifier
) {
    var dragAccumulator by remember { mutableStateOf(0f) }

    Box(
        modifier = modifier
            .pointerInput(shapeName) {
                awaitPointerEventScope {
                    while (true) {
                        val event = awaitPointerEvent()
                        if (event.changes.any { it.changedToDown() }) {
                            onScrollLockChange(true)
                        }
                        if (event.changes.any { it.changedToUp() }) {
                            onScrollLockChange(false)
                        }
                    }
                }
            }
            .pointerInput(shapeName) {
                detectTapGestures(
                    onTap = { onTap() }
                )
            }
            .pointerInput(shapeName) {
                detectHorizontalDragGestures(
                    onDragStart = {
                        dragAccumulator = 0f
                        onScrollLockChange(true)
                    },
                    onHorizontalDrag = { change, dragAmount ->
                        dragAccumulator += dragAmount
                        change.consume()
                    },
                    onDragEnd = {
                        onScrollLockChange(false)
                        if (Math.abs(dragAccumulator) > 10f) {
                            val sign = if (dragAccumulator > 0) 1.0f else -1.0f
                            val calculatedSpeed = (Math.abs(dragAccumulator) / 50.0f).coerceIn(0.3f, 1.8f)
                            val finalMult = String.format(java.util.Locale.US, "%.2f", sign * calculatedSpeed).toFloat()
                            onMultiplierChange(finalMult)
                        }
                    },
                    onDragCancel = {
                        onScrollLockChange(false)
                    }
                )
            },
        contentAlignment = Alignment.Center
    ) {
        Canvas(modifier = Modifier.fillMaxSize().graphicsLayer(rotationZ = angle)) {
            if (isAuraGlow) {
                drawCircle(
                    brush = Brush.radialGradient(
                        colors = listOf(color, Color.Transparent),
                        center = Offset(size.width / 2f, size.height / 2f),
                        radius = size.width * 0.5f
                    ),
                    radius = size.width * 0.5f
                )
            } else {
                val path = createLobedPath(
                    centerX = size.width / 2f,
                    centerY = size.height / 2f,
                    baseRadius = size.width * 0.44f,
                    lobes = lobes,
                    amplitude = size.width * 0.08f,
                    isSin = isSin
                )
                drawPath(path = path, color = color)
            }
        }

        Box(
            modifier = Modifier
                .size(24.dp)
                .clip(androidx.compose.foundation.shape.CircleShape)
                .background(MaterialTheme.colorScheme.surface.copy(alpha = 0.85f))
                .border(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.3f), androidx.compose.foundation.shape.CircleShape),
            contentAlignment = Alignment.Center
        ) {
            if (multiplier == 0f) {
                Icon(
                    imageVector = Icons.Rounded.Stop,
                    contentDescription = null,
                    tint = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f),
                    modifier = Modifier.size(12.dp)
                )
            } else {
                Text(
                    text = if (multiplier > 0f) "↻" else "↺",
                    fontWeight = FontWeight.ExtraBold,
                    fontSize = 11.sp,
                    color = MaterialTheme.colorScheme.primary
                )
            }
        }
    }
}

@Composable
fun Button(
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    shape: androidx.compose.ui.graphics.Shape? = null,
    colors: androidx.compose.material3.ButtonColors? = null,
    elevation: androidx.compose.material3.ButtonElevation? = null,
    border: androidx.compose.foundation.BorderStroke? = null,
    contentPadding: PaddingValues = ButtonDefaults.ContentPadding,
    interactionSource: androidx.compose.foundation.interaction.MutableInteractionSource = remember { androidx.compose.foundation.interaction.MutableInteractionSource() },
    content: @Composable RowScope.() -> Unit
) {
    val hapticTrigger = LocalButtonHapticTrigger.current
    val isDark = MaterialTheme.colorScheme.background.luminance() < 0.5f
    var isActive by remember { mutableStateOf(false) }
    val scope = rememberCoroutineScope()
    var resetJob by remember { mutableStateOf<kotlinx.coroutines.Job?>(null) }
    val scaleAnim = remember { Animatable(1f) }
    
    val cornerRadius by animateDpAsState(
        targetValue = if (isActive) 100.dp else 14.dp,
        animationSpec = spring(
            dampingRatio = Spring.DampingRatioMediumBouncy,
            stiffness = Spring.StiffnessLow
        ),
        label = "btn_shape"
    )
    
    val startContainer = MaterialTheme.colorScheme.primary
    val startContent = MaterialTheme.colorScheme.onPrimary
    val activeContainer = if (isDark) Color(0xFFE2E2E2) else MaterialTheme.colorScheme.primary
    val activeContent = if (isDark) Color(0xFF191C1C) else MaterialTheme.colorScheme.onPrimary
    
    val containerColor by animateColorAsState(
        targetValue = if (isActive) activeContainer else startContainer,
        animationSpec = tween(250),
        label = "btn_container_color"
    )
    
    val contentColor by animateColorAsState(
        targetValue = if (isActive) activeContent else startContent,
        animationSpec = tween(250),
        label = "btn_content_color"
    )
    
    androidx.compose.material3.Button(
        onClick = {
            if (enabled) {
                hapticTrigger()
                onClick()
                isActive = true
                scope.launch {
                    scaleAnim.animateTo(0.85f, animationSpec = tween(50))
                    scaleAnim.animateTo(1.08f, animationSpec = spring(dampingRatio = 0.45f, stiffness = 300f))
                    scaleAnim.animateTo(1.0f, animationSpec = spring())
                }
                resetJob?.cancel()
                resetJob = scope.launch {
                    delay(2000)
                    isActive = false
                }
            }
        },
        modifier = modifier
            .scale(scaleAnim.value)
            .clip(RoundedCornerShape(maxOf(0f, cornerRadius.value).dp)),
        enabled = enabled,
        shape = RoundedCornerShape(maxOf(0f, cornerRadius.value).dp),
        colors = ButtonDefaults.buttonColors(
            containerColor = containerColor,
            contentColor = contentColor,
            disabledContainerColor = colors?.disabledContainerColor ?: MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f),
            disabledContentColor = colors?.disabledContentColor ?: MaterialTheme.colorScheme.onSurface.copy(alpha = 0.38f)
        ),
        elevation = elevation,
        border = border,
        contentPadding = contentPadding,
        interactionSource = interactionSource,
        content = content
    )
}

