        enabled = enabled,
        colors = androidx.compose.material3.IconButtonDefaults.iconButtonColors(
            containerColor = Color.Transparent,
            contentColor = contentColor,
            disabledContainerColor = Color.Transparent,
            disabledContentColor = colors?.disabledContentColor ?: MaterialTheme.colorScheme.onSurface.copy(alpha = 0.38f)
        ),
        interactionSource = interactionSource,
        content = content
    )
}

@Composable
fun FilledIconButton(
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
    enabled: Boolean = true,
    shape: androidx.compose.ui.graphics.Shape? = null,
    colors: androidx.compose.material3.IconButtonColors? = null,
    interactionSource: androidx.compose.foundation.interaction.MutableInteractionSource = remember { androidx.compose.foundation.interaction.MutableInteractionSource() },
    content: @Composable () -> Unit
) {
    val hapticTrigger = LocalButtonHapticTrigger.current
    val isDark = MaterialTheme.colorScheme.background.luminance() < 0.5f
    var isActive by remember { mutableStateOf(false) }
    val scope = rememberCoroutineScope()
    var resetJob by remember { mutableStateOf<kotlinx.coroutines.Job?>(null) }
    val scaleAnim = remember { Animatable(1f) }
    
    val cornerRadius by animateDpAsState(
        targetValue = if (isActive) 100.dp else 14.dp,
        animationSpec = spring(
            dampingRatio = Spring.DampingRatioMediumBouncy,
            stiffness = Spring.StiffnessLow
        ),
        label = "filled_icon_btn_shape"
    )
    
    val startContainer = MaterialTheme.colorScheme.primaryContainer
    val startContent = MaterialTheme.colorScheme.onPrimaryContainer
    val activeContainer = if (isDark) Color(0xFFE2E2E2) else MaterialTheme.colorScheme.primary
    val activeContent = if (isDark) Color(0xFF191C1C) else MaterialTheme.colorScheme.onPrimary
    
    val containerColor by animateColorAsState(
        targetValue = if (isActive) activeContainer else startContainer,
        animationSpec = tween(250),
        label = "filled_icon_container"
    )
    
    val contentColor by animateColorAsState(
        targetValue = if (isActive) activeContent else startContent,
        animationSpec = tween(250),
        label = "filled_icon_content"
    )
    
    androidx.compose.material3.FilledIconButton(
        onClick = {
            if (enabled) {
                hapticTrigger()
                onClick()
                isActive = true
                scope.launch {
                    scaleAnim.animateTo(0.85f, animationSpec = tween(50))
                    scaleAnim.animateTo(1.08f, animationSpec = spring(dampingRatio = 0.45f, stiffness = 300f))
                    scaleAnim.animateTo(1.0f, animationSpec = spring())
                }
                resetJob?.cancel()
                resetJob = scope.launch {
                    delay(2000)
                    isActive = false
                }
            }
        },
        modifier = modifier
            .scale(scaleAnim.value)
            .clip(RoundedCornerShape(maxOf(0f, cornerRadius.value).dp)),
        enabled = enabled,
        shape = RoundedCornerShape(maxOf(0f, cornerRadius.value).dp),
        colors = androidx.compose.material3.IconButtonDefaults.filledIconButtonColors(
            containerColor = containerColor,
            contentColor = contentColor,
            disabledContainerColor = colors?.disabledContainerColor ?: MaterialTheme.colorScheme.onSurface.copy(alpha = 0.12f),
            disabledContentColor = colors?.disabledContentColor ?: MaterialTheme.colorScheme.onSurface.copy(alpha = 0.38f)
        ),
        interactionSource = interactionSource,
        content = content
    )
}

@Composable
fun PreviewDotsIcon(isSelected: Boolean, tint: Color, modifier: Modifier = Modifier) {
    androidx.compose.foundation.Canvas(modifier = modifier) {
        val w = size.width
        val h = size.height
        val cx = w / 2f
        val cy = h / 2f
        val dotRadius = 1.8.dp.toPx()
        val gap = 3.dp.toPx()
        
        if (isSelected) {
            val colors = listOf(
                Color(0xFF4285F4), // Blue
                Color(0xFFEA4335), // Red
                Color(0xFFFBBC05), // Yellow
                Color(0xFF34A853)  // Green
            )
            val dotW = 2 * dotRadius
            val totalW = 4 * dotW + 3 * gap
            val startX = cx - totalW / 2f + dotRadius
            for (i in 0..3) {
                drawCircle(
                    color = colors[i],
                    radius = dotRadius,
                    center = androidx.compose.ui.geometry.Offset(startX + i * (dotW + gap), cy)
                )
            }
        } else {
            val circleR = 4.dp.toPx()
            for (i in 0..3) {
                val angle = (i * Math.PI / 2) + (Math.PI / 4)
                val dx = cx + circleR * kotlin.math.cos(angle).toFloat()
                val dy = cy + circleR * kotlin.math.sin(angle).toFloat()
                drawCircle(
                    color = tint,
                    radius = dotRadius,
                    center = androidx.compose.ui.geometry.Offset(dx, dy)
                )
            }
        }
    }
}

