                                Box(modifier = Modifier.padding(6.dp)) { 
                                    if (index == 2) {
                                        PreviewDotsIcon(isSelected = false, tint = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f), modifier = Modifier.size(20.dp))
                                    } else {
                                        Icon(imageVector = icon, contentDescription = null, tint = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f), modifier = Modifier.size(20.dp))
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun LiveWidgetPreview(
    generalCornerRadius: Int,
