        "translucent" -> {
            if (widgetTranslucentInvisible) Color.Transparent
            else if (isDarkTheme) Color(0xAA1E293B) else Color(0xAACAB5FE)
        }
        "oled" -> Color.Black
        else -> if (isDarkTheme) Color(0xFF1E1F22) else Color(0xFFF8FAFC)
    }
    val previewBorder = if (selectedBgOption == "translucent") {
        if (widgetTranslucentInvisible) null
        else BorderStroke(1.dp, Color.White.copy(alpha = 0.25f))
    } else null

    val onBgColor = if (selectedBgOption == "oled") {
        Color.White
    } else if (selectedBgOption == "translucent") {
        Color.White
    } else {
        if (isDarkTheme) Color.White else Color(0xFF111827)
    }

