    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(34.dp)
            .background(Color.White.copy(alpha = 0.12f), shape = RoundedCornerShape(12.dp))
            .border(0.5.dp, Color.White.copy(alpha = 0.08f), shape = RoundedCornerShape(12.dp))
            .padding(horizontal = 8.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Box(
            modifier = Modifier
                .size(6.dp)
                .background(accentColor, shape = CircleShape)
        )
        Spacer(modifier = Modifier.width(8.dp))
        Column(modifier = Modifier.weight(1f)) {
            Text(text = title, fontSize = 7.sp, fontWeight = FontWeight.SemiBold, color = accentColor)
            Text(text = "+${amount} ml", fontSize = 10.sp, fontWeight = FontWeight.Bold, color = onBg)
        }
    }
}

fun androidx.compose.foundation.lazy.LazyListScope.renderLegalDisclaimerSection(
    viewModel: WaterViewModel,
    appLanguage: String,
    onBack: () -> Unit
) {
    item {
        val isDark = MaterialTheme.colorScheme.background.luminance() < 0.5f
        val isFrostedGlassEnabled = LocalFrostedGlassEnabled.current
        val frostedTransparency = LocalFrostedGlassTransparency.current
