                            },
                            shape = RoundedCornerShape(12.dp),
                            colors = ButtonDefaults.buttonColors(
                                containerColor = MaterialTheme.colorScheme.primaryContainer,
                                contentColor = MaterialTheme.colorScheme.onPrimaryContainer
                            )
                        ) {
                            Text(if (appLanguage == "el") "Συγχρονισμός" else "Sync", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                        }
                    }

                    HorizontalDivider(color = strokeColor.copy(alpha = 0.3f))

                    // Sideload Wear OS Companion
                    WearSettingRow(
                        icon = Icons.Rounded.Watch,
                        title = if (appLanguage == "el") "Εγκατάσταση Wear OS (Offline)" else "Sideload Wear OS Companion",
                        subtitle = if (appLanguage == "el") "Εξαγωγή & κοινοποίηση του Wear OS APK για άμεση εγκατάσταση." else "Extract & share the pre-bundled Wear OS companion APK."
                    ) {
                        Button(
                            onClick = { viewModel.exportPrebundledWearApk(context) },
                            shape = RoundedCornerShape(12.dp),
                            colors = ButtonDefaults.buttonColors(
                                containerColor = MaterialTheme.colorScheme.secondaryContainer,
                                contentColor = MaterialTheme.colorScheme.onSecondaryContainer
                            )
                        ) {
                            Text(if (appLanguage == "el") "Εξαγωγή" else "Sideload", fontSize = 12.sp, fontWeight = FontWeight.Bold)
                        }
                    }

                    // Device Entry Display
                    if (isNerdMode) {
                        HorizontalDivider(color = strokeColor.copy(alpha = 0.3f))
                        WearSettingRow(
                            icon = Icons.Rounded.Smartphone,
                            title = if (appLanguage == "el") "Εμφάνιση Προέλευσης Συσκευής" else "Device Entry Display",
                            subtitle = if (appLanguage == "el") "Εμφανίζει το όνομα της συσκευής (π.χ. Pixel Watch) στις καταγραφές." else "Show device name (e.g. Pixel Watch) in log history."
                        ) {
                            ChunkySettingSwitch(
                                checked = showDeviceOriginText,
                                onCheckedChange = { viewModel.updateShowDeviceOriginText(it) }
                            )
                        }

                        if (showDeviceOriginText) {
                            HorizontalDivider(color = strokeColor.copy(alpha = 0.3f))
                            Column(
                                modifier = Modifier.fillMaxWidth()
                            ) {
                                WearSettingRow(
                                    icon = Icons.Rounded.Title,
                                    title = if (appLanguage == "el") "Έντονη γραφή ονόματος" else "Bold Device Name",
                                    subtitle = if (appLanguage == "el") "Κάνει το όνομα της συσκευής να εμφανίζεται με έντονα γράμματα." else "Display the device name in bold letters in the logs."
                                ) {
                                    ChunkySettingSwitch(
                                        checked = boldDeviceOriginText,
                                        onCheckedChange = { viewModel.updateBoldDeviceOriginText(it) }
                                    )
                                }
                            }
                        }
                    }
                }
            }

            // 7. DEVELOPER SETTINGS
            val currentUserEmail = remember {
                com.google.firebase.auth.FirebaseAuth.getInstance().currentUser?.email ?: ""
            }
            val isDeveloper = currentUserEmail.lowercase().trim() == "antoniskouroudis1@gmail.com"

            if (isDeveloper) {
                val wearCircleSize by viewModel.wearCircleSize.collectAsStateWithLifecycle()
                val currentSizeText = if (wearCircleSize > 0) {
                    "${wearCircleSize}dp"
                } else {
                    if (appLanguage == "el") "190dp (Προεπιλογή - Διευρυμένο)" else "190dp (Default - Expanded)"
                }
                val wearDevOverlayEnabled by viewModel.wearDevOverlayEnabled.collectAsStateWithLifecycle()
                val wearDevOverlayR by viewModel.wearDevOverlayR.collectAsStateWithLifecycle()
                val wearDevOverlayG by viewModel.wearDevOverlayG.collectAsStateWithLifecycle()
                val wearDevOverlayB by viewModel.wearDevOverlayB.collectAsStateWithLifecycle()

                ChunkySettingCard(
                    modifier = Modifier
                        .fillMaxWidth()
                        
                ) {
                    Column(
                        modifier = Modifier.fillMaxWidth().padding(18.dp),
                        verticalArrangement = Arrangement.spacedBy(20.dp)
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(12.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(36.dp)
                                    .background(MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.4f), shape = CircleShape),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Rounded.Build,
                                    contentDescription = null,
                                    tint = MaterialTheme.colorScheme.primary,
                                    modifier = Modifier.size(18.dp)
                                )
                            }
                            Text(
                                text = if (appLanguage == "el") "Εργαλεία Προγραμματιστή" else "Developer Settings",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.primary
                            )
                        }

                        HorizontalDivider(color = strokeColor.copy(alpha = 0.3f))

                        Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = if (appLanguage == "el") "Μέγεθος Κύκλου Προόδου" else "Progress Circle Size",
                                        fontSize = 14.sp,
                                        fontWeight = FontWeight.SemiBold,
                                        color = MaterialTheme.colorScheme.onSurface
                                    )
                                    Text(
                                        text = if (appLanguage == "el") "Προσαρμογή μεγέθους κύκλου στο Wear OS ($currentSizeText)." else "Adjust progress circle size on Wear OS ($currentSizeText).",
                                        fontSize = 12.sp,
                                        color = MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                }
                                Button(
                                    onClick = { viewModel.resetWearCircleSizeToDefault() },
                                    colors = ButtonDefaults.buttonColors(
                                        containerColor = MaterialTheme.colorScheme.errorContainer,
                                        contentColor = MaterialTheme.colorScheme.onErrorContainer
                                    ),
                                    contentPadding = PaddingValues(horizontal = 10.dp, vertical = 4.dp),
                                    modifier = Modifier.height(28.dp)
                                ) {
                                    Text(if (appLanguage == "el") "Επαναφορά" else "Reset", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                                }
                            }

                            val sliderVal = if (wearCircleSize > 0) wearCircleSize.toFloat() else 190f
                            CapsulePatternSlider(
                                value = sliderVal,
                                onValueChange = { viewModel.updateWearCircleSize(it.toInt()) },
                                valueRange = 100f..600f,
                                stepsCount = 501,
                                triggerHaptic = { viewModel.triggerSliderHaptic() },
                                modifier = Modifier.fillMaxWidth()
                            )
                        }

                        HorizontalDivider(color = strokeColor.copy(alpha = 0.3f))

                        WearSettingRow(
                            icon = Icons.Rounded.DeveloperMode,
                            title = if (appLanguage == "el") "Δοκιμαστικό RGB Overlay" else "Dev Visual Target Overlay",
                            subtitle = if (appLanguage == "el") "Εμφάνιση χρωματιστού overlay πίσω από τον κύκλο." else "Show custom overlay behind progress circle."
                        ) {
                            ChunkySettingSwitch(
                                checked = wearDevOverlayEnabled,
                                onCheckedChange = { viewModel.updateWearDevOverlayEnabled(it) }
                            )
                        }

                        if (wearDevOverlayEnabled) {
                            HorizontalDivider(color = strokeColor.copy(alpha = 0.3f))
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    ,
                                verticalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                Text(
                                    text = "Overlay Color: RGB($wearDevOverlayR, $wearDevOverlayG, $wearDevOverlayB)",
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.onSurface
                                )

                                // Red
                                Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
                                    Text("R: ", fontSize = 12.sp, modifier = Modifier.width(20.dp), fontWeight = FontWeight.Bold)
                                    CapsulePatternSlider(
                                        value = wearDevOverlayR.toFloat(),
                                        onValueChange = { viewModel.updateWearDevOverlayR(it.toInt()) },
                                        valueRange = 0f..255f,
                                        stepsCount = 256,
                                        triggerHaptic = { viewModel.triggerSliderHaptic() },
                                        activeColor = Color.Red,
                                        modifier = Modifier.weight(1f)
                                    )
                                    Text("$wearDevOverlayR", fontSize = 12.sp, modifier = Modifier.width(30.dp), textAlign = androidx.compose.ui.text.style.TextAlign.End)
                                }

                                // Green
                                Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
                                    Text("G: ", fontSize = 12.sp, modifier = Modifier.width(20.dp), fontWeight = FontWeight.Bold)
                                    CapsulePatternSlider(
                                        value = wearDevOverlayG.toFloat(),
                                        onValueChange = { viewModel.updateWearDevOverlayG(it.toInt()) },
                                        valueRange = 0f..255f,
                                        stepsCount = 256,
                                        triggerHaptic = { viewModel.triggerSliderHaptic() },
                                        activeColor = Color.Green,
                                        modifier = Modifier.weight(1f)
                                    )
