                                }

                                // Blue
                                Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
                                    Text("B: ", fontSize = 12.sp, modifier = Modifier.width(20.dp), fontWeight = FontWeight.Bold)
                                    CapsulePatternSlider(
                                        value = wearDevOverlayB.toFloat(),
                                        onValueChange = { viewModel.updateWearDevOverlayB(it.toInt()) },
                                        valueRange = 0f..255f,
                                        stepsCount = 256,
                                        triggerHaptic = { viewModel.triggerSliderHaptic() },
                                        activeColor = Color.Blue,
                                        modifier = Modifier.weight(1f)
                                    )
                                    Text("$wearDevOverlayB", fontSize = 12.sp, modifier = Modifier.width(30.dp), textAlign = androidx.compose.ui.text.style.TextAlign.End)
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun WearOsLivePreview(
    viewModel: WaterViewModel,
    appLanguage: String,
    modifier: Modifier = Modifier
) {
    val context = androidx.compose.ui.platform.LocalContext.current
    val wearThemeColor by viewModel.wearThemeColor.collectAsStateWithLifecycle()
    val wearShowRemaining by viewModel.wearShowRemaining.collectAsStateWithLifecycle()
    val wearShowTomorrowDay by viewModel.wearShowTomorrowDay.collectAsStateWithLifecycle()
    val wearProgressCircleEnabled by viewModel.wearProgressCircleEnabled.collectAsStateWithLifecycle()
    val wearInsideCircleRemoved by viewModel.wearInsideCircleRemoved.collectAsStateWithLifecycle()
    val wearProgressCircleThickness by viewModel.wearProgressCircleThickness.collectAsStateWithLifecycle()
    val wearCustomThickness by viewModel.wearCustomThickness.collectAsStateWithLifecycle()
    val wearCustomTextSize by viewModel.wearCustomTextSize.collectAsStateWithLifecycle()
    val wearTextColorType by viewModel.wearTextColorType.collectAsStateWithLifecycle()
    val wearTextColorStatic by viewModel.wearTextColorStatic.collectAsStateWithLifecycle()
    val wearGraphDaysPrior by viewModel.wearGraphDaysPrior.collectAsStateWithLifecycle()
    val wearGraphPillarThickness by viewModel.wearGraphPillarThickness.collectAsStateWithLifecycle()
    val wearGraphHorizontalPadding by viewModel.wearGraphHorizontalPadding.collectAsStateWithLifecycle()
    val wearPastDaysToShow by viewModel.wearPastDaysToShow.collectAsStateWithLifecycle()
    
    val wearCrownRotationEnabled by viewModel.wearCrownRotationEnabled.collectAsStateWithLifecycle()
    val wearCrownRotationReverse by viewModel.wearCrownRotationReverse.collectAsStateWithLifecycle()
    val wearCrownClicksPerMl by viewModel.wearCrownClicksPerMl.collectAsStateWithLifecycle()
    
    val wearSwipeMode by viewModel.wearSwipeMode.collectAsStateWithLifecycle()
    val wearGraphSwipeDir by viewModel.wearGraphSwipeDir.collectAsStateWithLifecycle()
    val wearLongPressDeleteEnabled by viewModel.wearLongPressDeleteEnabled.collectAsStateWithLifecycle()
    val wearLongPressDeleteDuration by viewModel.wearLongPressDeleteDuration.collectAsStateWithLifecycle()
    val wearRamOptimization by viewModel.wearRamOptimization.collectAsStateWithLifecycle()
    val wearDevOverlayEnabled by viewModel.wearDevOverlayEnabled.collectAsStateWithLifecycle()
    val wearDevOverlayR by viewModel.wearDevOverlayR.collectAsStateWithLifecycle()
    val wearDevOverlayG by viewModel.wearDevOverlayG.collectAsStateWithLifecycle()
    val wearDevOverlayB by viewModel.wearDevOverlayB.collectAsStateWithLifecycle()

    val totalIntakeToday by viewModel.totalIntakeToday.collectAsStateWithLifecycle()
    val dailyGoalMl by viewModel.dailyGoalMl.collectAsStateWithLifecycle()
    val quickAddAmount by viewModel.quickAddAmount.collectAsStateWithLifecycle()
    val goalLineSquiggly by viewModel.goalLineSquiggly.collectAsStateWithLifecycle()

    // Resolve primary color & text color identically to Wear app
    val primaryColor = remember(wearThemeColor) {
        Color(viewModel.resolveWearThemeColorValue(wearThemeColor))
    }

    val displayTextColor = remember(wearTextColorType, wearTextColorStatic, wearThemeColor) {
        Color(viewModel.resolveWearTextColorValue())
    }

    val watchBgColor = if (wearDevOverlayEnabled) {
        Color(wearDevOverlayR, wearDevOverlayG, wearDevOverlayB)
    } else {
        Color.Black
    }

    val daysPrior = wearGraphDaysPrior
    val maxForward = if (wearShowTomorrowDay) 1 else 0

    val sandboxIntakes = remember { mutableStateMapOf<Int, Int>() }
    val sandboxGoals = remember { mutableStateMapOf<Int, Int>() }

    LaunchedEffect(totalIntakeToday, dailyGoalMl, daysPrior) {
        for (i in -daysPrior..maxForward) {
            if (!sandboxIntakes.containsKey(i)) {
                if (i == 0) {
                    sandboxIntakes[0] = totalIntakeToday
                } else if (i > 0) {
                    sandboxIntakes[i] = 0
                } else {
                    val seedFactor = when (i % 3) {
                        0 -> 0.45f
                        -1 -> 1.15f
                        else -> 0.85f
                    }
                    sandboxIntakes[i] = (dailyGoalMl * seedFactor).toInt()
                }
            }
            if (!sandboxGoals.containsKey(i)) {
                sandboxGoals[i] = dailyGoalMl
            }
        }
    }

    var sandboxTodayTouched by remember { mutableStateOf(false) }
    LaunchedEffect(totalIntakeToday) {
        if (!sandboxTodayTouched && sandboxIntakes.containsKey(0)) {
            sandboxIntakes[0] = totalIntakeToday
        }
    }

    var sandboxOffset by remember { mutableStateOf(0) }
    var sandboxLayer by remember { mutableStateOf(1) } // 1 = Main, 2 = Stats Graph

    val currentIntake = sandboxIntakes[sandboxOffset] ?: 0
    val currentGoal = sandboxGoals[sandboxOffset] ?: 2000

    val progress = remember(currentIntake, currentGoal) {
        if (currentGoal > 0) currentIntake.toFloat() / currentGoal.toFloat() else 0f
    }

    val animatedProgress by if (wearRamOptimization) {
        remember(progress) { mutableStateOf(progress) }
    } else {
        androidx.compose.animation.core.animateFloatAsState(
            targetValue = progress.coerceIn(0f, 3f),
            animationSpec = androidx.compose.animation.core.spring(
                dampingRatio = androidx.compose.animation.core.Spring.DampingRatioMediumBouncy,
                stiffness = androidx.compose.animation.core.Spring.StiffnessLow
            ),
            label = "preview_wear_progress"
        )
    }

    val coroutineScope = rememberCoroutineScope()

    val surpassedColor = remember(primaryColor) {
        val hsv = FloatArray(3)
        android.graphics.Color.colorToHSV(primaryColor.toArgb(), hsv)
        hsv[0] = (hsv[0] + 120f) % 360f
        hsv[1] = hsv[1].coerceAtLeast(0.85f)
        hsv[2] = hsv[2].coerceAtLeast(0.85f)
        Color(android.graphics.Color.HSVToColor(hsv))
    }
    val surpassedColor2 = remember(primaryColor) {
        val hsv = FloatArray(3)
        android.graphics.Color.colorToHSV(primaryColor.toArgb(), hsv)
        hsv[0] = (hsv[0] + 240f) % 360f
        hsv[1] = hsv[1].coerceAtLeast(0.85f)
        hsv[2] = hsv[2].coerceAtLeast(0.85f)
        Color(android.graphics.Color.HSVToColor(hsv))
    }

    val infiniteTransition = rememberInfiniteTransition(label = "sandbox_breathing")
    val breatheScale by if (wearRamOptimization) {
        remember { mutableStateOf(1.0f) }
    } else {
        infiniteTransition.animateFloat(
            initialValue = 0.88f,
            targetValue = 1.04f,
            animationSpec = androidx.compose.animation.core.infiniteRepeatable(
                animation = androidx.compose.animation.core.tween(2400, easing = androidx.compose.animation.core.FastOutSlowInEasing),
                repeatMode = androidx.compose.animation.core.RepeatMode.Reverse
            ),
            label = "sandbox_breathe"
        )
    }

    val centerTextScale = remember { androidx.compose.animation.core.Animatable(1f) }
    LaunchedEffect(currentIntake) {
        if (!wearRamOptimization) {
            centerTextScale.animateTo(
                targetValue = 1.14f,
                animationSpec = androidx.compose.animation.core.tween(durationMillis = 110, easing = androidx.compose.animation.core.FastOutSlowInEasing)
            )
            centerTextScale.animateTo(
                targetValue = 1.0f,
                animationSpec = androidx.compose.animation.core.spring(
                    dampingRatio = androidx.compose.animation.core.Spring.DampingRatioMediumBouncy,
                    stiffness = androidx.compose.animation.core.Spring.StiffnessMedium
                )
            )
        } else {
            centerTextScale.snapTo(1.0f)
        }
    }

    var isHeaderVisible by remember { mutableStateOf(true) }
    val headerAlpha by if (wearRamOptimization) {
        remember(isHeaderVisible) { mutableStateOf(if (isHeaderVisible) 1f else 0f) }
    } else {
        androidx.compose.animation.core.animateFloatAsState(
            targetValue = if (isHeaderVisible) 1f else 0f,
            animationSpec = androidx.compose.animation.core.tween(durationMillis = 300),
            label = "preview_header_alpha"
        )
    }

    LaunchedEffect(sandboxOffset) {
        isHeaderVisible = true
    }

    var hasSnappedHaptic by remember { mutableStateOf(false) }
    var crownDragAccumulator by remember { mutableStateOf(0f) }

    Column(
        modifier = modifier
            .fillMaxWidth()
            .padding(vertical = 12.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        // Main Watch Case & Screen
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.Center,
            modifier = Modifier.fillMaxWidth()
        ) {
            // Watch Face Container
            Box(
                modifier = Modifier
                    .size(210.dp)
                    .clip(CircleShape)
                    .background(watchBgColor)
                    .border(width = 3.5.dp, color = Color(0xFF2B2D31), shape = CircleShape)
                    .padding(3.dp),
                contentAlignment = Alignment.Center
            ) {
                AnimatedContent(
                    targetState = sandboxLayer,
                    transitionSpec = {
                        val isUpOrDown = wearGraphSwipeDir == "UP" || wearGraphSwipeDir == "DOWN"
                        if (isUpOrDown) {
                            if (targetState > initialState) {
                                (slideInVertically { height -> height } + fadeIn()).togetherWith(
                                    slideOutVertically { height -> -height } + fadeOut()
                                )
                            } else {
                                (slideInVertically { height -> -height } + fadeIn()).togetherWith(
                                    slideOutVertically { height -> height } + fadeOut()
                                )
                            }
                        } else {
                            if (targetState > initialState) {
                                (slideInHorizontally { width -> width } + fadeIn()).togetherWith(
                                    slideOutHorizontally { width -> -width } + fadeOut()
                                )
                            } else {
                                (slideInHorizontally { width -> -width } + fadeIn()).togetherWith(
                                    slideOutHorizontally { width -> width } + fadeOut()
                                )
                            }
                        }
                    },
                    label = "sandbox_layer_transition"
                ) { layer ->
                    if (layer == 1) {
                        // MAIN WATCH FACE (LAYER 1)
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .pointerInput(quickAddAmount, wearLongPressDeleteDuration, wearLongPressDeleteEnabled, wearSwipeMode, wearGraphSwipeDir, sandboxOffset, daysPrior, wearPastDaysToShow, maxForward) {
                                    awaitPointerEventScope {
                                        while (true) {
                                            val down = awaitFirstDown(requireUnconsumed = false)
                                            down.consume()
                                            var isLongPress = false
                                            var isDrag = false
                                            var accumulatedX = 0f
                                            var accumulatedY = 0f
                                            val touchSlop = 12f

                                            val longPressJob = coroutineScope.launch {
                                                delay(wearLongPressDeleteDuration.toLong())
                                                if (wearLongPressDeleteEnabled && !isDrag) {
                                                    isLongPress = true
                                                    viewModel.triggerWearHaptic("DELETE")
                                                    sandboxTodayTouched = true
                                                    val currentVal = sandboxIntakes[sandboxOffset] ?: 0
                                                    val newVal = (currentVal - quickAddAmount).coerceAtLeast(0)
                                                    sandboxIntakes[sandboxOffset] = newVal
                                                }
                                            }

                                            while (true) {
                                                val event = awaitPointerEvent()
                                                val anyDown = event.changes.any { it.pressed }
                                                if (!anyDown) break

                                                val change = event.changes.firstOrNull()
                                                if (change != null) {
                                                    change.consume()
                                                    val dragAmount = change.position - change.previousPosition
                                                    accumulatedX += dragAmount.x
                                                    accumulatedY += dragAmount.y

                                                    val absX = kotlin.math.abs(accumulatedX)
                                                    val absY = kotlin.math.abs(accumulatedY)

                                                    if (absX > touchSlop || absY > touchSlop) {
                                                        if (!isDrag) {
                                                            isDrag = true
                                                            longPressJob.cancel()
                                                        }

                                                        val isGraphVertical = wearGraphSwipeDir == "UP" || wearGraphSwipeDir == "DOWN"
                                                        val layerTargetOffset = if (isGraphVertical) accumulatedY else accumulatedX
                                                        val absLayerDrag = kotlin.math.abs(layerTargetOffset)

                                                        val isDaySwipeVertical = wearSwipeMode == "VERTICAL"
                                                        val dayTargetOffset = if (isDaySwipeVertical) accumulatedY else accumulatedX
                                                        val absDayDrag = kotlin.math.abs(dayTargetOffset)

                                                        val isDaySwipeAllowed = wearSwipeMode != "OFF"
                                                        val threshold = 50f
                                                        if (absLayerDrag > threshold || (isDaySwipeAllowed && absDayDrag > threshold)) {
                                                            if (!hasSnappedHaptic) {
                                                                viewModel.triggerWearHaptic("SWIPE")
                                                                hasSnappedHaptic = true
                                                            }
                                                        } else {
                                                            hasSnappedHaptic = false
                                                        }
                                                    }
                                                }
                                            }

                                            longPressJob.cancel()

                                            if (isDrag) {
                                                val threshold = 50f
                                                var handledLayerSwitch = false
                                                when (wearGraphSwipeDir) {
                                                    "LEFT" -> {
                                                        if (accumulatedX < -threshold) {
                                                            sandboxLayer = 2
                                                            handledLayerSwitch = true
                                                            viewModel.triggerWearHaptic("SWIPE")
                                                        }
                                                    }
                                                    "RIGHT" -> {
                                                        if (accumulatedX > threshold) {
                                                            sandboxLayer = 2
                                                            handledLayerSwitch = true
                                                            viewModel.triggerWearHaptic("SWIPE")
                                                        }
                                                    }
                                                    "UP" -> {
                                                        if (accumulatedY < -threshold) {
                                                            sandboxLayer = 2
                                                            handledLayerSwitch = true
                                                            viewModel.triggerWearHaptic("SWIPE")
                                                        }
                                                    }
                                                    "DOWN" -> {
                                                        if (accumulatedY > threshold) {
                                                            sandboxLayer = 2
                                                            handledLayerSwitch = true
                                                            viewModel.triggerWearHaptic("SWIPE")
                                                        }
                                                    }
                                                }

                                                if (!handledLayerSwitch && wearSwipeMode != "OFF") {
                                                    if (wearSwipeMode == "HORIZONTAL") {
                                                        if (accumulatedX > threshold) {
                                                            if (sandboxOffset > -wearPastDaysToShow) {
                                                                sandboxOffset--
                                                                viewModel.triggerWearHaptic("SWIPE")
                                                            }
                                                        } else if (accumulatedX < -threshold) {
                                                            if (sandboxOffset < maxForward) {
                                                                sandboxOffset++
                                                                viewModel.triggerWearHaptic("SWIPE")
                                                            }
                                                        }
                                                    } else if (wearSwipeMode == "VERTICAL") {
                                                        if (accumulatedY > threshold) {
                                                            if (sandboxOffset > -wearPastDaysToShow) {
                                                                sandboxOffset--
                                                                viewModel.triggerWearHaptic("SWIPE")
                                                            }
                                                        } else if (accumulatedY < -threshold) {
                                                            if (sandboxOffset < maxForward) {
                                                                sandboxOffset++
                                                                viewModel.triggerWearHaptic("SWIPE")
                                                            }
                                                        }
                                                    }
                                                }
                                            } else if (!isLongPress) {
                                                viewModel.triggerWearHaptic("CLICK")
                                                sandboxTodayTouched = true
                                                val currentVal = sandboxIntakes[sandboxOffset] ?: 0
                                                val newVal = currentVal + quickAddAmount
                                                sandboxIntakes[sandboxOffset] = newVal
                                            }
                                            hasSnappedHaptic = false
                                        }
                                    }
                                },
                            contentAlignment = Alignment.Center
                        ) {
                            // Ticks background
                            androidx.compose.foundation.Canvas(modifier = Modifier.fillMaxSize()) {
                                val center = size / 2f
                                val radius = size.minDimension / 2f - 12.dp.toPx()
                                for (i in 0 until 12) {
                                    val angleRad = Math.toRadians(i * 30.0)
                                    val startX = center.width + (radius - 4.dp.toPx()) * Math.sin(angleRad).toFloat()
                                    val startY = center.height - (radius - 4.dp.toPx()) * Math.cos(angleRad).toFloat()
                                    val endX = center.width + radius * Math.sin(angleRad).toFloat()
                                    val endY = center.height - radius * Math.cos(angleRad).toFloat()
                                    drawLine(
                                        color = Color.White.copy(alpha = 0.12f),
                                        start = androidx.compose.ui.geometry.Offset(startX, startY),
                                        end = androidx.compose.ui.geometry.Offset(endX, endY),
                                        strokeWidth = 1.dp.toPx()
                                    )
                                }
                            }

                            // Drawing progress circles and text on Canvas
                            if (wearProgressCircleEnabled) {
                                androidx.compose.foundation.Canvas(modifier = Modifier.fillMaxSize()) {
                                    val strokeWidthPx = when (wearProgressCircleThickness) {
                                        "THICK" -> 24.dp.toPx()
                                        "CUSTOM" -> wearCustomThickness.dp.toPx()
                                        else -> 14.4.dp.toPx()
                                    }
                                    val diameter = size.minDimension - strokeWidthPx
                                    val radius = diameter / 2f
                                    val centerOffset = androidx.compose.ui.geometry.Offset(size.width / 2f, size.height / 2f)
                                    val centerCircleRadius = radius - strokeWidthPx / 2f

                                    if (!wearInsideCircleRemoved) {
                                        drawCircle(
                                            color = Color(0xFF111213),
                                            radius = centerCircleRadius,
                                            center = centerOffset
                                        )
                                        drawCircle(
                                            color = primaryColor.copy(alpha = 0.05f * breatheScale),
                                            radius = centerCircleRadius * breatheScale,
                                            center = centerOffset
                                        )
                                    }

                                    drawCircle(
                                        color = Color(0xFF2C2D2F),
                                        radius = radius,
                                        center = centerOffset,
                                        style = androidx.compose.ui.graphics.drawscope.Stroke(width = strokeWidthPx)
                                    )

                                    val basePercentage = animatedProgress.coerceAtMost(1f)
                                    drawArc(
                                        color = primaryColor,
                                        startAngle = -90f,
                                        sweepAngle = basePercentage * 360f,
                                        useCenter = false,
                                        topLeft = androidx.compose.ui.geometry.Offset(centerOffset.x - radius, centerOffset.y - radius),
                                        size = androidx.compose.ui.geometry.Size(diameter, diameter),
                                        style = androidx.compose.ui.graphics.drawscope.Stroke(
                                            width = strokeWidthPx,
                                            cap = androidx.compose.ui.graphics.StrokeCap.Round
                                        )
                                    )

                                    if (animatedProgress > 1f) {
                                        val overflow1 = (animatedProgress - 1f).coerceAtMost(1f)
                                        drawArc(
                                            color = surpassedColor,
                                            startAngle = -90f,
                                            sweepAngle = overflow1 * 360f,
                                            useCenter = false,
                                            topLeft = androidx.compose.ui.geometry.Offset(centerOffset.x - radius, centerOffset.y - radius),
                                            size = androidx.compose.ui.geometry.Size(diameter, diameter),
                                            style = androidx.compose.ui.graphics.drawscope.Stroke(
                                                width = strokeWidthPx,
                                                cap = androidx.compose.ui.graphics.StrokeCap.Round
                                            )
                                        )
                                    }

                                    if (animatedProgress > 2f) {
                                        val overflow2 = (animatedProgress - 2f).coerceAtMost(1f)
                                        drawArc(
                                            color = surpassedColor2,
                                            startAngle = -90f,
                                            sweepAngle = overflow2 * 360f,
                                            useCenter = false,
                                            topLeft = androidx.compose.ui.geometry.Offset(centerOffset.x - radius, centerOffset.y - radius),
                                            size = androidx.compose.ui.geometry.Size(diameter, diameter),
                                            style = androidx.compose.ui.graphics.drawscope.Stroke(
                                                width = strokeWidthPx,
                                                cap = androidx.compose.ui.graphics.StrokeCap.Round
                                            )
                                        )
                                    }

                                    // Curved Text Canvas drawing
                                    val textRadius = radius - strokeWidthPx * 0.95f
                                    if (textRadius > 0) {
                                        val paintBottom = android.graphics.Paint().apply {
                                            isAntiAlias = true
                                            color = primaryColor.toArgb()
                                            textSize = when (wearProgressCircleThickness) {
                                                "THICK" -> (47f * 0.22f).coerceIn(4f, 18f).dp.toPx()
                                                "CUSTOM" -> (wearCustomTextSize * 0.22f).coerceIn(4f, 18f).dp.toPx()
                                                else -> (28.2f * 0.22f).coerceIn(4f, 18f).dp.toPx()
                                            }
                                            typeface = android.graphics.Typeface.create("sans-serif", android.graphics.Typeface.BOLD)
                                            textAlign = android.graphics.Paint.Align.CENTER
                                            letterSpacing = 0.05f
                                        }

                                        val rectBottom = android.graphics.RectF(
                                            centerOffset.x - textRadius,
                                            centerOffset.y - textRadius,
                                            centerOffset.x + textRadius,
                                            centerOffset.y + textRadius
                                        )
                                        val pathBottom = android.graphics.Path().apply {
                                            addArc(rectBottom, 180f, -180f)
                                        }

                                        val bottomText = if (wearShowRemaining) {
                                            val rem = (currentGoal - currentIntake).coerceAtLeast(0)
                                            if (appLanguage == "el") "$rem ml απομένουν" else "$rem ml remaining"
                                        } else {
                                            "ml / $currentGoal"
                                        }
                                        drawContext.canvas.nativeCanvas.drawTextOnPath(
                                            bottomText,
                                            pathBottom,
                                            0f,
                                            0f,
                                            paintBottom
                                        )

                                        val dayHeaderColor = if (sandboxOffset == 0) primaryColor else Color(0xFFFFB74D)
                                        val paintTop = android.graphics.Paint().apply {
                                            isAntiAlias = true
                                            color = dayHeaderColor.toArgb()
                                            alpha = (headerAlpha * 255f).toInt().coerceIn(0, 255)
                                            textSize = when (wearProgressCircleThickness) {
                                                "THICK" -> (47f * 0.22f).coerceIn(4f, 18f).dp.toPx()
                                                "CUSTOM" -> (wearCustomTextSize * 0.22f).coerceIn(4f, 18f).dp.toPx()
                                                else -> (28.2f * 0.22f).coerceIn(4f, 18f).dp.toPx()
                                            }
                                            typeface = android.graphics.Typeface.create("sans-serif", android.graphics.Typeface.BOLD)
                                            textAlign = android.graphics.Paint.Align.CENTER
                                            letterSpacing = 0.1f
                                        }

                                        val rectTop = android.graphics.RectF(
                                            centerOffset.x - textRadius,
                                            centerOffset.y - textRadius,
                                            centerOffset.x + textRadius,
                                            centerOffset.y + textRadius
                                        )
                                        val pathTop = android.graphics.Path().apply {
                                            addArc(rectTop, 180f, 180f)
                                        }

                                        val topText = when (sandboxOffset) {
                                            -3 -> if (appLanguage == "el") "ΠΡΙΝ 3 ΜΕΡΕΣ" else "3 DAYS AGO"
                                            -2 -> if (appLanguage == "el") "ΠΡΙΝ 2 ΜΕΡΕΣ" else "2 DAYS AGO"
                                            -1 -> if (appLanguage == "el") "ΧΘΕΣ" else "YESTERDAY"
                                            0 -> if (appLanguage == "el") "ΣΗΜΕΡΑ" else "TODAY"
                                            1 -> if (appLanguage == "el") "ΑΥΡΙΟ" else "TOMORROW"
                                            2 -> if (appLanguage == "el") "ΣΕ 2 ΜΕΡΕΣ" else "IN 2 DAYS"
                                            else -> {
                                                if (sandboxOffset < 0) {
                                                    if (appLanguage == "el") "ΠΡΙΝ ${-sandboxOffset} ΜΕΡΕΣ" else "${-sandboxOffset} DAYS AGO"
                                                } else {
                                                    if (appLanguage == "el") "ΣΕ $sandboxOffset ΜΕΡΕΣ" else "IN $sandboxOffset DAYS"
                                                }
                                            }
                                        }

                                        if (headerAlpha > 0f) {
                                            drawContext.canvas.nativeCanvas.drawTextOnPath(
                                                topText,
                                                pathTop,
                                                0f,
                                                0f,
                                                paintTop
                                            )
                                        }
                                    }
                                }
                            }

                            // Centered Water Amount text
                            Column(
                                modifier = Modifier
                                    .scale(centerTextScale.value)
                                    .align(Alignment.Center),
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.Center
                            ) {
                                val displayAmount = if (wearShowRemaining) {
                                    (currentGoal - currentIntake).coerceAtLeast(0)
                                } else {
                                    currentIntake
                                }
                                val formattedAmountStr = if (displayAmount >= 1000) {
                                    val liters = displayAmount / 1000
                                    val rem = displayAmount % 1000
                                    String.format(java.util.Locale.US, "%d.%03d", liters, rem)
                                } else {
                                    displayAmount.toString()
                                }

                                Text(
                                    text = formattedAmountStr,
                                    fontSize = when (wearProgressCircleThickness) {
                                        "THICK" -> 47.sp
                                        "CUSTOM" -> wearCustomTextSize.sp
                                        else -> 28.2.sp
                                    },
                                    fontWeight = FontWeight.ExtraBold,
                                    color = displayTextColor,
                                    letterSpacing = (-0.5).sp
                                )
                            }
                        }
                    } else {
                        // STATS GRAPH LAYER (2)
                        val scrollState = rememberScrollState()
                        var statsDragX by remember { mutableStateOf(0f) }
                        val statsDragThreshold = 50f
                        val maxVisualOffsetPx = with(androidx.compose.ui.platform.LocalDensity.current) { 12.dp.toPx() }
                        val statsDragDistance = kotlin.math.abs(statsDragX)
                        val statsDragFraction = (statsDragDistance / statsDragThreshold).coerceIn(0f, 1f)
                        val statsBaseCorner = 24.dp
                        val statsActiveCorner = (24f * (1f - statsDragFraction) + 4f * statsDragFraction).dp

                        val statsMorphedShape = when {
                            statsDragX > 1f -> RoundedCornerShape(
                                topStart = statsBaseCorner,
                                bottomStart = statsBaseCorner,
                                topEnd = statsActiveCorner,
                                bottomEnd = statsActiveCorner
                            )
                            statsDragX < -1f -> RoundedCornerShape(
                                topStart = statsActiveCorner,
                                bottomStart = statsActiveCorner,
                                topEnd = statsBaseCorner,
                                bottomEnd = statsBaseCorner
                            )
                            else -> RoundedCornerShape(statsBaseCorner)
                        }

                        val visualOffsetPx = if (statsDragX > 0) {
                            (statsDragX * 0.2f).coerceAtMost(maxVisualOffsetPx)
                        } else {
                            (statsDragX * 0.2f).coerceAtLeast(-maxVisualOffsetPx)
                        }

                        val wearChartData = remember(sandboxIntakes, sandboxGoals, daysPrior, maxForward, appLanguage) {
                            (-daysPrior..maxForward).map { offset ->
                                val label = when (offset) {
                                    0 -> if (appLanguage == "el") "ΣΗΜ" else "TOD"
                                    -1 -> if (appLanguage == "el") "ΧΘΕ" else "YEST"
                                    1 -> if (appLanguage == "el") "ΑΥΡ" else "TOM"
                                    else -> {
                                        if (offset < 0) {
                                            if (appLanguage == "el") "ΠΡ${-offset}" else "${offset}D"
                                        } else {
                                            if (appLanguage == "el") "ΣΕ$offset" else "+${offset}D"
                                        }
                                    }
                                }
                                val intake = sandboxIntakes[offset] ?: 0
                                val goal = sandboxGoals[offset] ?: 2000
                                Triple(label, intake, goal)
                            }
                        }

                        val maxVal = remember(wearChartData) {
                            val maxAmount = wearChartData.maxOfOrNull { it.second } ?: 1000
                            val maxGoal = wearChartData.maxOfOrNull { it.third } ?: 1000
                            val refMax = maxOf(maxAmount, maxGoal)
                            if (refMax <= 0) 1000 else refMax
                        }

                        val effectiveBarWidth = when (wearProgressCircleThickness) {
                            "THIN" -> (wearGraphPillarThickness * (14.4f / 24f) * 0.625f).coerceIn(6f, 26f).dp
                            "THICK" -> (wearGraphPillarThickness * 0.625f).coerceIn(8f, 28f).dp
                            "CUSTOM" -> (wearGraphPillarThickness * (wearCustomThickness / 24f) * 0.625f).coerceIn(5f, 30f).dp
                            else -> (wearGraphPillarThickness * 0.625f).coerceIn(8f, 28f).dp
                        }
                        val barWidth = effectiveBarWidth
                        val colWidth = barWidth + 4.dp

                        val wearThemePalette = remember(primaryColor) {
                            val hsl = FloatArray(3)
                            androidx.core.graphics.ColorUtils.colorToHSL(primaryColor.toArgb(), hsl)
                            val h = hsl[0]
                            val s = hsl[1]
                            val l = hsl[2]

                            val activePillar = Color(
                                androidx.core.graphics.ColorUtils.HSLToColor(
                                    floatArrayOf(h, (s * 1.1f).coerceIn(0.6f, 1f), (l * 0.95f).coerceIn(0.40f, 0.65f))
                                )
                            )

                            val inProgressPillar = Color(
                                androidx.core.graphics.ColorUtils.HSLToColor(
                                    floatArrayOf(h, (s * 0.85f).coerceIn(0.4f, 0.9f), (l * 1.25f).coerceIn(0.60f, 0.85f))
                                )
                            )

                            val badgeBg = Color(
                                androidx.core.graphics.ColorUtils.HSLToColor(
                                    floatArrayOf((h + 25f) % 360f, (s * 1.1f).coerceIn(0.7f, 1f), 0.82f)
                                )
                            )

                            val checkMark = Color(
                                androidx.core.graphics.ColorUtils.HSLToColor(
                                    floatArrayOf((h - 20f + 360f) % 360f, (s * 1.2f).coerceIn(0.8f, 1f), 0.28f)
                                )
                            )

                            val zeroBar = activePillar.copy(alpha = 0.22f)

                            listOf(activePillar, inProgressPillar, badgeBg, checkMark, zeroBar)
                        }

                        val graphActivePillarColor = wearThemePalette[0]
                        val graphInProgressPillarColor = wearThemePalette[1]
                        val graphBadgeBgColor = wearThemePalette[2]
                        val graphCheckMarkColor = wearThemePalette[3]
                        val graphZeroBarColor = wearThemePalette[4]

                        LaunchedEffect(sandboxOffset, daysPrior) {
                            val activeIndex = sandboxOffset + daysPrior
                            val density = context.resources.displayMetrics.density
                            val colWidthPx = colWidth.value * density
                            val targetScroll = colWidthPx * (activeIndex - 2.1f).coerceAtLeast(0f)
                            scrollState.animateScrollTo(targetScroll.toInt())
                        }

                        Column(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(vertical = 12.dp)
                                .pointerInput(Unit) {
                                    awaitPointerEventScope {
                                        while (true) {
                                            val down = awaitFirstDown(requireUnconsumed = false)
                                            down.consume()
                                            var accumulatedX = 0f
                                            var accumulatedY = 0f
                                            val touchSlop = 12f
                                            var isDrag = false
                                            while (true) {
                                                val event = awaitPointerEvent()
                                                val anyDown = event.changes.any { it.pressed }
                                                if (!anyDown) break
                                                val change = event.changes.firstOrNull()
                                                if (change != null) {
                                                    change.consume()
                                                    val dragAmount = change.position - change.previousPosition
                                                    accumulatedX += dragAmount.x
                                                    accumulatedY += dragAmount.y
                                                    if (kotlin.math.abs(accumulatedX) > touchSlop || kotlin.math.abs(accumulatedY) > touchSlop) {
                                                        isDrag = true
                                                    }
                                                }
                                            }
                                            if (isDrag) {
                                                sandboxLayer = 1
                                                viewModel.triggerWearHaptic("SWIPE")
                                            }
                                        }
                                    }
                                },
                            horizontalAlignment = Alignment.CenterHorizontally,
                            verticalArrangement = Arrangement.spacedBy(4.dp)
                        ) {
                            // Header pill to return to main layer
                            Box(
                                modifier = Modifier
                                    .offset {
                                        androidx.compose.ui.unit.IntOffset(
                                            x = visualOffsetPx.toInt(),
                                            y = 0
                                        )
                                    }
                                    .background(
                                        color = primaryColor.copy(alpha = 0.15f),
                                        shape = statsMorphedShape
                                    )
                                    .clickable {
                                        sandboxLayer = 1
                                        viewModel.triggerWearHaptic("CLICK")
                                    }
                                    .padding(horizontal = 14.dp, vertical = 6.dp),
                                contentAlignment = Alignment.Center
                            ) {
                                Text(
                                    text = if (appLanguage == "el") "ΣΤΑΤΙΣΤΙΚΑ" else "STATS",
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = primaryColor
                                )
                            }

                            Box(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(124.dp)
                            ) {
                                Box(
                                    modifier = Modifier
                                        .fillMaxSize()
                                        .horizontalScroll(scrollState)
                                ) {
                                    val previewHorizontalPadding = (wearGraphHorizontalPadding * 0.625f).dp
                                    val totalScrollWidth = (colWidth * wearChartData.size) + (previewHorizontalPadding * 2)

                                    Box(
                                        modifier = Modifier
                                            .width(totalScrollWidth)
                                            .fillMaxHeight()
                                    ) {
                                        androidx.compose.foundation.Canvas(
                                            modifier = Modifier
                                                .fillMaxSize()
                                                .padding(bottom = 20.dp)
                                        ) {
                                            val numSegments = wearChartData.size
                                            if (numSegments > 0) {
                                                val padPx = previewHorizontalPadding.toPx()
                                                val segmentWidth = (size.width - padPx * 2f).coerceAtLeast(1f) / numSegments
                                                val path = androidx.compose.ui.graphics.Path()
                                                val points = mutableListOf<androidx.compose.ui.geometry.Offset>()

                                                for (idx in 0 until numSegments) {
                                                    val itemGoal = wearChartData[idx].third
                                                    val goalRatio = (itemGoal.toFloat() / maxVal.toFloat()).coerceIn(0f, 1f) * 0.72f + 0.12f
                                                    val y = size.height * (1f - goalRatio)
                                                    val x = padPx + idx * segmentWidth + segmentWidth / 2f
                                                    points.add(androidx.compose.ui.geometry.Offset(x, y))
                                                }

                                                if (points.size > 1) {
                                                    val strokeWidth = if (goalLineSquiggly) (barWidth.value * 0.20f).coerceIn(2.8f, 5.0f).dp.toPx() else (barWidth.value * 0.13f).coerceIn(1.8f, 3.8f).dp.toPx()
                                                    if (goalLineSquiggly) {
                                                        val amplitude = (barWidth.value * 0.32f).coerceIn(3.5f, 7.5f).dp.toPx()
                                                        val period = (barWidth.value * 1.10f).coerceIn(14f, 28f).dp.toPx()
                                                        val twoPiOverPeriod = (2 * Math.PI / period).toFloat()
                                                        
                                                        val firstP = points.first()
                                                        val startSquigglyY = firstP.y + amplitude * kotlin.math.sin(0.0).toFloat()
                                                        path.moveTo(0f, startSquigglyY)

                                                        val step = 1.5f
                                                        var currentX = 0f
                                                        while (currentX <= size.width) {
                                                            val baseY = when {
                                                                currentX <= points.first().x -> points.first().y
                                                                currentX >= points.last().x -> points.last().y
                                                                else -> {
                                                                    var interpolatedY = points.first().y
                                                                    for (i in 0 until points.size - 1) {
                                                                        val p1 = points[i]
                                                                        val p2 = points[i + 1]
                                                                        if (currentX >= p1.x && currentX <= p2.x) {
                                                                            val deltaX = p2.x - p1.x
                                                                            val t = if (deltaX != 0f) (currentX - p1.x) / deltaX else 0f
                                                                            interpolatedY = p1.y + t * (p2.y - p1.y)
                                                                            break
                                                                        }
                                                                    }
                                                                    interpolatedY
                                                                }
                                                            }
                                                            val squigglyY = baseY + amplitude * kotlin.math.sin(twoPiOverPeriod * currentX)
                                                            path.lineTo(currentX, squigglyY)
                                                            currentX += step
                                                        }
                                                        val lastBaseY = points.last().y
                                                        val endSquigglyY = lastBaseY + amplitude * kotlin.math.sin(twoPiOverPeriod * size.width)
                                                        path.lineTo(size.width, endSquigglyY)
                                                    } else {
                                                        path.moveTo(0f, points[0].y)
                                                        path.lineTo(points[0].x, points[0].y)
                                                        for (i in 0 until points.size - 1) {
                                                            val p1 = points[i]
                                                            val p2 = points[i + 1]
                                                            val dx = (p2.x - p1.x) / 2f
                                                            path.cubicTo(
                                                                p1.x + dx, p1.y,
                                                                p2.x - dx, p2.y,
                                                                p2.x, p2.y
                                                            )
                                                        }
                                                        path.lineTo(size.width, points.last().y)
                                                    }
                                                    drawPath(
                                                        path = path,
                                                        color = primaryColor.copy(alpha = 0.5f),
                                                        style = androidx.compose.ui.graphics.drawscope.Stroke(
                                                            width = strokeWidth,
                                                            cap = androidx.compose.ui.graphics.StrokeCap.Round,
                                                            join = androidx.compose.ui.graphics.StrokeJoin.Round
                                                        )
                                                    )
                                                }
                                            }
                                        }

                                        Row(
                                            modifier = Modifier
                                                .fillMaxSize()
                                                .padding(horizontal = previewHorizontalPadding),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.Bottom
                                        ) {
                                            wearChartData.forEachIndexed { idx, (label, valMl, valGoal) ->
                                                val activeBar = valMl >= valGoal
                                                val isActiveDay = idx == (sandboxOffset + daysPrior)

                                                Column(
                                                    modifier = Modifier
                                                        .width(colWidth)
                                                        .fillMaxHeight()
                                                        .clickable {
                                                            sandboxOffset = idx - daysPrior
                                                            sandboxLayer = 1
                                                            viewModel.triggerWearHaptic("CLICK")
                                                        },
                                                    horizontalAlignment = Alignment.CenterHorizontally,
                                                    verticalArrangement = Arrangement.Bottom
                                                ) {
                                                    Box(
                                                        modifier = Modifier
                                                            .weight(1f)
                                                            .fillMaxWidth()
                                                            .padding(bottom = 4.dp),
                                                        contentAlignment = Alignment.BottomCenter
                                                    ) {
                                                        val barHeightRatio = (valMl.toFloat() / maxVal.toFloat()).coerceIn(0f, 1f) * 0.72f + 0.12f

                                                        if (valMl > 0) {
                                                            Box(
                                                                modifier = Modifier
                                                                    .fillMaxHeight(barHeightRatio)
                                                                    .width(barWidth),
                                                                contentAlignment = Alignment.TopCenter
                                                            ) {
                                                                Box(
                                                                    modifier = Modifier
                                                                        .fillMaxHeight()
                                                                        .width(barWidth)
                                                                        .clip(RoundedCornerShape(percent = 50))
                                                                        .background(
                                                                            color = if (activeBar) graphActivePillarColor else graphInProgressPillarColor
                                                                        )
                                                                )

                                                                if (activeBar) {
                                                                    val rosetteSize = (barWidth.value * 0.82f).coerceIn(9f, 22f).dp
                                                                    val rosetteOffsetY = (barWidth.value * 0.08f).coerceIn(1.2f, 3f).dp
                                                                    VerifiedRosetteBadge(
                                                                        modifier = Modifier
                                                                            .size(rosetteSize)
                                                                            .offset(y = rosetteOffsetY),
                                                                        tint = graphBadgeBgColor,
                                                                        checkMarkColor = graphCheckMarkColor
                                                                    )
                                                                }
                                                            }
                                                        } else {
                                                            val zeroBarHeight = (barWidth.value * 0.12f).coerceIn(1.5f, 3.5f).dp
                                                            Box(
                                                                modifier = Modifier
                                                                    .height(zeroBarHeight)
                                                                    .width(barWidth)
                                                                    .clip(RoundedCornerShape(percent = 50))
                                                                    .background(
                                                                        color = graphZeroBarColor
                                                                    )
                                                            )
                                                        }
                                                    }

                                                    Text(
                                                        text = label,
                                                        fontSize = 10.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        color = if (isActiveDay) primaryColor else Color(0xFF9EAAB6),
                                                        textAlign = androidx.compose.ui.text.style.TextAlign.Center,
                                                        maxLines = 1,
                                                        softWrap = false,
                                                        modifier = Modifier
                                                            .padding(vertical = 4.dp, horizontal = 1.dp)
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // Digital Crown Knob on the Right Side of Watch
            Box(
                modifier = Modifier
                    .width(10.dp)
                    .height(36.dp)
                    .offset(x = (-2).dp)
                    .background(
                        color = Color(0xFF242528),
                        shape = RoundedCornerShape(topEnd = 5.dp, bottomEnd = 5.dp, topStart = 0.dp, bottomStart = 0.dp)
                    )
                    .border(
                        width = 1.dp,
                        color = Color.White.copy(alpha = 0.15f),
                        shape = RoundedCornerShape(topEnd = 5.dp, bottomEnd = 5.dp, topStart = 0.dp, bottomStart = 0.dp)
                    )
                    .pointerInput(sandboxOffset, sandboxLayer, wearCrownRotationEnabled, wearCrownRotationReverse, wearCrownClicksPerMl) {
                        awaitPointerEventScope {
                            while (true) {
                                val down = awaitFirstDown(requireUnconsumed = false)
                                down.consume()
                                var isDrag = false
                                var accumulatedY = 0f
                                val touchSlop = 4f

                                while (true) {
                                    val event = awaitPointerEvent()
                                    val anyDown = event.changes.any { it.pressed }
                                    if (!anyDown) break

                                    val change = event.changes.firstOrNull()
                                    if (change != null) {
                                        change.consume()
                                        val dragAmount = change.position - change.previousPosition
                                        accumulatedY += dragAmount.y

                                        if (kotlin.math.abs(accumulatedY) > touchSlop) {
                                            isDrag = true
                                        }

                                        if (isDrag) {
                                            crownDragAccumulator += dragAmount.y
                                            val threshold = 10.dp.toPx()
                                            if (crownDragAccumulator > threshold) {
                                                if (wearCrownRotationEnabled) {
                                                    val mlStep = if (wearCrownClicksPerMl > 0) wearCrownClicksPerMl else 10
                                                    val currentVal = sandboxIntakes[sandboxOffset] ?: 0
                                                    val delta = if (wearCrownRotationReverse) -mlStep else mlStep
                                                    val newVal = (currentVal + delta).coerceAtLeast(0)
                                                    sandboxIntakes[sandboxOffset] = newVal
                                                    sandboxTodayTouched = true
                                                    viewModel.triggerWearHaptic("ROTARY")
                                                } else {
                                                    viewModel.triggerWearHaptic("ROTARY")
                                                }
                                                crownDragAccumulator = 0f
                                            } else if (crownDragAccumulator < -threshold) {
                                                if (wearCrownRotationEnabled) {
                                                    val mlStep = if (wearCrownClicksPerMl > 0) wearCrownClicksPerMl else 10
                                                    val currentVal = sandboxIntakes[sandboxOffset] ?: 0
                                                    val delta = if (wearCrownRotationReverse) mlStep else -mlStep
                                                    val newVal = (currentVal + delta).coerceAtLeast(0)
                                                    sandboxIntakes[sandboxOffset] = newVal
                                                    sandboxTodayTouched = true
                                                    viewModel.triggerWearHaptic("ROTARY")
                                                } else {
                                                    viewModel.triggerWearHaptic("ROTARY")
                                                }
                                                crownDragAccumulator = 0f
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
            )
        }


    }
}
fun androidx.compose.foundation.lazy.LazyListScope.renderWearOsSettingsSection_deprecated(

    viewModel: WaterViewModel,
    appLanguage: String
) {
    item {
        SettingsCategoryHeader(
            title = if (appLanguage == "el") "ΣΥΝΔΕΣΗ WEAR OS" else "WEAR OS COMPANION SETTINGS",
            icon = Icons.Rounded.Watch
        )
    }

    item {
        val context = androidx.compose.ui.platform.LocalContext.current
        
        val wearShowRemaining by viewModel.wearShowRemaining.collectAsStateWithLifecycle()
        val wearHapticStrength by viewModel.wearHapticStrength.collectAsStateWithLifecycle()
        val wearThemeColor by viewModel.wearThemeColor.collectAsStateWithLifecycle()
        val wearSwipeMode by viewModel.wearSwipeMode.collectAsStateWithLifecycle()
        val wearGraphSwipeDir by viewModel.wearGraphSwipeDir.collectAsStateWithLifecycle()
        val wearComplicationIconStyle by viewModel.wearComplicationIconStyle.collectAsStateWithLifecycle()

        val isWatchConnected by viewModel.isWatchConnected.collectAsStateWithLifecycle()
        val connectedWatchModel by viewModel.connectedWatchModel.collectAsStateWithLifecycle()
        val watchBatteryLevel by viewModel.watchBatteryLevel.collectAsStateWithLifecycle()
        val watchCompanionDetected by viewModel.watchCompanionDetected.collectAsStateWithLifecycle()
        
        val isDark = MaterialTheme.colorScheme.background.luminance() < 0.5f
        val isFrostedGlassEnabled = LocalFrostedGlassEnabled.current
        val frostedTransparency = LocalFrostedGlassTransparency.current
        
        val cardBgColor = if (isFrostedGlassEnabled) {
            GlassTheme.getSubCardColor(isDark, frostedTransparency)
        } else {
            MaterialTheme.colorScheme.surfaceVariant
        }
        
        val strokeColor = if (isFrostedGlassEnabled) {
            Color.White.copy(alpha = if (isDark) 0.18f else 0.40f)
        } else {
            MaterialTheme.colorScheme.outlineVariant
        }

        val statusCardBrush = if (isFrostedGlassEnabled) {
            androidx.compose.ui.graphics.Brush.linearGradient(colors = listOf(cardBgColor, cardBgColor))
        } else if (isWatchConnected) {
            androidx.compose.ui.graphics.Brush.linearGradient(
                colors = listOf(
                    MaterialTheme.colorScheme.primaryContainer,
                    MaterialTheme.colorScheme.surfaceVariant
                )
            )
        } else {
            androidx.compose.ui.graphics.Brush.linearGradient(
                colors = listOf(
                    MaterialTheme.colorScheme.surfaceVariant,
                    MaterialTheme.colorScheme.surfaceVariant
                )
            )
        }

        val statusBorderColor = if (isWatchConnected && !isFrostedGlassEnabled) {
            MaterialTheme.colorScheme.primary
        } else {
            strokeColor
        }

        val customCardBrush = if (isFrostedGlassEnabled) {
            androidx.compose.ui.graphics.Brush.linearGradient(colors = listOf(cardBgColor, cardBgColor))
        } else {
            androidx.compose.ui.graphics.Brush.linearGradient(
                colors = listOf(
                    MaterialTheme.colorScheme.surfaceVariant,
                    MaterialTheme.colorScheme.surfaceVariant
                )
            )
        }

        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 10.dp),
            verticalArrangement = Arrangement.spacedBy(18.dp)
        ) {
            // 1. Live Watch Connection Status Card
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(24.dp))
                    .background(statusCardBrush)
                    .border(1.dp, statusBorderColor, RoundedCornerShape(24.dp))
                    .padding(18.dp)
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(14.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        // Pulsating Signal Dot
                        val infiniteTransition = androidx.compose.animation.core.rememberInfiniteTransition(label = "pulse")
                        val scale by infiniteTransition.animateFloat(
                            initialValue = 0.8f,
                            targetValue = 1.3f,
                            animationSpec = androidx.compose.animation.core.infiniteRepeatable(
                                animation = androidx.compose.animation.core.tween(1000, easing = androidx.compose.animation.core.FastOutSlowInEasing),
                                repeatMode = androidx.compose.animation.core.RepeatMode.Reverse
                            ),
                            label = "scale"
                        )
                        
                        val dotColor = if (isWatchConnected) Color(0xFF4CAF50) else Color(0xFFE57373)
                        
                        Box(contentAlignment = Alignment.Center) {
                            Box(
                                modifier = Modifier
                                    .size(14.dp)
                                    .graphicsLayer {
                                        scaleX = if (isWatchConnected) scale else 1.0f
                                        scaleY = if (isWatchConnected) scale else 1.0f
                                    }
                                    .background(dotColor.copy(alpha = 0.4f), shape = CircleShape)
                            )
                            Box(
                                modifier = Modifier
                                    .size(8.dp)
                                    .background(dotColor, shape = CircleShape)
                            )
                        }
                        
                        Column {
                            val watchName = remember(isWatchConnected, connectedWatchModel) {
                                if (isWatchConnected) {
                                    val name = connectedWatchModel.trim()
                                    if (name.isEmpty()) {
                                        if (appLanguage == "el") "Έξυπνο Ρολόι" else "Smartwatch"
                                    } else {
                                        val isPixelWatch = name.lowercase().contains("pixel watch")
                                        if (isPixelWatch) "Google Pixel Watch" else name
                                    }
                                } else {
                                    ""
                                }
                            }
                            
                            val titleText = if (isWatchConnected) {
                                if (appLanguage == "el") "$watchName Συνδεδεμένο" else "$watchName Connected"
                            } else {
                                if (appLanguage == "el") "Δεν βρέθηκε Ρολόι" else "No Watch Connected"
                            }
                            
                            val subtitleText = if (isWatchConnected) {
                                if (watchCompanionDetected) {
                                    if (appLanguage == "el") "Εφαρμογή συνοδός ενεργή" else "Companion app active"
                                } else {
                                    if (appLanguage == "el") "Δεν εκτελείται η εφαρμογή" else "Companion app not running"
                                }
                            } else {
                                if (appLanguage == "el") "Ενεργοποιήστε το Bluetooth" else "Enable Bluetooth or start watch app"
                            }

                            Text(
                                text = titleText,
                                fontSize = 16.sp,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Text(
                                text = subtitleText,
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Medium,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                    }
                    
                    if (isWatchConnected) {
                        val batteryText = if (watchBatteryLevel != null) "$watchBatteryLevel%" else "--%"
                        val batteryColor = if (watchBatteryLevel != null && watchBatteryLevel!! <= 20) Color(0xFFE57373) else Color(0xFF4CAF50)
                        Text(
                            text = batteryText,
                            fontSize = 14.sp,
                            fontWeight = FontWeight.ExtraBold,
                            color = batteryColor
                        )
                    }
                }
            }

            // 2. Main Customization Card
            ChunkySettingCard(
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(
                    modifier = Modifier.fillMaxWidth().padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(20.dp)
                ) {
                    // Title
                    Text(
                        text = if (appLanguage == "el") "Προσαρμογή Εμπειρίας" else "Watch Interface",
                        fontSize = 15.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.primary,
                        letterSpacing = 1.sp
                    )
                    
                    // Toggle remaining water
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text = if (appLanguage == "el") "Εμφάνιση Υπολειπόμενου Νερού" else "Show Remaining Water",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = if (appLanguage == "el") "Εμφανίζει το υπόλοιπο ml αντί για το σύνολο στο ρολόι." else "Display remaining goal intake instead of logged total.",
                                fontSize = 12.sp,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                        
                        Switch(
                            checked = wearShowRemaining,
                            onCheckedChange = { viewModel.updateWearShowRemaining(it) }
                        )
                    }



                }
            }
            
            ChunkySettingCard(
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(
                    modifier = Modifier.fillMaxWidth().padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(20.dp)
                ) {
                    // Watch Theme color selector
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Text(
                            text = if (appLanguage == "el") "Θέμα Χρώματος Ρολογιού" else "Watch Face Theme Color",
                            fontSize = 16.sp,
                            fontWeight = FontWeight.SemiBold,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(12.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            // Dynamic item
                            val isDynamicSelected = wearThemeColor == "DYNAMIC" || wearThemeColor == "FOLLOW_APP"
                            Column(
                                horizontalAlignment = Alignment.CenterHorizontally,
                                verticalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                com.pixelwater.app.ui.GearRotatableShapeButton(
                                    isSelected = isDynamicSelected,
                                    onClick = { viewModel.updateWearThemeColor("DYNAMIC") },
                                    modifier = Modifier.size(56.dp),
                                    shape = com.pixelwater.app.ui.WavyShape(),
                                    backgroundBrush = androidx.compose.ui.graphics.Brush.linearGradient(
                                        colors = listOf(
                                            if (isDynamicSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.primary.copy(alpha = 0.5f),
                                            if (isDynamicSelected) MaterialTheme.colorScheme.tertiary else MaterialTheme.colorScheme.tertiary.copy(alpha = 0.5f)
                                        )
                                    )
                                ) {
                                    Icon(
                                        imageVector = androidx.compose.material.icons.Icons.Rounded.AutoAwesome,
                                        contentDescription = "Dynamic",
                                        tint = if (isDynamicSelected) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.primary,
                                        modifier = Modifier.size(if (isDynamicSelected) 28.dp else 24.dp)
                                    )
                                }
                                Text(
                                    text = if (appLanguage == "el") "Δυναμικό" else "Dynamic",
                                    fontSize = 11.sp,
                                    fontWeight = if (isDynamicSelected) FontWeight.Bold else FontWeight.Medium,
                                    color = if (isDynamicSelected) MaterialTheme.colorScheme.onSurface else MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }

                            // Extracted wallpaper colors
                            val wallpaperColors by viewModel.wallpaperThemeColors.collectAsStateWithLifecycle()
                            Row(
                                modifier = Modifier
                                    .weight(1f)
                                    .horizontalScroll(rememberScrollState()),
                                horizontalArrangement = Arrangement.spacedBy(4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                wallpaperColors.forEachIndexed { idx, colorInt ->
                                    val name = "PALETTE_$idx"
                                    val isSelected = wearThemeColor == name
                                    val (topColor, bottomLeftColor, bottomRightColor) = remember(colorInt) { viewModel.getSwatchColors(colorInt) }

                                    Box(
                                        modifier = Modifier
                                            .size(56.dp)
                                            .padding(2.dp)
                                            .then(
                                                if (isSelected) {
                                                    Modifier.border(
                                                        width = 3.dp,
                                                        color = MaterialTheme.colorScheme.primary,
                                                        shape = CircleShape
                                                    )
                                                } else Modifier
                                            )
                                            .padding(if (isSelected) 4.dp else 0.dp)
                                            .clip(CircleShape)
                                            .clickable {
                                                viewModel.updateWearThemeColor(name)
                                            }
                                    ) {
                                        Canvas(modifier = Modifier.fillMaxSize()) {
                                            drawArc(color = topColor, startAngle = 180f, sweepAngle = 180f, useCenter = true)
                                            drawArc(color = bottomLeftColor, startAngle = 90f, sweepAngle = 90f, useCenter = true)
                                            drawArc(color = bottomRightColor, startAngle = 0f, sweepAngle = 90f, useCenter = true)
                                        }
                                    }
                                }
                            }
                        }

                        // If dynamic or palette color is selected, show Dynamic Palette Role Options
                        val isDynamicOrPalette = wearThemeColor == "DYNAMIC" || wearThemeColor == "FOLLOW_APP" || wearThemeColor.startsWith("PALETTE_")
                        if (isDynamicOrPalette) {
                            val activeRole by viewModel.wearDynamicPaletteRole.collectAsStateWithLifecycle()
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = if (appLanguage == "el") "Ρόλος Χρωματικής Παλέτας (Wear OS)" else "Palette Color Role (Wear OS)",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .background(
                                        if (isFrostedGlassEnabled) Color.White.copy(alpha = 0.08f) 
                                        else MaterialTheme.colorScheme.surfaceVariant, 
                                        RoundedCornerShape(12.dp)
                                    )
                                    .border(1.dp, strokeColor, RoundedCornerShape(12.dp))
                                    .padding(4.dp),
                                horizontalArrangement = Arrangement.spacedBy(4.dp)
                            ) {
                                val roles = listOf(
                                    "PRIMARY" to (if (appLanguage == "el") "Πρωτεύον" else "Primary"),
                                    "SECONDARY" to (if (appLanguage == "el") "Δευτερεύον" else "Secondary"),
                                    "TERTIARY" to (if (appLanguage == "el") "Τριτεύον" else "Tertiary")
                                )
                                roles.forEach { (roleKey, roleLabel) ->
                                    val isRoleSelected = activeRole == roleKey
                                    Box(
                                        modifier = Modifier
                                            .weight(1f)
                                            .clip(RoundedCornerShape(10.dp))
                                            .background(if (isRoleSelected) MaterialTheme.colorScheme.primary else Color.Transparent)
                                            .clickable { viewModel.updateWearDynamicPaletteRole(roleKey) }
                                            .padding(vertical = 8.dp),
                                        contentAlignment = Alignment.Center
                                    ) {
                                        Text(
                                            text = roleLabel,
                                            fontSize = 11.sp,
                                            fontWeight = if (isRoleSelected) FontWeight.Bold else FontWeight.Medium,
                                            color = if (isRoleSelected) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant
                                        )
                                    }
                                }
                            }
                        }

                        Spacer(modifier = Modifier.height(4.dp))

                        // Scrollable Row of standard colors
                        Text(
                            text = if (appLanguage == "el") "Σταθερά Χρώματα" else "Standard Colors",
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Medium,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )

                        val isCustomRgbSelected = wearThemeColor.startsWith("CUSTOM_RGB_")

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .horizontalScroll(rememberScrollState()),
                            horizontalArrangement = Arrangement.spacedBy(12.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            // Custom RGB Color trigger dot
                            Box(
                                modifier = Modifier
                                    .size(44.dp)
                                    .clip(CircleShape)
                                    .background(if (isCustomRgbSelected) MaterialTheme.colorScheme.primary.copy(alpha = 0.3f) else Color.Transparent)
                                    .border(
                                        width = if (isCustomRgbSelected) 2.5.dp else 1.dp,
                                        color = if (isCustomRgbSelected) MaterialTheme.colorScheme.primary else strokeColor,
                                        shape = CircleShape
                                    )
                                    .clickable { 
                                        val currentHex = if (wearThemeColor.startsWith("CUSTOM_RGB_")) wearThemeColor.removePrefix("CUSTOM_RGB_") else "00BFA5"
                                        viewModel.updateWearThemeColor("CUSTOM_RGB_$currentHex")
                                    },
                                contentAlignment = Alignment.Center
                            ) {
                                Box(
                                    modifier = Modifier
                                        .size(28.dp)
                                        .clip(CircleShape)
                                        .background(
                                            androidx.compose.ui.graphics.Brush.sweepGradient(
                                                colors = listOf(Color.Red, Color.Yellow, Color.Green, Color.Cyan, Color.Blue, Color.Magenta, Color.Red)
                                            )
                                        )
                                )
                            }

                            val standardColors = listOf(
                                "MINT" to Color(0xFF00BFA5),
                                "SKY" to Color(0xFF29B6F6),
                                "LAVENDER" to Color(0xFFAB47BC),
                                "CORAL" to Color(0xFFFF7043),
                                "OCEAN" to Color(0xFF1D5AAB),
                                "PURPLE" to Color(0xFF8E24AA),
                                "FOREST" to Color(0xFF2E7D32),
                                "SLATE" to Color(0xFF455A64),
                                "ORANGE" to Color(0xFFFF9100),
                                "CRIMSON" to Color(0xFFD81B60),
                                "INDIGO" to Color(0xFF3F51B5),
                                "BLACK" to Color(0xFF000000),
                                "WHITE" to Color(0xFFFFFFFF)
                            )
                            
                            standardColors.forEach { (name, color) ->
                                val isSelected = wearThemeColor == name
                                val borderStrokeColor = if (isSelected) {
                                    color
                                } else if (name == "BLACK") {
                                    strokeColor
                                } else {
                                    strokeColor
                                }
                                Box(
                                    modifier = Modifier
                                        .size(44.dp)
                                        .clip(CircleShape)
                                        .background(if (isSelected) color.copy(alpha = 0.3f) else Color.Transparent)
                                        .border(
                                            width = if (isSelected) 2.5.dp else 1.dp,
                                            color = borderStrokeColor,
                                            shape = CircleShape
                                        )
                                        .clickable { viewModel.updateWearThemeColor(name) },
                                    contentAlignment = Alignment.Center
                                ) {
                                    Box(
                                        modifier = Modifier
                                            .size(28.dp)
                                            .border(
                                                width = if (name == "BLACK") 0.5.dp else 0.dp,
                                                color = if (name == "BLACK") Color.Gray.copy(alpha = 0.5f) else Color.Transparent,
                                                shape = CircleShape
                                            )
                                            .background(color, shape = CircleShape)
                                    )
                                }
                            }
                        }

                        // Custom RGB Slider Controls
                        if (isCustomRgbSelected) {
                            val currentHex = wearThemeColor.removePrefix("CUSTOM_RGB_")
                            val rVal = remember(currentHex) {
                                try { currentHex.substring(0, 2).toInt(16) } catch (e: Exception) { 0 }
                            }
                            val gVal = remember(currentHex) {
                                try { currentHex.substring(2, 4).toInt(16) } catch (e: Exception) { 191 }
                            }
                            val bVal = remember(currentHex) {
                                try { currentHex.substring(4, 6).toInt(16) } catch (e: Exception) { 165 }
                            }

                            var isSlidersExpanded by remember { mutableStateOf(false) }

                            Spacer(modifier = Modifier.height(6.dp))
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clip(RoundedCornerShape(16.dp))
                                    .background(
                                        if (isFrostedGlassEnabled) Color.White.copy(alpha = 0.05f) 
                                        else MaterialTheme.colorScheme.surfaceVariant
                                    )
                                    .border(1.dp, strokeColor, RoundedCornerShape(16.dp))
                                    .padding(14.dp),
                                verticalArrangement = Arrangement.spacedBy(10.dp)
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .clickable { isSlidersExpanded = !isSlidersExpanded }
                                        .padding(vertical = 2.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(
                                        verticalAlignment = Alignment.CenterVertically,
                                        horizontalArrangement = Arrangement.spacedBy(4.dp)
                                    ) {
                                        Icon(
                                            imageVector = if (isSlidersExpanded) Icons.Rounded.KeyboardArrowUp else Icons.Rounded.KeyboardArrowDown,
                                            contentDescription = "Toggle RGB Sliders",
                                            tint = MaterialTheme.colorScheme.primary,
                                            modifier = Modifier.size(20.dp)
                                        )
                                        Text(
                                            text = if (appLanguage == "el") "Προσαρμοσμένο Χρώμα RGB" else "Custom RGB Color",
                                            fontSize = 13.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = MaterialTheme.colorScheme.primary
                                        )
                                    }
                                    val previewColor = remember(currentHex) {
                                        try { Color(android.graphics.Color.parseColor("#$currentHex")) } catch (e: Exception) { Color(0xFF00BFA5) }
                                    }
                                    Row(
                                        horizontalArrangement = Arrangement.spacedBy(4.dp),
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Box(
                                            modifier = Modifier
                                                .size(16.dp)
                                                .clip(CircleShape)
                                                .background(previewColor)
                                                .border(1.dp, strokeColor, CircleShape)
                                        )
                                        Text(
                                            text = "#$currentHex",
                                            fontSize = 13.sp,
                                            fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace,
                                            fontWeight = FontWeight.ExtraBold,
                                            color = MaterialTheme.colorScheme.onSurface
                                        )
                                    }
                                }

                                if (isSlidersExpanded) {
                                     // Red Slider
                                    Column {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween
                                        ) {
                                            Text(text = if (appLanguage == "el") "Κόκκινο" else "Red", fontSize = 11.sp, fontWeight = FontWeight.Medium, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                            Text(text = rVal.toString(), fontSize = 11.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                        }
                                        CapsulePatternSlider(
                                            value = rVal.toFloat(),
                                            onValueChange = { 
                                                val hex = String.format("%02X%02X%02X", it.toInt(), gVal, bVal)
                                                viewModel.updateWearThemeColor("CUSTOM_RGB_$hex")
                                            },
                                            valueRange = 0f..255f,
                                            stepsCount = 256,
                                            triggerHaptic = { viewModel.triggerSliderHaptic() },
                                            activeColor = Color.Red,
                                            modifier = Modifier.fillMaxWidth()
                                        )
                                    }

                                    // Green Slider
                                    Column {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween
                                        ) {
                                            Text(text = if (appLanguage == "el") "Πράσινο" else "Green", fontSize = 11.sp, fontWeight = FontWeight.Medium, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                            Text(text = gVal.toString(), fontSize = 11.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                        }
                                        CapsulePatternSlider(
                                            value = gVal.toFloat(),
                                            onValueChange = { 
                                                val hex = String.format("%02X%02X%02X", rVal, it.toInt(), bVal)
                                                viewModel.updateWearThemeColor("CUSTOM_RGB_$hex")
                                            },
                                            valueRange = 0f..255f,
                                            stepsCount = 256,
                                            triggerHaptic = { viewModel.triggerSliderHaptic() },
                                            activeColor = Color.Green,
                                            modifier = Modifier.fillMaxWidth()
                                        )
                                    }

                                    // Blue Slider
                                    Column {
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.SpaceBetween
                                        ) {
                                            Text(text = if (appLanguage == "el") "Μπλε" else "Blue", fontSize = 11.sp, fontWeight = FontWeight.Medium, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                            Text(text = bVal.toString(), fontSize = 11.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.onSurfaceVariant)
                                        }
                                        CapsulePatternSlider(
                                            value = bVal.toFloat(),
                                            onValueChange = { 
                                                val hex = String.format("%02X%02X%02X", rVal, gVal, it.toInt())
                                                viewModel.updateWearThemeColor("CUSTOM_RGB_$hex")
                                            },
                                            valueRange = 0f..255f,
                                            stepsCount = 256,
                                            triggerHaptic = { viewModel.triggerSliderHaptic() },
                                            activeColor = Color.Blue,
                                            modifier = Modifier.fillMaxWidth()
                                        )
                                    }
                                }
                            }
                        }
                    }

                }
            }
            
            ChunkySettingCard(
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(
                    modifier = Modifier.fillMaxWidth().padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(20.dp)
                ) {
                    // Tap and Hold (Long Press) settings
                    val wearLongPressDeleteEnabled by viewModel.wearLongPressDeleteEnabled.collectAsStateWithLifecycle()
                    val wearLongPressDeleteDuration by viewModel.wearLongPressDeleteDuration.collectAsStateWithLifecycle()

                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    text = if (appLanguage == "el") "Διαγραφή με Tap & Hold" else "Delete with Tap & Hold",
                                    fontSize = 16.sp,
                                    fontWeight = FontWeight.SemiBold,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                                Spacer(modifier = Modifier.height(2.dp))
                                Text(
                                    text = if (appLanguage == "el") "Πατήστε παρατεταμένα τον κύκλο προόδου στο ρολόι για να διαγράψετε την τελευταία καταγραφή." else "Long press the progress circle on the watch to delete the last logged entry.",
                                    fontSize = 12.sp,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                            Switch(
                                checked = wearLongPressDeleteEnabled,
                                onCheckedChange = { viewModel.updateWearLongPressDeleteEnabled(it) }
                            )
                        }

                        if (wearLongPressDeleteEnabled) {
                            Spacer(modifier = Modifier.height(4.dp))
                            Column(
                                modifier = Modifier.fillMaxWidth(),
                                verticalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = if (appLanguage == "el") "Διάρκεια Πατήματος" else "Long Press Duration",
                                        fontSize = 14.sp,
                                        fontWeight = FontWeight.Medium,
                                        color = MaterialTheme.colorScheme.onSurface
                                    )
                                    Text(
                                        text = "${wearLongPressDeleteDuration} ms",
                                        fontSize = 14.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.primary
                                    )
                                }
                                CapsulePatternSlider(
                                    value = wearLongPressDeleteDuration.toFloat(),
                                    onValueChange = { viewModel.updateWearLongPressDeleteDuration(it.toInt()) },
                                    valueRange = 100f..3000f,
                                    stepsCount = 30, // Increment of 100 ms
                                    triggerHaptic = { viewModel.triggerSliderHaptic() },
                                    modifier = Modifier.fillMaxWidth()
                                )
                            }
                        }
                    }

                }
            }
            
            ChunkySettingCard(
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(
                    modifier = Modifier.fillMaxWidth().padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(20.dp)
                ) {
                    // Haptic strength
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Text(
                            text = if (appLanguage == "el") "Ένταση Απτικής Ανάδρασης" else "Vibration Feedback Strength",
                            fontSize = 16.sp,
                            fontWeight = FontWeight.SemiBold,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(16.dp))
                                .background(if (isFrostedGlassEnabled) Color.White.copy(alpha = 0.08f) else MaterialTheme.colorScheme.surfaceVariant)
                                .border(1.dp, strokeColor, RoundedCornerShape(16.dp))
                                .padding(4.dp),
                            horizontalArrangement = Arrangement.spacedBy(4.dp)
                        ) {
                            val options = listOf(
                                "NONE" to if (appLanguage == "el") "Όχι" else "None",
                                "LIGHT" to if (appLanguage == "el") "Απαλή" else "Light",
                                "MEDIUM" to if (appLanguage == "el") "Μέτρια" else "Medium",
                                "STRONG" to if (appLanguage == "el") "Ισχυρή" else "Strong"
                            )
                            
                            options.forEach { (key, label) ->
                                val isSelected = wearHapticStrength == key
                                Box(
                                    modifier = Modifier
                                        .weight(1f)
                                        .clip(RoundedCornerShape(12.dp))
                                        .background(
                                            if (isSelected) {
                                                MaterialTheme.colorScheme.primary
                                            } else {
                                                Color.Transparent
                                            }
                                        )
                                        .clickable {
                                            viewModel.updateWearHapticStrength(key)
                                        }
                                        .padding(vertical = 10.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Text(
                                        text = label,
                                        fontSize = 12.sp,
                                        fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                                        color = if (isSelected) {
                                            MaterialTheme.colorScheme.onPrimary
                                        } else {
                                            MaterialTheme.colorScheme.onSurfaceVariant
                                        }
                                    )
                                }
                            }
                        }
                    }

                }
            }
            
            // Complication Display Style Card
            ChunkySettingCard(
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(
                    modifier = Modifier.fillMaxWidth().padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(14.dp)
                ) {
                    Column(modifier = Modifier.fillMaxWidth()) {
                        Text(
                            text = if (appLanguage == "el") "Εμφάνιση Επιπλοκής (Complication)" else "Complication Display",
                            fontSize = 16.sp,
                            fontWeight = FontWeight.SemiBold,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        Spacer(modifier = Modifier.height(2.dp))
                        Text(
                            text = if (appLanguage == "el") "Επιλέξτε την εμφανιζόμενη μορφή της επιπλοκής στην όψη του ρολογιού." else "Choose what is displayed on your watch face complication.",
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }

                    val styles = listOf(
                        "APP_ICON" to (if (appLanguage == "el") "Εικονίδιο Εφαρμογής" else "Actual App Icon"),
                        "DROPLET" to (if (appLanguage == "el") "Σταγόνα Νερού" else "Generic Droplet"),
                        "PROGRESS_CIRCLE" to (if (appLanguage == "el") "Κύκλος Προόδου" else "Small Progress Circle"),
                        "INVISIBLE" to (if (appLanguage == "el") "Αόρατο" else "Invisible")
                    )

                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        styles.forEach { (styleKey, styleLabel) ->
                            val isSelected = wearComplicationIconStyle == styleKey
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clip(RoundedCornerShape(12.dp))
                                    .background(
                                        if (isSelected) MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.6f)
                                        else MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.2f)
                                    )
                                    .border(
                                        width = 1.dp,
                                        color = if (isSelected) MaterialTheme.colorScheme.primary else strokeColor,
                                        shape = RoundedCornerShape(12.dp)
                                    )
                                    .clickable { viewModel.updateWearComplicationIconStyle(styleKey) }
                                    .padding(horizontal = 14.dp, vertical = 10.dp),
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Column(modifier = Modifier.weight(1f)) {
                                    Text(
                                        text = styleLabel,
                                        fontSize = 14.sp,
                                        fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                                        color = if (isSelected) MaterialTheme.colorScheme.onPrimaryContainer else MaterialTheme.colorScheme.onSurface
                                    )
                                    val desc = when (styleKey) {
                                        "APP_ICON" -> if (appLanguage == "el") "Αυθεντικό εικονίδιο εφαρμογής (χωρίς παραποίηση)" else "Unaltered full-color app launcher icon"
                                        "DROPLET" -> if (appLanguage == "el") "Κλασικό εικονίδιο σταγόνας νερού" else "Classic minimal water droplet icon"
                                        "PROGRESS_CIRCLE" -> if (appLanguage == "el") "Μικρός κύκλος προόδου (χωρίς το κείμενο +250)" else "Small progress circle (without +250 text)"
                                        "INVISIBLE" -> if (appLanguage == "el") "Πλήρως αόρατη επιπλοκή (διάφανη)" else "Completely transparent / invisible icon"
                                        else -> ""
                                    }
                                    if (desc.isNotEmpty()) {
                                        Text(
                                            text = desc,
                                            fontSize = 11.sp,
                                            color = MaterialTheme.colorScheme.onSurfaceVariant
                                        )
                                    }
                                }
                                RadioButton(
                                    selected = isSelected,
                                    onClick = { viewModel.updateWearComplicationIconStyle(styleKey) }
                                )
                            }
                        }
                    }
                }
            }
            
            ChunkySettingCard(
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(
                    modifier = Modifier.fillMaxWidth().padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(20.dp)
                ) {
                    // Swipe Gesture Mode
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Column(modifier = Modifier.fillMaxWidth()) {
                            Text(
                                text = if (appLanguage == "el") "Τρόπος Σύρσης (Swipe)" else "Swipe Gesture Mode",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = if (appLanguage == "el") "Αλλαγή ημέρας με σύρση πάνω/κάτω ή αριστερά/δεξιά στο ρολόι." else "Navigate between days by swiping vertically or horizontally on watch.",
                                fontSize = 12.sp,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }

                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .clip(RoundedCornerShape(8.dp))
                                .background(MaterialTheme.colorScheme.secondaryContainer.copy(alpha = 0.4f))
                                .padding(3.dp),
                            horizontalArrangement = Arrangement.spacedBy(2.dp)
                        ) {
                            val modes = listOf(
                                "VERTICAL" to (if (appLanguage == "el") "Κατακόρυφα" else "Vertical"),
                                "HORIZONTAL" to (if (appLanguage == "el") "Οριζόντια" else "Horizontal"),
                                "OFF" to (if (appLanguage == "el") "Ανενεργό" else "Off")
                            )
                            modes.forEach { (modeKey, modeLabel) ->
