                                }
                                Switch(
                                    checked = wearDevOverlayEnabled,
                                    onCheckedChange = { viewModel.updateWearDevOverlayEnabled(it) }
                                )
                            }

                            if (wearDevOverlayEnabled) {
                                Text(
                                    text = "RGB Overlay Color: RGB($wearDevOverlayR, $wearDevOverlayG, $wearDevOverlayB)",
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.onSurface
                                )

                                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                    // Red slider
                                    Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
                                        Text("R: ", fontSize = 12.sp, modifier = Modifier.width(20.dp), fontWeight = FontWeight.Bold)
                                         CapsulePatternSlider(
                                             value = wearDevOverlayR.toFloat(),
                                             onValueChange = { viewModel.updateWearDevOverlayR(it.toInt()) },
                                             valueRange = 0f..255f,
                                             stepsCount = 256,
                                             triggerHaptic = { viewModel.triggerSliderHaptic() },
                                             activeColor = Color.Red,
                                             modifier = Modifier.weight(1f)
                                         )
                                        Text("${wearDevOverlayR}", fontSize = 12.sp, modifier = Modifier.width(30.dp), textAlign = androidx.compose.ui.text.style.TextAlign.End)
                                    }

                                    // Green slider
                                    Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
                                        Text("G: ", fontSize = 12.sp, modifier = Modifier.width(20.dp), fontWeight = FontWeight.Bold)
                                         CapsulePatternSlider(
                                             value = wearDevOverlayG.toFloat(),
                                             onValueChange = { viewModel.updateWearDevOverlayG(it.toInt()) },
                                             valueRange = 0f..255f,
                                             stepsCount = 256,
                                             triggerHaptic = { viewModel.triggerSliderHaptic() },
                                             activeColor = Color.Green,
                                             modifier = Modifier.weight(1f)
                                         )
                                        Text("${wearDevOverlayG}", fontSize = 12.sp, modifier = Modifier.width(30.dp), textAlign = androidx.compose.ui.text.style.TextAlign.End)
                                    }

                                    // Blue slider
                                    Row(verticalAlignment = Alignment.CenterVertically, modifier = Modifier.fillMaxWidth()) {
                                        Text("B: ", fontSize = 12.sp, modifier = Modifier.width(20.dp), fontWeight = FontWeight.Bold)
                                         CapsulePatternSlider(
                                             value = wearDevOverlayB.toFloat(),
                                             onValueChange = { viewModel.updateWearDevOverlayB(it.toInt()) },
                                             valueRange = 0f..255f,
                                             stepsCount = 256,
                                             triggerHaptic = { viewModel.triggerSliderHaptic() },
                                             activeColor = Color.Blue,
                                             modifier = Modifier.weight(1f)
                                         )
                                        Text("${wearDevOverlayB}", fontSize = 12.sp, modifier = Modifier.width(30.dp), textAlign = androidx.compose.ui.text.style.TextAlign.End)
                                    }
                                }
                            }
                        }
                    }
                }
            }

            val wearGraphDaysPrior by viewModel.wearGraphDaysPrior.collectAsStateWithLifecycle()
            val wearGraphPillarThickness by viewModel.wearGraphPillarThickness.collectAsStateWithLifecycle()
            val wearGraphHorizontalPadding by viewModel.wearGraphHorizontalPadding.collectAsStateWithLifecycle()
            val wearPastDaysToShow by viewModel.wearPastDaysToShow.collectAsStateWithLifecycle()
            ChunkySettingCard(
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(
                    modifier = Modifier.fillMaxWidth().padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text = if (appLanguage == "el") "Ημέρες Ιστορικού Ρολογιού" else "Watch Graph Days Prior",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = if (appLanguage == "el") "Πόσες ημέρες στο παρελθόν θα εμφανίζει το γράφημα στο ρολόι." else "Control how many days prior the watch graph can display.",
                                fontSize = 12.sp,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                        Text(
                            text = if (appLanguage == "el") "$wearGraphDaysPrior ημ." else "$wearGraphDaysPrior d",
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary
                        )
                    }

                    CapsulePatternSlider(
                        value = wearGraphDaysPrior.toFloat(),
                        onValueChange = { viewModel.updateWearGraphDaysPrior(it.toInt()) },
                        valueRange = 1f..30f,
                        stepsCount = 30,
                        triggerHaptic = { viewModel.triggerSliderHaptic() },
                        modifier = Modifier.fillMaxWidth()
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            ChunkySettingCard(
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(
                    modifier = Modifier.fillMaxWidth().padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    ResettableCapsuleSliderRow(
                        title = if (appLanguage == "el") "Πάχος Στηλών Γραφήματος Ρολογιού" else "Watch Graph Pillar Thickness",
                        value = wearGraphPillarThickness,
                        defaultValue = 24f,
                        valueRange = 12f..48f,
                        onValueChange = { viewModel.updateWearGraphPillarThickness(it) },
                        triggerHaptic = { viewModel.triggerSliderHaptic() },
                        unit = "dp",
                        isInt = true
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            ChunkySettingCard(
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(
                    modifier = Modifier.fillMaxWidth().padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    ResettableCapsuleSliderRow(
                        title = if (appLanguage == "el") "Οριζόντιο Περιθώριο Γραφήματος Ρολογιού" else "Watch Graph Edge Padding",
                        value = wearGraphHorizontalPadding,
                        defaultValue = 18f,
                        valueRange = 0f..48f,
                        onValueChange = { viewModel.updateWearGraphHorizontalPadding(it) },
                        triggerHaptic = { viewModel.triggerSliderHaptic() },
                        unit = "dp",
                        isInt = true
                    )
                    Text(
                        text = if (appLanguage == "el") "Προσθέτει οριζόντιο περιθώριο στις άκρες του γραφήματος ώστε οι ακριανές τιμές και στήλες να μην κρύβονται από το κυρτό πλαίσιο του ρολογιού." else "Adds horizontal padding to the graph edges so end values and pillars are not hidden by curved watch bezels.",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            ChunkySettingCard(
                modifier = Modifier.fillMaxWidth()
            ) {
                Column(
                    modifier = Modifier.fillMaxWidth().padding(20.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text = if (appLanguage == "el") "Ημέρες Προόδου Κύκλου Ρολογιού" else "Watch Progress Circle Past Days",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = if (appLanguage == "el") "Πόσες ημέρες στο παρελθόν θα εμφανίζει ο κύκλος προόδου (λιγότερες σημαίνει ταχύτερη εκκίνηση)." else "How many days in the past the watch progress circle can show (fewer means faster booting).",
                                fontSize = 12.sp,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                        Text(
                            text = if (appLanguage == "el") "$wearPastDaysToShow ημ." else "$wearPastDaysToShow d",
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.primary
                        )
                    }

                    CapsulePatternSlider(
                        value = wearPastDaysToShow.toFloat(),
                        onValueChange = { viewModel.updateWearPastDaysToShow(it.toInt()) },
                        valueRange = 1f..7f,
                        stepsCount = 7,
                        triggerHaptic = { viewModel.triggerSliderHaptic() },
                        modifier = Modifier.fillMaxWidth()
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // 3. Manual Sync / Reset Settings Card
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(24.dp))
                    .background(customCardBrush)
                    .border(1.dp, strokeColor, RoundedCornerShape(24.dp))
                    .padding(18.dp)
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = if (appLanguage == "el") "Μη αυτόματος συγχρονισμός" else "Manual Data Sync",
                            fontSize = 15.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        Text(
                            text = if (appLanguage == "el") "Αναγκαστική αποστολή όλων των δεδομένων στο ρολόι." else "Force push current goal and water status to companion app.",
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                    
                    Button(
                        onClick = {
                            viewModel.triggerWearOsSync()
                            Toast.makeText(context, if (appLanguage == "el") "Τα δεδομένα στάλθηκαν επιτυχώς!" else "Wear OS Sync forced successfully!", Toast.LENGTH_SHORT).show()
                        },
                        shape = RoundedCornerShape(16.dp),
                        colors = ButtonDefaults.buttonColors(
                            containerColor = MaterialTheme.colorScheme.primaryContainer,
                            contentColor = MaterialTheme.colorScheme.onPrimaryContainer
                        )
                    ) {
                        Row(
                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Icon(
                                imageVector = Icons.Rounded.Sync,
                                contentDescription = "Sync icon",
                                modifier = Modifier.size(16.dp)
                            )
                            Text(
                                text = if (appLanguage == "el") "Συγχρονισμός" else "Sync",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                }
            }



            // 4b. Pre-bundled Wear OS Sideload Card
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(24.dp))
                    .background(customCardBrush)
                    .border(1.dp, strokeColor, RoundedCornerShape(24.dp))
                    .padding(18.dp)
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = if (appLanguage == "el") "Εγκατάσταση Wear OS (Offline)" else "Sideload Wear OS Companion",
                            fontSize = 15.sp,
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        Text(
                            text = if (appLanguage == "el") "Εξαγωγή & κοινοποίηση του προ-ενσωματωμένου Wear OS APK για άμεση εγκατάσταση." else "Extract & share the high-performance offline pre-bundled Wear OS companion APK.",
                            fontSize = 12.sp,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                    
                    Spacer(modifier = Modifier.width(8.dp))

                    Button(
                        onClick = {
                            viewModel.exportPrebundledWearApk(context)
                        },
                        shape = RoundedCornerShape(16.dp),
                        colors = ButtonDefaults.buttonColors(
                            containerColor = MaterialTheme.colorScheme.secondaryContainer,
                            contentColor = MaterialTheme.colorScheme.onSecondaryContainer
                        )
                    ) {
                        Row(
                            horizontalArrangement = Arrangement.spacedBy(4.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Icon(
                                imageVector = Icons.Rounded.Watch,
                                contentDescription = "Sideload icon",
                                modifier = Modifier.size(16.dp)
                            )
                            Text(
                                text = if (appLanguage == "el") "Εξαγωγή" else "Sideload",
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                }
            }

            // 4c. Device Entry Display settings (Device name, origin, bold toggles)
            val showDeviceOriginText by viewModel.showDeviceOriginText.collectAsStateWithLifecycle()
            val boldDeviceOriginText by viewModel.boldDeviceOriginText.collectAsStateWithLifecycle()

            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(24.dp))
                    .background(customCardBrush)
                    .border(1.dp, strokeColor, RoundedCornerShape(24.dp))
                    .padding(18.dp)
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
                    Text(
                        text = if (appLanguage == "el") "Εμφάνιση Προέλευσης Συσκευής" else "Device Entry Display",
                        fontSize = 15.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text = if (appLanguage == "el") "Εμφάνιση ονόματος συσκευής" else "Show device name",
                                fontSize = 14.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Text(
                                text = if (appLanguage == "el") "Εμφανίζει το όνομα της συσκευής (π.χ. Pixel Watch) στις καταγραφές." else "Show device name (e.g. Pixel Watch) in log history.",
                                fontSize = 12.sp,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                        Switch(
                            checked = showDeviceOriginText,
                            onCheckedChange = { viewModel.updateShowDeviceOriginText(it) }
                        )
                    }

                    if (showDeviceOriginText) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    text = if (appLanguage == "el") "Έντονη γραφή ονόματος" else "Bold device name",
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.SemiBold,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                                Text(
                                    text = if (appLanguage == "el") "Κάνει το όνομα της συσκευής να εμφανίζεται με έντονα γράμματα." else "Display the device name in bold letters in the logs.",
                                    fontSize = 12.sp,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                            Switch(
                                checked = boldDeviceOriginText,
                                onCheckedChange = { viewModel.updateBoldDeviceOriginText(it) }
                            )
                        }
                    }
                }
            }
        }
    }
}

fun androidx.compose.foundation.lazy.LazyListScope.renderWidgetSettingsSection(
    viewModel: WaterViewModel,
    appLanguage: String
) {
    item {
        SettingsCategoryHeader(
            title = if (appLanguage == "el") "ΕΜΦΑΝΙΣΗ ΜΙΚΡΟΕΦΑΡΜΟΓΗΣ" else "WIDGET PREVIEW & STYLING",
            icon = Icons.Rounded.Widgets
        )
    }

    item {
        val context = androidx.compose.ui.platform.LocalContext.current
        val coroutineScope = rememberCoroutineScope()
        val widgetPrefs = remember { context.getSharedPreferences("water_tracker_prefs", Context.MODE_PRIVATE) }
        var selectedBgOption by remember { 
            mutableStateOf(widgetPrefs.getString("widget_bg_option", "opaque") ?: "opaque") 
        }
        var widgetDisplayMode by remember {
            mutableStateOf(widgetPrefs.getString("widget_display_mode", "left") ?: "left")
        }
        var widgetTranslucentInvisible by remember {
            mutableStateOf(widgetPrefs.getBoolean("widget_translucent_invisible", false))
        }

        val totalIntakeVal by viewModel.totalIntakeToday.collectAsStateWithLifecycle()
        val dailyGoalVal by viewModel.dailyGoalMl.collectAsStateWithLifecycle()
        val fillRatio = if (dailyGoalVal > 0) (totalIntakeVal.toFloat() / dailyGoalVal.toFloat()).coerceIn(0f, 1f) else 1f

        Column(
            modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            // --- THEME SELECTION OPTIONS ---
            ChunkySettingCard {
                Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
                    Text(
                        text = if (appLanguage == "el") "Επιλέξτε το στυλ φόντου" else "Select Background Theme",
                        fontSize = 17.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface
                    )

                    Text(
                        text = if (appLanguage == "el") 
                            "Η μικροεφαρμογή της αρχικής οθόνης θα ενημερώσει την εμφάνισή της σύμφωνα με την επιλεγμένη ρύθμιση." 
                            else "The home screen widget will adapt its outer container style dynamically according to this selection.",
                        fontSize = 13.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )

                    val options = listOf(
                        Triple(
                            "opaque", 
                            if (appLanguage == "el") "Αδιαφανές (Προσαρμόσιμο)" else "Opaque (Adaptive)",
                            if (appLanguage == "el") "Ανοιχτόχρωμο ή σκούρο ανάλογα με το θέμα συστήματος." else "Adaptive contrast background matching system theme mode."
                        ),
                        Triple(
                            "translucent", 
                            if (appLanguage == "el") "Ημιδιαφανές (Glow)" else "Translucent (Glass)",
                            if (appLanguage == "el") "Ημιδιαφανές εφέ γυαλιού, ιδανικό για όμορφα wallpapers." else "Glass-morphic alpha blends beautifully with any launcher wallpaper."
                        ),
                        Triple(
                            "oled", 
                            if (appLanguage == "el") "Απόλυτο Μαύρο (OLED)" else "OLED Pitch Black",
                            if (appLanguage == "el") "Καθαρό μαύρο χρώμα για εξοικονόμηση μπαταρίας." else "Saves power on AMOLED screens with true pitch black backgrounds."
                        )
                    )

                    options.forEach { (key, title, desc) ->
                        val isSelected = selectedBgOption == key
                        val cornerRadius by androidx.compose.animation.core.animateDpAsState(
                            targetValue = if (isSelected) 24.dp else 10.dp,
                            label = "widgetOptionCornerRadius"
                        )
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(
                                    color = if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surfaceVariant,
                                    shape = RoundedCornerShape(cornerRadius)
                                )
                                .then(
                                    if (!isSelected) Modifier.border(
                                        width = 1.dp,
                                        color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f),
                                        shape = RoundedCornerShape(cornerRadius)
                                    ) else Modifier
                                )
                                .clickable {
                                    selectedBgOption = key
                                    widgetPrefs.edit().putString("widget_bg_option", key).apply()
                                    viewModel.triggerButtonHaptic()
                                    coroutineScope.launch {
                                        try {
                                            com.pixelwater.app.widget.WaterTrackerWidget().updateAll(context)
                                        } catch (e: Exception) {
                                            android.util.Log.e("WaterTrackerScreen", "Failed updating widgets", e)
                                        }
                                    }
                                }
                                .padding(16.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    text = title,
                                    fontSize = 16.sp,
                                    fontWeight = FontWeight.ExtraBold,
                                    color = if (isSelected) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurface
                                )
                                Spacer(modifier = Modifier.height(2.dp))
                                Text(
                                    text = desc,
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Medium,
                                    color = if (isSelected) MaterialTheme.colorScheme.onPrimary.copy(alpha = 0.85f) else MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }

                            RadioButton(
                                selected = isSelected,
                                onClick = {
                                    selectedBgOption = key
                                    widgetPrefs.edit().putString("widget_bg_option", key).apply()
                                    viewModel.triggerButtonHaptic()
                                    coroutineScope.launch {
                                        try {
                                            com.pixelwater.app.widget.WaterTrackerWidget().updateAll(context)
                                        } catch (e: Exception) {
                                            android.util.Log.e("WaterTrackerScreen", "Failed updating widgets", e)
                                        }
                                    }
                                },
                                colors = RadioButtonDefaults.colors(
                                    selectedColor = MaterialTheme.colorScheme.onPrimary,
                                    unselectedColor = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            )
                        }
                    }
                }
            }

            // --- ADDITIONAL WIDGET CUSTOMISATIONS ---
            ChunkySettingCard {
                Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
                    Text(
                        text = if (appLanguage == "el") "Προσαρμογή Μικροεφαρμογής" else "Widget Customization",
                        fontSize = 17.sp,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface
                    )

                    // 1. Show Remaining Water Toggle
                    val isMlLeft = widgetDisplayMode == "left"
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(
                                color = if (isMlLeft) MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.surfaceVariant,
                                shape = RoundedCornerShape(24.dp)
                            )
                            .border(
                                width = 2.dp,
                                color = if (isMlLeft) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f),
                                shape = RoundedCornerShape(24.dp)
                            )
                            .clickable {
                                val newVal = if (isMlLeft) "added" else "left"
                                widgetDisplayMode = newVal
                                widgetPrefs.edit().putString("widget_display_mode", newVal).apply()
                                viewModel.triggerButtonHaptic()
                                coroutineScope.launch {
                                    try {
                                        com.pixelwater.app.widget.WaterTrackerWidget().updateAll(context)
                                    } catch (e: Exception) {
                                        android.util.Log.e("WaterTrackerScreen", "Failed updating widgets", e)
                                    }
                                }
                            }
                            .padding(16.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text = if (appLanguage == "el") "Εμφάνιση υπολειπόμενου νερού" else "Show Remaining Water",
                                fontSize = 16.sp,
                                fontWeight = FontWeight.ExtraBold,
                                color = if (isMlLeft) MaterialTheme.colorScheme.onPrimaryContainer else MaterialTheme.colorScheme.onSurface
                            )
                            Spacer(modifier = Modifier.height(2.dp))
                            Text(
                                text = if (appLanguage == "el") 
                                    "Ενεργοποιήστε για να εμφανίζεται το υπολειπόμενο νερό αντί για το προστιθέμενο." 
                                    else "Show remaining milliliters left to target rather than total amount added.",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Medium,
                                color = if (isMlLeft) MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.8f) else MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                        androidx.compose.material3.Switch(
                            checked = isMlLeft,
                            onCheckedChange = { checked ->
                                val newVal = if (checked) "left" else "added"
                                widgetDisplayMode = newVal
                                widgetPrefs.edit().putString("widget_display_mode", newVal).apply()
                                viewModel.triggerToggleHaptic(reversed = !checked)
                                coroutineScope.launch {
                                    try {
                                        com.pixelwater.app.widget.WaterTrackerWidget().updateAll(context)
                                    } catch (e: Exception) {
                                        android.util.Log.e("WaterTrackerScreen", "Failed updating widgets", e)
                                    }
                                }
                            },
                            colors = androidx.compose.material3.SwitchDefaults.colors(
                                checkedThumbColor = MaterialTheme.colorScheme.primary
                            )
                        )
                    }

                    // 2. Invisible Wallpaper Mode Toggle (only visible when translucent is selected!)
                    if (selectedBgOption == "translucent") {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(
                                    color = if (widgetTranslucentInvisible) MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.surfaceVariant,
                                    shape = RoundedCornerShape(24.dp)
                                )
                                .border(
                                    width = 2.dp,
                                    color = if (widgetTranslucentInvisible) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f),
                                    shape = RoundedCornerShape(24.dp)
                                )
                                .clickable {
                                    val newVal = !widgetTranslucentInvisible
                                    widgetTranslucentInvisible = newVal
                                    widgetPrefs.edit().putBoolean("widget_translucent_invisible", newVal).apply()
                                    viewModel.triggerToggleHaptic(reversed = !newVal)
                                    coroutineScope.launch {
                                        try {
                                            com.pixelwater.app.widget.WaterTrackerWidget().updateAll(context)
                                        } catch (e: Exception) {
                                            android.util.Log.e("WaterTrackerScreen", "Failed updating widgets", e)
                                        }
                                    }
                                }
                                .padding(16.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    text = if (appLanguage == "el") "Πλήρης Διαφάνεια (Αόρατο Φόντο)" else "Full Transparency (Invisible Background)",
                                    fontSize = 16.sp,
                                    fontWeight = FontWeight.ExtraBold,
                                    color = if (widgetTranslucentInvisible) MaterialTheme.colorScheme.onPrimaryContainer else MaterialTheme.colorScheme.onSurface
                                )
                                Spacer(modifier = Modifier.height(2.dp))
                                Text(
                                    text = if (appLanguage == "el") 
                                        "Καταργεί πλήρως το φόντο κάνοντας το πλαίσιο της μικροεφαρμογής αόρατο." 
                                        else "Completely removes the background, making the widget container fully invisible.",
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Medium,
                                    color = if (widgetTranslucentInvisible) MaterialTheme.colorScheme.onPrimaryContainer.copy(alpha = 0.8f) else MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                            androidx.compose.material3.Switch(
                                checked = widgetTranslucentInvisible,
                                onCheckedChange = { checked ->
                                    widgetTranslucentInvisible = checked
                                    widgetPrefs.edit().putBoolean("widget_translucent_invisible", checked).apply()
                                    viewModel.triggerToggleHaptic(reversed = !checked)
                                    coroutineScope.launch {
                                        try {
                                            com.pixelwater.app.widget.WaterTrackerWidget().updateAll(context)
                                        } catch (e: Exception) {
                                            android.util.Log.e("WaterTrackerScreen", "Failed updating widgets", e)
                                        }
                                    }
                                },
                                colors = androidx.compose.material3.SwitchDefaults.colors(
                                    checkedThumbColor = MaterialTheme.colorScheme.primary
                                )
                            )
                        }
                    }
                }
            }
        }
    }
}

fun androidx.compose.foundation.lazy.LazyListScope.renderTileSettingsSection(
    viewModel: WaterViewModel,
    appLanguage: String
) {
    item {
        SettingsCategoryHeader(
            title = if (appLanguage == "el") "ΠΡΟΣΑΡΜΟΓΗ ΠΛΑΚΙΔΙΟΥ" else "QUICK SETTINGS TILE CUSTOMIZATION",
            icon = Icons.Rounded.SpaceDashboard
        )
    }

    item {
        val coroutineScope = rememberCoroutineScope()
        val tileQuickAddAmount by viewModel.tileQuickAddAmount.collectAsStateWithLifecycle()
        val tileDisplayMode by viewModel.tileDisplayMode.collectAsStateWithLifecycle()
        val tileIconType by viewModel.tileIconType.collectAsStateWithLifecycle()
        val tileLongPressAppLaunch by viewModel.tileLongPressAppLaunch.collectAsStateWithLifecycle()

        ChunkySettingCard(
            modifier = Modifier.padding(horizontal = 16.dp)
        ) {
            Column(modifier = Modifier.fillMaxWidth()) {
                // --- QUICK ADD AMOUNT OPTION ---
                Column(modifier = Modifier.padding(20.dp)) {
                    Text(
                        text = if (appLanguage == "el") "Ποσότητα Γρήγορης Προσθήκης" else "Quick Add Amount",
                        fontSize = 15.sp,
                        fontWeight = FontWeight.SemiBold,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = if (appLanguage == "el") "Επιλέξτε την ποσότητα ml που θα καταγράφεται" else "Select the volume (ml) added upon tapping the tile.",
                        fontSize = 13.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                    Spacer(modifier = Modifier.height(12.dp))
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        listOf(250, 500).forEach { amount ->
                            val isSelected = tileQuickAddAmount == amount
                            val cornerRadius by androidx.compose.animation.core.animateDpAsState(
                                targetValue = if (isSelected) 24.dp else 10.dp,
                                label = "quickAddCornerRadius"
                            )
                            Surface(
                                modifier = Modifier.weight(1f),
                                onClick = {
                                    viewModel.updateTileQuickAddAmount(amount)
                                    viewModel.triggerButtonHaptic()
                                },
                                shape = RoundedCornerShape(cornerRadius),
                                color = if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surfaceVariant,
                                border = if (!isSelected) androidx.compose.foundation.BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f)) else null
                            ) {
                                Box(modifier = Modifier.padding(vertical = 12.dp), contentAlignment = Alignment.Center) {
                                    Text(
                                        text = "$amount ml",
                                        fontWeight = FontWeight.Bold,
                                        color = if (isSelected) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                }
                            }
                        }
                    }
                }
                
                HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f), thickness = 1.dp)

                // --- TILE DISPLAY MODE OPTION ---
                Column(modifier = Modifier.padding(20.dp)) {
                    Text(
                        text = if (appLanguage == "el") "Λειτουργία Εμφάνισης Πληροφοριών" else "Tile Display Mode",
                        fontSize = 15.sp,
                        fontWeight = FontWeight.SemiBold,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = if (appLanguage == "el") "Τι να εμφανίζεται ως υπότιτλος στο πλακίδιο;" else "What should the tile subtitle display?",
                        fontSize = 13.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                    Spacer(modifier = Modifier.height(12.dp))
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        val displayOptions = listOf(
                            "remaining" to (if (appLanguage == "el") "Υπολειπόμενο" else "Remaining Goal"),
                            "added" to (if (appLanguage == "el") "Προστιθέμενο" else "Water Added")
                        )
                        displayOptions.forEach { (mode, title) ->
                            val isSelected = tileDisplayMode == mode
                            val cornerRadius by androidx.compose.animation.core.animateDpAsState(
                                targetValue = if (isSelected) 24.dp else 10.dp,
                                label = "displayModeCornerRadius"
                            )
                            Surface(
                                modifier = Modifier.weight(1f),
                                onClick = {
                                    viewModel.updateTileDisplayMode(mode)
                                    viewModel.triggerButtonHaptic()
                                },
                                shape = RoundedCornerShape(cornerRadius),
                                color = if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surfaceVariant,
                                border = if (!isSelected) androidx.compose.foundation.BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f)) else null
                            ) {
                                Box(modifier = Modifier.padding(vertical = 12.dp), contentAlignment = Alignment.Center) {
                                    Text(
                                        text = title,
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 13.sp,
                                        textAlign = TextAlign.Center,
                                        color = if (isSelected) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                }
                            }
                        }
                    }
                }
                
                HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f), thickness = 1.dp)

                // --- TILE ICON TYPE OPTION ---
                Column(modifier = Modifier.padding(20.dp)) {
                    Text(
                        text = if (appLanguage == "el") "Τύπος Εικονιδίου Πλακιδίου" else "Tile Icon Type",
                        fontSize = 15.sp,
                        fontWeight = FontWeight.SemiBold,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = if (appLanguage == "el") "Επιλέξτε την εμφάνιση του εικονιδίου." else "Select the visual style of the tile's active icon.",
                        fontSize = 13.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                    Spacer(modifier = Modifier.height(12.dp))
                    Column(
                        modifier = Modifier.fillMaxWidth(),
                        verticalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        val iconOptions = listOf(
                            "stars" to (if (appLanguage == "el") "Αστέρια" else "Cluster of Stars"),
                            "droplet" to (if (appLanguage == "el") "Σταγόνα" else "Generic Droplet"),
                            "actual_app_icon" to (if (appLanguage == "el") "Εικονίδιο Εφαρμογής" else "Actual App Icon")
                        )
                        iconOptions.forEach { (type, title) ->
                            val isSelected = tileIconType == type
                            val cornerRadius by androidx.compose.animation.core.animateDpAsState(
                                targetValue = if (isSelected) 24.dp else 10.dp,
                                label = "iconTypeCornerRadius"
                            )
                            Surface(
                                modifier = Modifier.fillMaxWidth(),
                                onClick = {
                                    viewModel.updateTileIconType(type)
                                    viewModel.triggerButtonHaptic()
                                },
                                shape = RoundedCornerShape(cornerRadius),
                                color = if (isSelected) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surfaceVariant,
                                border = if (!isSelected) androidx.compose.foundation.BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f)) else null
                            ) {
                                Row(
                                    modifier = Modifier.padding(horizontal = 16.dp, vertical = 14.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text(
                                        text = title,
                                        fontWeight = FontWeight.Bold,
                                        color = if (isSelected) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant
                                    )
                                    if (isSelected) {
                                        Icon(
                                            imageVector = Icons.Rounded.Check,
                                            contentDescription = null,
                                            tint = MaterialTheme.colorScheme.onPrimary,
                                            modifier = Modifier.size(20.dp)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }

                HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f), thickness = 1.dp)

                // --- TILE LONG PRESS APP LAUNCH ---
                Column(modifier = Modifier.padding(20.dp)) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text = if (appLanguage == "el") "Παρατεταμένο Πάτημα Πλακιδίου" else "Tile Long Press App Launch",
                                fontSize = 15.sp,
                                fontWeight = FontWeight.SemiBold,
                                color = MaterialTheme.colorScheme.onSurface
                            )
                            Spacer(modifier = Modifier.height(4.dp))
                            Text(
                                text = if (appLanguage == "el")
                                    "Ανοίξτε το Pixel Water κατά το παρατεταμένο πάτημα αντί για τις ρυθμίσεις συστήματος."
                                    else "Launch the Pixel Water app directly on long press instead of opening system app details.",
                                fontSize = 13.sp,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                        Spacer(modifier = Modifier.width(12.dp))
                        ChunkySettingSwitch(
                            checked = tileLongPressAppLaunch,
                            onCheckedChange = { checked ->
                                viewModel.updateTileLongPressAppLaunch(checked)
                                viewModel.triggerButtonHaptic()
                            }
                        )
                    }
                }
            }
        }
    }
}

fun androidx.compose.foundation.lazy.LazyListScope.renderDeveloperOptionsSection(
    viewModel: WaterViewModel,
    appLanguage: String,
    isDeveloper: Boolean,
    isEmailDeveloper: Boolean
) {
    item {
        ChunkySettingCard {
            Column(
                modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                Box(
                    modifier = Modifier
                        .size(60.dp)
                        .background(MaterialTheme.colorScheme.primaryContainer, shape = CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        imageVector = Icons.Rounded.Settings,
                        contentDescription = "Developer Settings icon",
                        tint = MaterialTheme.colorScheme.onPrimaryContainer,
                        modifier = Modifier.size(32.dp)
                    )
                }

                Column(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    Text(
                        text = if (appLanguage == "el") "Επιλογές Προγραμματιστή" else "Developer Options",
                        fontSize = 20.sp,
                        fontWeight = FontWeight.ExtraBold,
                        color = MaterialTheme.colorScheme.onSurface,
                        textAlign = TextAlign.Center
                    )
                    Text(
                        text = if (appLanguage == "el") 
                            "Λειτουργία Προγραμματιστή Ενεργή" 
                            else "Developer Mode Active",
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.8f),
                        textAlign = TextAlign.Center,
                        fontWeight = FontWeight.Bold
                    )
                }

                Spacer(modifier = Modifier.height(4.dp))
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(MaterialTheme.colorScheme.surfaceContainer, RoundedCornerShape(12.dp))
                        .padding(16.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Text(
                        text = if (appLanguage == "el") "Λειτουργία Προγραμματιστή" else "Developer Mode",
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    val isDeveloperInternal by viewModel.isDeveloper.collectAsStateWithLifecycle()
                    ChunkySettingSwitch(
                        checked = isDeveloperInternal,
                        onCheckedChange = { viewModel.updateDeveloperMode(it) }
                    )
                }


            }
        }
    }

    item {
        DevDatabaseInspectorCard(
            viewModel = viewModel,
            appLanguage = appLanguage,
            isEmailDeveloper = isEmailDeveloper
        )
    }

    item {
        DevChronoInjectorCard(viewModel = viewModel, appLanguage = appLanguage)
    }

    item {
        DevDeleteDayLogsCard(viewModel = viewModel, appLanguage = appLanguage)
    }

    item {
        DevDeveloperScalesCard(viewModel = viewModel, appLanguage = appLanguage)
    }

    item {
        DevAlarmCenterCard(viewModel = viewModel, appLanguage = appLanguage)
    }

    item {
        DevDeviceFakerCard(viewModel = viewModel, appLanguage = appLanguage)
    }

    item {
        DevLegalDisclaimerTestCard(viewModel = viewModel, appLanguage = appLanguage)
    }

    item {
        DevRecentlyAddedBubbleCard(viewModel = viewModel, appLanguage = appLanguage)
    }

    item {
        DevRainSimulationCard(viewModel = viewModel, appLanguage = appLanguage)
    }

}

@Composable
fun DevDatabaseInspectorCard(
    viewModel: WaterViewModel,
    appLanguage: String,
    isEmailDeveloper: Boolean,
    modifier: Modifier = Modifier
) {
    val allLogs by viewModel.allLogs.collectAsStateWithLifecycle()
    var showWipeConfirm by remember { mutableStateOf(false) }
    var wipeDataInputText by remember { mutableStateOf("") }

    val totalRecords = allLogs.size
    val totalVolumeMl = allLogs.sumOf { it.waterEquivalentMl }
    val averageSip = if (totalRecords > 0) allLogs.map { it.amountMl }.average() else 0.0

    ChunkySettingCard {
        Column(
            modifier = modifier.fillMaxWidth().padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                Icon(
                    imageVector = Icons.Rounded.Android,
                    contentDescription = null,
                    tint = MaterialTheme.colorScheme.tertiary,
                    modifier = Modifier.size(20.dp)
                )
                Text(
                    text = if (appLanguage == "el") "Επιθεώρηση Βάσης Δεδομένων SQLite" else "SQLite Database Inspector",
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = MaterialTheme.colorScheme.onSurface
                )
            }

            // High-Tech Telemetry Stats Grid
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(MaterialTheme.colorScheme.surface.copy(alpha = 0.3f), RoundedCornerShape(12.dp))
                    .padding(8.dp),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.weight(1f)) {
                    Text("Records", fontSize = 10.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
                    Text("$totalRecords", fontSize = 14.sp, fontWeight = FontWeight.Bold)
                }
                Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.weight(1.2f)) {
                    Text("Total Volume", fontSize = 10.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
                    Text("${totalVolumeMl}ml", fontSize = 14.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                }
                Column(horizontalAlignment = Alignment.CenterHorizontally, modifier = Modifier.weight(1f)) {
                    Text("Avg Sip", fontSize = 10.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
                    Text("${averageSip.roundToInt()}ml", fontSize = 14.sp, fontWeight = FontWeight.Bold)
                }
            }

            // Fast Insertion Cheats
            Text(
                text = if (appLanguage == "el") "Γρήγορη Έγχυση 🧩" else "Fast Injection Controls 🧩",
                fontSize = 11.sp,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.primary
            )

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                androidx.compose.material3.Button(
                    onClick = {
                        viewModel.triggerButtonHaptic()
                        viewModel.addWaterLog(2500, "Super Gulp", 1.0f)
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.secondary),
                    shape = RoundedCornerShape(10.dp),
                    modifier = Modifier.weight(1f),
                    contentPadding = PaddingValues(horizontal = 4.dp, vertical = 6.dp)
                ) {
                    Text("+2.5L", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                }

                androidx.compose.material3.Button(
                    onClick = {
                        viewModel.triggerButtonHaptic()
                        viewModel.addWaterLog(10000, "Dev Jetpack", 1.0f)
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.tertiary),
                    shape = RoundedCornerShape(10.dp),
                    modifier = Modifier.weight(1.1f),
                    contentPadding = PaddingValues(horizontal = 4.dp, vertical = 6.dp)
                ) {
                    Text("+10L Jetpack", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                }

                androidx.compose.material3.Button(
                    onClick = {
                        viewModel.triggerButtonHaptic()
                        val cocktails = listOf("Fancy Cocktail 🍹", "Craft Beer 🍺", "Hyper Tonic 🔋", "Dev Coffee ☕")
                        viewModel.addWaterLog((150..600).random(), cocktails.random(), 0.9f)
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary),
                    shape = RoundedCornerShape(10.dp),
                    modifier = Modifier.weight(1.3f),
                    contentPadding = PaddingValues(horizontal = 4.dp, vertical = 6.dp)
                ) {
                    Text("Beer/Cocktail", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                }
            }

            // Logs inspector list
            Text(
                text = if (appLanguage == "el") "Τελευταίες 4 Καταγραφές (Scrollable):" else "Last 4 Hydration Logs (Inspectable):",
                fontSize = 11.sp,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )

            val lastLogs = allLogs.sortedByDescending { it.timestamp }.take(4)
            if (lastLogs.isEmpty()) {
                Text(
                    text = if (appLanguage == "el") "Δεν βρέθηκαν καταγραφές." else "No records found.",
                    fontStyle = androidx.compose.ui.text.font.FontStyle.Italic,
                    fontSize = 11.sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f)
                )
            } else {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(Color.Black.copy(alpha = 0.2f), RoundedCornerShape(10.dp))
                        .padding(6.dp),
                    verticalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    lastLogs.forEach { log ->
                        val date = java.util.Date(log.timestamp)
                        val formattedTime = java.text.SimpleDateFormat("HH:mm", java.util.Locale.getDefault()).format(date)
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .background(MaterialTheme.colorScheme.surface.copy(alpha = 0.15f), RoundedCornerShape(6.dp))
                                .padding(horizontal = 8.dp, vertical = 4.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column {
                                Row(horizontalArrangement = Arrangement.spacedBy(4.dp), verticalAlignment = Alignment.CenterVertically) {
                                    Box(modifier = Modifier.size(6.dp).clip(CircleShape).background(MaterialTheme.colorScheme.primary))
                                    Text(
                                        text = log.beverageType,
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.onSurface
                                    )
                                }
                                Text("Time: $formattedTime | Date: ${log.dateString}", fontSize = 9.sp, color = MaterialTheme.colorScheme.onSurfaceVariant)
                            }
                            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                val amountTextStr = if (log.beverageType.lowercase() != "water" && log.beverageType.lowercase() != "νερό") {
                                    "${log.waterEquivalentMl}ml (${log.amountMl}ml)"
                                } else {
                                    "${log.waterEquivalentMl}ml"
                                }
                                Text(amountTextStr, fontSize = 12.sp, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary)
                                IconButton(
                                    onClick = {
                                        viewModel.triggerButtonHaptic()
                                        viewModel.deleteWaterLog(log)
                                    },
                                    modifier = Modifier.size(24.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Rounded.Close,
                                        contentDescription = "Delete entry",
                                        tint = MaterialTheme.colorScheme.error,
                                        modifier = Modifier.size(14.dp)
                                    )
                                }
                            }
                        }
                    }
                }
            }

            // Wipe database button
            if (showWipeConfirm) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(MaterialTheme.colorScheme.errorContainer.copy(alpha = 0.8f), RoundedCornerShape(12.dp))
                        .padding(10.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Text(
                        text = if (appLanguage == "el") {
                            "Αυτή η ενέργεια θα διαγράψει ΟΛΕΣ τις καταγραφές σας! Πληκτρολογήστε WIPE_DATA για επιβεβαίωση:"
                        } else {
                            "This will delete ALL tracked content! Type WIPE_DATA to confirm:"
                        },
                        color = MaterialTheme.colorScheme.onErrorContainer,
                        fontSize = 11.sp,
                        textAlign = TextAlign.Center,
                        fontWeight = FontWeight.Bold
                    )
                    OutlinedTextField(
                        value = wipeDataInputText,
                        onValueChange = { wipeDataInputText = it },
                        placeholder = { Text("WIPE_DATA", color = MaterialTheme.colorScheme.onErrorContainer.copy(alpha = 0.6f)) },
                        singleLine = true,
                        colors = androidx.compose.material3.OutlinedTextFieldDefaults.colors(
                            focusedBorderColor = MaterialTheme.colorScheme.onErrorContainer,
                            unfocusedBorderColor = MaterialTheme.colorScheme.onErrorContainer.copy(alpha = 0.5f),
                            focusedLabelColor = MaterialTheme.colorScheme.onErrorContainer,
                            unfocusedLabelColor = MaterialTheme.colorScheme.onErrorContainer,
                            cursorColor = MaterialTheme.colorScheme.onErrorContainer
                        ),
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(8.dp)
                    )
                    Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                        androidx.compose.material3.Button(
                            onClick = {
                                viewModel.triggerButtonHaptic()
                                viewModel.restoreRealData() // Wipes database logs
                                showWipeConfirm = false
                                wipeDataInputText = ""
                            },
                            enabled = wipeDataInputText == "WIPE_DATA",
                            colors = ButtonDefaults.buttonColors(
                                containerColor = MaterialTheme.colorScheme.error,
                                disabledContainerColor = MaterialTheme.colorScheme.error.copy(alpha = 0.3f)
                            ),
                            shape = RoundedCornerShape(8.dp),
                            modifier = Modifier.weight(1f)
                        ) {
                            Text(if (appLanguage == "el") "Διαγραφή" else "Wipe Base", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                        }
                        androidx.compose.material3.OutlinedButton(
                            onClick = {
                                viewModel.triggerButtonHaptic()
                                showWipeConfirm = false
                                wipeDataInputText = ""
                            },
                            shape = RoundedCornerShape(8.dp),
                            colors = ButtonDefaults.outlinedButtonColors(contentColor = MaterialTheme.colorScheme.onErrorContainer),
                            modifier = Modifier.weight(1f)
                        ) {
                            Text(if (appLanguage == "el") "Ακύρωση" else "Cancel", fontSize = 11.sp, fontWeight = FontWeight.Bold)
                        }
                    }
                }
            } else {
                androidx.compose.material3.Button(
                    onClick = {
                        viewModel.triggerButtonHaptic()
                        showWipeConfirm = true
                        wipeDataInputText = ""
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.error.copy(alpha = 0.95f)),
                    shape = RoundedCornerShape(12.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Icon(imageVector = Icons.Rounded.Warning, contentDescription = "Wipe", modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(if (appLanguage == "el") "Εκκαθάριση Όλων των Δεδομένων" else "Force Cold Database Wipe", fontWeight = FontWeight.Bold, fontSize = 12.sp)
                }
            }
        }
    }
}

@Composable
fun DevExperimentalUiOptionsCard(
    viewModel: WaterViewModel,
    appLanguage: String,
    modifier: Modifier = Modifier
) {
    val expBlurRadius by viewModel.experimentalBlurRadius.collectAsStateWithLifecycle()
    val isRainbowBorder by viewModel.isRainbowBorderEnabled.collectAsStateWithLifecycle()
    val expBorderWidth by viewModel.experimentalBorderWidth.collectAsStateWithLifecycle()
    val expCardScale by viewModel.experimentalCardScale.collectAsStateWithLifecycle()

    ChunkySettingCard {
        Column(
            modifier = modifier.fillMaxWidth().padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp)
