                onValueChange = { viewModel.updateExperimentalBorderWidth(it) },
                triggerHaptic = { viewModel.triggerSliderHaptic() },
                activeColor = MaterialTheme.colorScheme.primary,
                modifier = Modifier.fillMaxWidth()
            )

            // Card Scale Slider
            ResettableCapsuleSliderRow(
                title = if (appLanguage == "el") "Κλίμακα Καρτών:" else "UI Card Base Scale:",
                value = expCardScale,
                defaultValue = 1.0f,
                valueRange = 0.8f..1.2f,
                onValueChange = { viewModel.updateExperimentalCardScale(it) },
                triggerHaptic = { viewModel.triggerSliderHaptic() },
                activeColor = MaterialTheme.colorScheme.primary,
                modifier = Modifier.fillMaxWidth()
            )

            // Hue Shift Duration Slider
            val expHueShiftDuration by viewModel.experimentalHueShiftDuration.collectAsStateWithLifecycle()
            ResettableCapsuleSliderRow(
                title = if (appLanguage == "el") "Διάρκεια Κύκλου Ουράνιου Τόξου (δευτ):" else "Rainbow Cycle Duration (sec):",
                value = expHueShiftDuration,
                defaultValue = 5.0f,
                valueRange = 0.5f..20.0f,
                onValueChange = { viewModel.updateExperimentalHueShiftDuration(it) },
                triggerHaptic = { viewModel.triggerSliderHaptic() },
                activeColor = MaterialTheme.colorScheme.primary,
                modifier = Modifier.fillMaxWidth()
            )
        }
    }
}

