@Composable
fun DevAlarmCenterCard(
    viewModel: WaterViewModel,
    appLanguage: String,
    modifier: Modifier = Modifier
) {
    val context = androidx.compose.ui.platform.LocalContext.current
    var triggerStatus by remember { mutableStateOf("") }

    ChunkySettingCard {
        Column(
            modifier = modifier.fillMaxWidth().padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                Icon(
                    imageVector = Icons.Rounded.Notifications,
                    contentDescription = null,
                    tint = MaterialTheme.colorScheme.secondary,
                    modifier = Modifier.size(20.dp)
                )
                Text(
                    text = if (appLanguage == "el") "Αποστολή Ειδοποιήσεων Alert System" else "Alert & Notification dispatcher",
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = MaterialTheme.colorScheme.onSurface
                )
            }

            Text(
                text = if (appLanguage == "el")
                    "Δοκιμάστε το σύστημα ειδοποιήσεων άμεσα, αγνοώντας τους χρονοδιακόπτες."
                    else "Fire-test target notification intents immediately without altering your scheduled alarms.",
                fontSize = 11.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.75f)
            )

            // Action button
            androidx.compose.material3.Button(
                onClick = {
                    viewModel.triggerButtonHaptic()
                    try {
                        com.pixelwater.app.notifications.NotificationHelper.showReminderNotification(context)
                        triggerStatus = "Success: Dispatcher alert fired!"
                    } catch (e: Throwable) {
                        triggerStatus = "Error: ${e.localizedMessage}"
                    }
                },
                shape = RoundedCornerShape(12.dp),
                colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary),
                modifier = Modifier.fillMaxWidth()
            ) {
                Icon(imageVector = Icons.Rounded.Notifications, contentDescription = "Fire Alert", modifier = Modifier.size(16.dp))
                Spacer(modifier = Modifier.width(6.dp))
                Text(if (appLanguage == "el") "Άμεση Δοκιμή Ειδοποίησης" else "Trigger Instant Test Alert", fontWeight = FontWeight.Bold)
            }

            if (triggerStatus.isNotEmpty()) {
                Text(
                    text = triggerStatus,
                    fontSize = 10.sp,
                    fontFamily = androidx.compose.ui.text.font.FontFamily.Monospace,
                    color = if (triggerStatus.startsWith("Success")) Color(0xFF66BB6A) else Color(0xFFEF5350),
                    modifier = Modifier.padding(top = 2.dp)
                )
            }
        }
    }
}

