@Composable
fun DevChronoInjectorCard(
    viewModel: WaterViewModel,
    appLanguage: String,
    modifier: Modifier = Modifier
) {
    var amountMl by remember { mutableStateOf(250) }
    var rawBeverage by remember { mutableStateOf("Water") }
    var daysAgo by remember { mutableStateOf(0) }
    var waterEquivalency by remember { mutableStateOf(1.0f) }

    ChunkySettingCard {
        Column(
            modifier = modifier.fillMaxWidth().padding(12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            Row(
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                Icon(
                    imageVector = Icons.Rounded.Autorenew,
                    contentDescription = null,
                    tint = MaterialTheme.colorScheme.primary,
                    modifier = Modifier.size(20.dp)
                )
                Text(
                    text = if (appLanguage == "el") "Chrono-Sync Έγχυση Ιστορικού" else "Chrono-Sync Entry Injector",
                    fontWeight = FontWeight.Bold,
                    fontSize = 14.sp,
                    color = MaterialTheme.colorScheme.onSurface
                )
            }

            Text(
                text = if (appLanguage == "el")
                    "Προσθέστε αναδρομικές καταγραφές στο παρελθόν για να ελέγξετε αλγορίθμους σερί."
                    else "Insert backdated water logs with custom equivalents and offsets to test streak calculations.",
                fontSize = 11.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.75f)
            )

            // Preset values row
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                listOf(150, 250, 500, 1000).forEach { preset ->
                    androidx.compose.material3.FilterChip(
                        selected = amountMl == preset,
                        onClick = {
                            viewModel.triggerButtonHaptic()
                            amountMl = preset
                        },
                        label = { Text("${preset}ml", fontSize = 10.sp, fontWeight = FontWeight.Bold) },
                        modifier = Modifier.weight(1f)
                    )
                }
            }

            // Days ago slider
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Text(
                    text = if (appLanguage == "el") "Ημέρες Πριν:" else "Days Offset:",
                    fontSize = 11.sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    modifier = Modifier.width(75.dp)
                )
                CapsulePatternSlider(
                    value = daysAgo.toFloat(),
                    onValueChange = { daysAgo = it.roundToInt() },
                    valueRange = 0f..14f,
                    triggerHaptic = { viewModel.triggerSliderHaptic() },
                    activeColor = MaterialTheme.colorScheme.primary,
                    modifier = Modifier.weight(1f)
                )
                Text(
                    text = if (daysAgo == 0) "Today" else "-$daysAgo d",
                    fontSize = 11.sp,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.primary,
                    modifier = Modifier.width(50.dp),
                    textAlign = TextAlign.End
                )
            }

            // Water Equivalency Coefficient
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Text(
                    text = if (appLanguage == "el") "Συντελεστής:" else "Efficiency:",
                    fontSize = 11.sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    modifier = Modifier.width(75.dp)
                )
                CapsulePatternSlider(
                    value = waterEquivalency,
                    onValueChange = { waterEquivalency = it },
                    valueRange = 0.1f..1.0f,
                    triggerHaptic = { viewModel.triggerSliderHaptic() },
                    activeColor = MaterialTheme.colorScheme.secondary,
                    modifier = Modifier.weight(1f)
                )
                Text(
                    text = "${String.format(java.util.Locale.US, "%.1f", waterEquivalency)}x",
                    fontSize = 11.sp,
                    fontWeight = FontWeight.Bold,
                    color = MaterialTheme.colorScheme.secondary,
                    modifier = Modifier.width(50.dp),
                    textAlign = TextAlign.End
                )
            }

            // Beverage Type grid
            Text(
                text = "Beverage Type Picker:",
                fontSize = 10.sp,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )

            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                listOf(
                    "Water" to "💧",
                    "Coffee" to "☕",
                    "Brew" to "🍺",
                    "Potion" to "🧪"
                ).forEach { (btype, icon) ->
                    androidx.compose.material3.FilterChip(
                        selected = rawBeverage == btype,
                        onClick = {
                            viewModel.triggerButtonHaptic()
                            rawBeverage = btype
                        },
                        label = { Text("$icon $btype", fontSize = 10.sp, fontWeight = FontWeight.SemiBold) },
                        modifier = Modifier.weight(1f)
                    )
                }
            }

            // Inject action
            val targetDateString = remember(daysAgo) {
                val calendar = java.util.Calendar.getInstance()
                calendar.add(java.util.Calendar.DAY_OF_YEAR, -daysAgo)
                java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.getDefault()).format(calendar.time)
            }

            androidx.compose.material3.Button(
                onClick = {
                    viewModel.triggerButtonHaptic()
                    viewModel.addWaterLogWithCustomDate(
                        amountMl = amountMl,
                        beverageType = rawBeverage,
                        waterEquivalency = waterEquivalency,
                        dateStr = targetDateString,
                        daysAgoOffset = daysAgo
                    )
                },
                shape = RoundedCornerShape(12.dp),
                colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary),
                modifier = Modifier.fillMaxWidth()
            ) {
                Icon(imageVector = Icons.Rounded.Autorenew, contentDescription = "Insert Chrono Log", modifier = Modifier.size(16.dp))
                Spacer(modifier = Modifier.width(6.dp))
                Text(
                    text = if (appLanguage == "el") "Έγχυση ⏱️ $amountMl ml ($targetDateString)" else "Inject ⏱️ $amountMl ml ($targetDateString)",
                    fontWeight = FontWeight.Bold,
                    fontSize = 12.sp
                )
            }
        }
    }
}

@Composable
fun Modifier.withScrollHaptics(viewModel: WaterViewModel): Modifier {
    val scrollHapticsEnabled by viewModel.scrollHapticsEnabled.collectAsStateWithLifecycle()
    val scrollHapticsPixels by viewModel.scrollHapticsPixels.collectAsStateWithLifecycle()
    
    val accumulatedScroll = remember { mutableStateOf(0f) }
    
    val nestedScrollConnection = remember(scrollHapticsEnabled, scrollHapticsPixels) {
        object : NestedScrollConnection {
            override fun onPreScroll(available: Offset, source: NestedScrollSource): Offset {
                if (scrollHapticsEnabled) {
                    val delta = available.y
                    if (delta != 0f) {
                        accumulatedScroll.value += delta
                        if (kotlin.math.abs(accumulatedScroll.value) >= scrollHapticsPixels) {
                            viewModel.triggerScrollHaptic()
                            accumulatedScroll.value = 0f
                        }
                    }
                }
                return Offset.Zero
            }
        }
    }
    
    return this.then(Modifier.nestedScroll(nestedScrollConnection))
}

@Composable
fun DevOptionsSliderRow(
    titlePrefix: String,
    value: Float,
    defaultValue: Float,
    valueRange: ClosedFloatingPointRange<Float>,
    stepsCount: Int = 0,
    onValueChange: (Float) -> Unit,
    triggerHaptic: () -> Unit,
    formatValue: (Float) -> String,
    modifier: Modifier = Modifier
) {
    var isDragged by remember { mutableStateOf(false) }
    val showReset = !isDragged && kotlin.math.abs(value - defaultValue) > 0.001f

    Column(
        modifier = modifier
            .fillMaxWidth()
            .background(MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.35f), RoundedCornerShape(16.dp))
            .padding(14.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Text(
            text = titlePrefix + formatValue(value),
            fontSize = 13.sp,
            fontWeight = FontWeight.ExtraBold,
            color = MaterialTheme.colorScheme.onSurface
        )

        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically
        ) {
            CapsulePatternSlider(
                value = value,
                onValueChange = onValueChange,
                valueRange = valueRange,
                stepsCount = stepsCount,
                triggerHaptic = triggerHaptic,
                onDragStateChange = { isDragged = it },
                modifier = Modifier.weight(1f)
            )

            androidx.compose.animation.AnimatedVisibility(
                visible = showReset,
                enter = androidx.compose.animation.fadeIn() + androidx.compose.animation.expandHorizontally(),
                exit = androidx.compose.animation.fadeOut() + androidx.compose.animation.shrinkHorizontally()
            ) {
                IconButton(
                    onClick = {
                        onValueChange(defaultValue)
                        triggerHaptic()
                    },
                    modifier = Modifier.padding(start = 8.dp).size(36.dp)
                ) {
                    Icon(
                        imageVector = Icons.Rounded.Restore,
                        contentDescription = "Reset to Default",
                        tint = MaterialTheme.colorScheme.primary
                    )
                }
            }
        }
    }
}

