@androidx.compose.runtime.Composable
private fun VerifiedRosetteBadge(
    modifier: Modifier = Modifier,
    tint: Color = Color(0xFF4FE3D6),
    checkMarkColor: Color? = null
) {
    val primaryThemeColor = MaterialTheme.colorScheme.primary
    val finalCheckMarkColor = checkMarkColor ?: primaryThemeColor

    Canvas(
        modifier = modifier
    ) {
        val center = androidx.compose.ui.geometry.Offset(size.width / 2f, size.height / 2f)
        val maxR = size.minDimension / 2f
        val baseRadius = maxR * 0.82f
        val amplitude = maxR * 0.18f
        val path = Path()
        
        val steps = 180
        for (i in 0 until steps) {
            val angle = (i * 2 * Math.PI / steps).toFloat()
            val r = baseRadius + amplitude * kotlin.math.cos(12f * angle)
            val x = center.x + r * kotlin.math.cos(angle)
            val y = center.y + r * kotlin.math.sin(angle)
            if (i == 0) {
                path.moveTo(x, y)
            } else {
                path.lineTo(x, y)
            }
        }
        path.close()
        drawPath(path, color = tint)

        val w = size.width
        val h = size.height
        
        val tickPath = Path()
        tickPath.moveTo(w * 0.32f, h * 0.52f)
        tickPath.lineTo(w * 0.45f, h * 0.65f)
        tickPath.lineTo(w * 0.68f, h * 0.38f)
        
        drawPath(
            path = tickPath,
            color = finalCheckMarkColor,
            style = androidx.compose.ui.graphics.drawscope.Stroke(
                width = 2.4.dp.toPx(),
                cap = androidx.compose.ui.graphics.StrokeCap.Round,
                join = androidx.compose.ui.graphics.StrokeJoin.Round
            )
        )
    }
}

@Composable
fun WorkoutHydrationMeterCanvas(
    modifier: Modifier = Modifier,
    bonusMl: Int,
    color: Color = MaterialTheme.colorScheme.primary,
    isDark: Boolean = false
) {
    val progress = remember { androidx.compose.animation.core.Animatable(0f) }

    LaunchedEffect(bonusMl) {
        progress.animateTo(
            targetValue = 1f,
            animationSpec = androidx.compose.animation.core.tween(durationMillis = 900, easing = androidx.compose.animation.core.FastOutSlowInEasing)
        )
    }

    Box(
        modifier = modifier
            .size(96.dp)
            .background(
                color = color.copy(alpha = if (isDark) 0.15f else 0.1f),
                shape = CircleShape
            ),
        contentAlignment = Alignment.Center
    ) {
        androidx.compose.foundation.Canvas(modifier = Modifier.fillMaxSize().padding(8.dp)) {
            val strokeWidth = 7.dp.toPx()
            val radius = (size.minDimension - strokeWidth) / 2f
            val center = androidx.compose.ui.geometry.Offset(size.width / 2f, size.height / 2f)

            drawCircle(
                color = color.copy(alpha = 0.2f),
                radius = radius,
                center = center,
                style = androidx.compose.ui.graphics.drawscope.Stroke(width = strokeWidth)
            )

            val sweepAngle = progress.value * 280f
            drawArc(
                color = color,
                startAngle = 130f,
                sweepAngle = sweepAngle,
                useCenter = false,
                topLeft = androidx.compose.ui.geometry.Offset(center.x - radius, center.y - radius),
                size = androidx.compose.ui.geometry.Size(radius * 2f, radius * 2f),
                style = androidx.compose.ui.graphics.drawscope.Stroke(
                    width = strokeWidth,
                    cap = androidx.compose.ui.graphics.StrokeCap.Round
                )
            )
        }

        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            Text(
                text = "+$bonusMl",
                fontSize = 15.sp,
                fontWeight = FontWeight.Black,
                color = color
            )
            Text(
                text = "ml",
                fontSize = 10.sp,
                fontWeight = FontWeight.Bold,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
        }
    }
}

